(383372,42597,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O dün gövdeyi çok hızlı kesmiş olsaydı, ayı şimdi kırık ...'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'O dün gövdeyi çok hızlı kesmiş olsaydı, ayı şimdi kırık olurdu.'::text),
(383373,42597,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ő tegnap túl gyorsan fűrészelte volna a törzset, a medve most törött ...'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha ő tegnap túl gyorsan fűrészelte volna a törzset, a medve most törött lenne.'::text),
(362766,40308,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dir macht es sichtlich Spaß, dieses Hemd zu ..., und ehrlich, man sieht''s.'::text,'bügeln'::text,'bügeln'::text,'bügeln'::text,'Dir macht es sichtlich Spaß, dieses Hemd zu bügeln, und ehrlich, man sieht''s.'::text),
(362770,40308,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти явно любиш ... цю сорочку, і чесно, це видно.'::text,'прасувати'::text,'прасувати'::text,'прасувати'::text,'Ти явно любиш прасувати цю сорочку, і чесно, це видно.'::text),
(362769,40308,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú claramente disfrutas ... esa camisa, y la verdad se nota.'::text,'planchando'::text,'planchar'::text,'planchar'::text,'Tú claramente disfrutas planchando esa camisa, y la verdad se nota.'::text),
(362768,40308,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu aimes clairement ... cette chemise, et honnêtement, ça se voit.'::text,'repasser'::text,'repasser'::text,'repasser'::text,'Tu aimes clairement repasser cette chemise, et honnêtement, ça se voit.'::text),
(362771,40308,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen o gömleği ... resmen bayılıyorsun, açıkçası belli oluyor.'::text,'ütülemeye'::text,'ütülemeye'::text,'ütülemeye'::text,'Sen o gömleği ütülemeye resmen bayılıyorsun, açıkçası belli oluyor.'::text),
(362772,40308,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te láthatóan élvezed ... azt az inget, és őszintén, látszik is.'::text,'vasalni'::text,'vasalni'::text,'vasalni'::text,'Te láthatóan élvezed vasalni azt az inget, és őszintén, látszik is.'::text),
(362793,40311,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die zwei Frauen ... das Laken eine Stunde lang, bevor es endlich glatt war.'::text,'bügelten'::text,'bügeln'::text,'bügelten'::text,'Die zwei Frauen bügelten das Laken eine Stunde lang, bevor es endlich glatt war.'::text),
(362797,40311,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дві жінки ... простирадло годину, перш ніж воно нарешті стало гладким.'::text,'прасували'::text,'прасують'::text,'прасували'::text,'Дві жінки прасували простирадло годину, перш ніж воно нарешті стало гладким.'::text),
(362796,40311,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las dos mujeres ... la sábana durante una hora antes de que por fin quedara lisa.'::text,'habían estado planchando'::text,'han estado planchando'::text,'estaban planchando'::text,'Las dos mujeres habían estado planchando la sábana durante una hora antes de que por fin quedara lisa.'::text),
(362795,40311,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux femmes ... le drap pendant une heure avant qu''il soit enfin lisse.'::text,'repassaient'::text,'repassent'::text,'repassaient'::text,'Les deux femmes repassaient le drap pendant une heure avant qu''il soit enfin lisse.'::text),
(362798,40311,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki kadın, çarşaf sonunda dümdüz olana kadar bir saat boyunca onu ...'::text,'ütülemişlerdi'::text,'ütülüyorlar'::text,'ütülüyorlardı'::text,'İki kadın, çarşaf sonunda dümdüz olana kadar bir saat boyunca onu ütülemişlerdi.'::text),
(362799,40311,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A két nő egy órán át ... a lepedőt, mire végre sima lett.'::text,'vasalta'::text,'vasalja'::text,'vasalta'::text,'A két nő egy órán át vasalta a lepedőt, mire végre sima lett.'::text),
(357861,39763,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Von allen Teilen der Maschine war ..., das er zuletzt einbaute, das größte.'::text,'das Zahnrad'::text,'ein Zahnrad'::text,'Zahnrad'::text,'Von allen Teilen der Maschine war das Zahnrad, das er zuletzt einbaute, das größte.'::text),
(357865,39763,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'З усіх деталей у машині ..., яке він встановив останнім, було найбільшим.'::text,'зубчасте колесо'::text,'зубчасте колесо'::text,'зубчасте колесо'::text,'З усіх деталей у машині зубчасте колесо, яке він встановив останнім, було найбільшим.'::text),
(357864,39763,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De todas las piezas de la máquina, ... que montó al final era el más grande.'::text,'el engranaje'::text,'un engranaje'::text,'engranaje'::text,'De todas las piezas de la máquina, el engranaje que montó al final era el más grande.'::text),
(357863,39763,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De toutes les pièces de la machine, ... qu''il a montée en dernier était la plus grande.'::text,'la roue dentée'::text,'une roue dentée'::text,'roue dentée'::text,'De toutes les pièces de la machine, la roue dentée qu''il a montée en dernier était la plus grande.'::text),
(357866,39763,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makinedeki tüm parçalar içinde en son taktığı ... en büyüğüydü.'::text,'dişli'::text,'bir dişli'::text,'dişli'::text,'Makinedeki tüm parçalar içinde en son taktığı dişli en büyüğüydü.'::text),
(357867,39763,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gép összes alkatrésze közül ..., amelyet utoljára szerelt be, volt a legnagyobb.'::text,'a fogaskerék'::text,'egy fogaskerék'::text,'fogaskerék'::text,'A gép összes alkatrésze közül a fogaskerék, amelyet utoljára szerelt be, volt a legnagyobb.'::text),
(396939,44105,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, sie ... schon seit zehn Jahren so winzige Zahnräder.'::text,'repariert'::text,'repariert'::text,'repariert'::text,'Bestie, ich hab gehört, sie repariert schon seit zehn Jahren so winzige Zahnräder.'::text),
(396943,44105,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що вона ... такі крихітні шестерні вже десять років.'::text,'ремонтує'::text,'ремонтує'::text,'ремонтує'::text,'Подруго, я чула, що вона ремонтує такі крихітні шестерні вже десять років.'::text),
(396942,44105,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, he oído que ella ... engranajes diminutos como estos desde hace diez años.'::text,'ha estado reparando'::text,'está reparando'::text,'repara'::text,'Amiga, he oído que ella ha estado reparando engranajes diminutos como estos desde hace diez años.'::text),
(396941,44105,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, j''ai entendu dire qu''elle ... des rouages minuscules comme ça depuis dix ans.'::text,'répare'::text,'est en train de réparer'::text,'répare'::text,'Bestie, j''ai entendu dire qu''elle répare des rouages minuscules comme ça depuis dix ans.'::text),
(396944,44105,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duydum ki o on yıldır böyle minik dişlileri ...'::text,'tamir ediyormuş'::text,'tamir ediyor'::text,'tamir eder'::text,'Kanka, duydum ki o on yıldır böyle minik dişlileri tamir ediyormuş.'::text),
(396945,44105,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, úgy hallottam, ő tíz éve ... ilyen apró fogaskerekeket.'::text,'javít'::text,'javít'::text,'javít'::text,'Csajszi, úgy hallottam, ő tíz éve javít ilyen apró fogaskerekeket.'::text),
(396984,44110,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie arbeitet ... des so winzigen Zahnrads mit einer Lupe.'::text,'aufgrund'::text,'trotz'::text,'weil'::text,'Sie arbeitet aufgrund des so winzigen Zahnrads mit einer Lupe.'::text),
(396988,44110,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона працює з лупою ... те, що шестерня така крихітна.'::text,'через'::text,'попри'::text,'бо'::text,'Вона працює з лупою через те, що шестерня така крихітна.'::text),
(396987,44110,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella trabaja con una lupa ... que el engranaje es tan diminuto.'::text,'debido a'::text,'a pesar de'::text,'porque'::text,'Ella trabaja con una lupa debido a que el engranaje es tan diminuto.'::text),
(396986,44110,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle travaille à la loupe ... la taille minuscule du rouage.'::text,'en raison de'::text,'malgré'::text,'parce que'::text,'Elle travaille à la loupe en raison de la taille minuscule du rouage.'::text),
(396989,44110,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, dişli çok küçük olduğu ... büyüteçle çalışıyor.'::text,'için'::text,'halde'::text,'çünkü'::text,'O, dişli çok küçük olduğu için büyüteçle çalışıyor.'::text),
(396990,44110,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő nagyítóval dolgozik, ... a fogaskerék olyan apró.'::text,'mivel'::text,'annak ellenére, hogy'::text,'mert'::text,'Ő nagyítóval dolgozik, mivel a fogaskerék olyan apró.'::text),
(390675,43409,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die ganze Spirale ... an einem einzigen Tag von nur einem Mann aufgebaut. Klar, ein schneller Job.'::text,'wurde'::text,'wird'::text,'hat'::text,'Die ganze Spirale wurde an einem einzigen Tag von nur einem Mann aufgebaut. Klar, ein schneller Job.'::text),
(390679,43409,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уся спіраль ... за один день лише одним чоловіком. Явно швидка робота.'::text,'була викладена'::text,'викладається'::text,'виклав'::text,'Уся спіраль була викладена за один день лише одним чоловіком. Явно швидка робота.'::text),
(390678,43409,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toda la espiral ... en un solo día por un solo hombre. Un trabajo rapidito, claro.'::text,'fue montada'::text,'es montada'::text,'montó'::text,'Toda la espiral fue montada en un solo día por un solo hombre. Un trabajo rapidito, claro.'::text),
(390677,43409,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toute la spirale ... en une seule journée par un seul homme. Clairement un petit boulot rapide.'::text,'a été montée'::text,'est montée'::text,'a monté'::text,'Toute la spirale a été montée en une seule journée par un seul homme. Clairement un petit boulot rapide.'::text),
(390680,43409,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün spiral, tek bir günde ve tek bir adam tarafından ...; belli ki hızlı bir iş.'::text,'kuruldu'::text,'kuruluyor'::text,'kurdu'::text,'Bütün spiral, tek bir günde ve tek bir adam tarafından kuruldu; belli ki hızlı bir iş.'::text),
(390681,43409,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egész spirál egyetlen nap alatt ... egyetlen ember által. Nyilván gyors meló.'::text,'lett felállítva'::text,'van felállítva'::text,'felállított'::text,'Az egész spirál egyetlen nap alatt lett felállítva egyetlen ember által. Nyilván gyors meló.'::text),
(390747,43417,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... seit Stunden an dieser Spirale, und das sieht man. Respekt.'::text,'arbeitest'::text,'arbeitest'::text,'arbeitest'::text,'Du arbeitest seit Stunden an dieser Spirale, und das sieht man. Respekt.'::text),
(390751,43417,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... над цією спіраллю вже кілька годин, і це видно. Респект.'::text,'працюєш'::text,'працюєш'::text,'працюєш'::text,'Ти працюєш над цією спіраллю вже кілька годин, і це видно. Респект.'::text),
(390750,43417,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... en esa espiral durante horas, y se nota. Respeto.'::text,'has estado trabajando'::text,'estás trabajando'::text,'trabajas'::text,'Tú has estado trabajando en esa espiral durante horas, y se nota. Respeto.'::text),
(390749,43417,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... sur cette spirale depuis des heures, et ça se voit. Respect.'::text,'travailles'::text,'es en train de travailler'::text,'travailles'::text,'Tu travailles sur cette spirale depuis des heures, et ça se voit. Respect.'::text),
(390752,43417,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen saatlerdir o spiral üzerinde ..., belli oluyor. Helal.'::text,'çalışıyorsun'::text,'çalışıyorsun'::text,'çalışırsın'::text,'Sen saatlerdir o spiral üzerinde çalışıyorsun, belli oluyor. Helal.'::text),
(390753,43417,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te órák óta ... azon a spirálon, és látszik. Respekt.'::text,'dolgozol'::text,'dolgozol'::text,'dolgozol'::text,'Te órák óta dolgozol azon a spirálon, és látszik. Respekt.'::text),
(336603,37401,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du liebst ein gutes Blasenexperiment, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Ehrlich, du liebst ein gutes Blasenexperiment, oder?'::text),
(336607,37401,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти обожнюєш класний експеримент із бульбашками, ...?'::text,'так?'::text,'так?'::text,'так?'::text,'Чесно, ти обожнюєш класний експеримент із бульбашками, так?'::text),
(336606,37401,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, tú adoras un buen experimento con burbujas, ¿...'::text,'verdad?'::text,'verdad?'::text,'verdad?'::text,'La verdad, tú adoras un buen experimento con burbujas, ¿verdad?'::text),
(336605,37401,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Honnêtement, tu adores une bonne expérience avec des bulles, ...'::text,'non ?'::text,'non ?'::text,'non ?'::text,'Honnêtement, tu adores une bonne expérience avec des bulles, non ?'::text),
(336608,37401,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen güzel bir baloncuk deneyine bayılıyorsun, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Açıkçası sen güzel bir baloncuk deneyine bayılıyorsun, değil mi?'::text),
(336609,37401,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te imádsz egy jó buborékos kísérletet, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Őszintén, te imádsz egy jó buborékos kísérletet, ugye?'::text),
(336621,37403,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, bis zum Ende des Tages ... du in diesem Tank tausend Blasen gemacht haben.'::text,'wirst'::text,'wirst'::text,'wirst'::text,'Ehrlich, bis zum Ende des Tages wirst du in diesem Tank tausend Blasen gemacht haben.'::text),
(336625,37403,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, до кінця дня ти ... тисячу бульбашок у цьому резервуарі.'::text,'зробиш'::text,'зробиш'::text,'робитимеш'::text,'Чесно, до кінця дня ти зробиш тисячу бульбашок у цьому резервуарі.'::text),
(336624,37403,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, para el final del día tú ... mil burbujas en ese tanque.'::text,'habrás hecho'::text,'harás'::text,'estarás haciendo'::text,'La verdad, para el final del día tú habrás hecho mil burbujas en ese tanque.'::text),
(336623,37403,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Honnêtement, d''ici la fin de la journée, tu ... mille bulles dans ce bac.'::text,'auras fait'::text,'feras'::text,'seras en train de faire'::text,'Honnêtement, d''ici la fin de la journée, tu auras fait mille bulles dans ce bac.'::text),
(336626,37403,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, gün sonuna kadar sen o tankta bin baloncuk ...'::text,'yapmış olacaksın'::text,'yapacaksın'::text,'yapıyor olacaksın'::text,'Açıkçası, gün sonuna kadar sen o tankta bin baloncuk yapmış olacaksın.'::text),
(336627,37403,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, mire vége a napnak, te ... ezer buborékot abban a tartályban.'::text,'csinálsz'::text,'csinálsz'::text,'fogsz csinálni'::text,'Őszintén, mire vége a napnak, te csinálsz ezer buborékot abban a tartályban.'::text),
(365223,40581,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das lange Objektiv ... für 2.000 Euro aus dem Budget des letzten Jahres gekauft.'::text,'wurde'::text,'hat'::text,'wird'::text,'Das lange Objektiv wurde für 2.000 Euro aus dem Budget des letzten Jahres gekauft.'::text),
(365227,40581,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Довгий об''єктив ... за 2 000 євро з торішнього бюджету.'::text,'був куплений'::text,'купив'::text,'купується'::text,'Довгий об''єктив був куплений за 2 000 євро з торішнього бюджету.'::text),
(365226,40581,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El objetivo largo ... por 2.000 euros del presupuesto del año pasado.'::text,'fue comprado'::text,'compró'::text,'es comprado'::text,'El objetivo largo fue comprado por 2.000 euros del presupuesto del año pasado.'::text),
(365225,40581,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''objectif long ... pour 2 000 euros sur le budget de l''an dernier.'::text,'a été acheté'::text,'a acheté'::text,'est acheté'::text,'L''objectif long a été acheté pour 2 000 euros sur le budget de l''an dernier.'::text),
(365228,40581,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uzun lens geçen yılın bütçesinden 2.000 euroya ...'::text,'satın alındı'::text,'satın aldı'::text,'satın alınıyor'::text,'Uzun lens geçen yılın bütçesinden 2.000 euroya satın alındı.'::text),
(365229,40581,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hosszú objektívet ... 2000 euróért a tavalyi keretből.'::text,'megvették'::text,'megvette'::text,'megveszik'::text,'A hosszú objektívet megvették 2000 euróért a tavalyi keretből.'::text),
(365250,40584,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende der Nacht ... er Hunderte Fotos mit diesem Objektiv gemacht haben.'::text,'wird'::text,'wird'::text,'macht'::text,'Bis zum Ende der Nacht wird er Hunderte Fotos mit diesem Objektiv gemacht haben.'::text),
(365254,40584,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця ночі він ... сотні фото через цей об''єктив.'::text,'зробить'::text,'зробить'::text,'робить'::text,'До кінця ночі він зробить сотні фото через цей об''єктив.'::text),
(365253,40584,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final de la noche, él ... cientos de fotos con este objetivo.'::text,'habrá hecho'::text,'hará'::text,'hace'::text,'Para el final de la noche, él habrá hecho cientos de fotos con este objetivo.'::text),
(365252,40584,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de la nuit, il ... des centaines de photos avec cet objectif.'::text,'aura pris'::text,'prendra'::text,'prend'::text,'D''ici la fin de la nuit, il aura pris des centaines de photos avec cet objectif.'::text),
(365255,40584,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gecenin sonuna kadar o, bu lensle yüzlerce fotoğraf ...'::text,'çekmiş olacak'::text,'çekecek'::text,'çekiyor'::text,'Gecenin sonuna kadar o, bu lensle yüzlerce fotoğraf çekmiş olacak.'::text),
(365256,40584,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az éjszaka végére ő ... több száz fotót ezzel az objektívvel.'::text,'elkészít'::text,'el fog készíteni'::text,'készít'::text,'Az éjszaka végére ő elkészít több száz fotót ezzel az objektívvel.'::text),
(349293,38811,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... die Drohne so geschmeidig, als die Crew anfing zu klatschen.'::text,'steuertest'::text,'steuertest'::text,'hast gesteuert'::text,'Ehrlich, du steuertest die Drohne so geschmeidig, als die Crew anfing zu klatschen.'::text),
(349297,38811,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... дрон так плавно, коли знімальна група почала аплодувати.'::text,'керував'::text,'керував'::text,'покерував'::text,'Чесно, ти керував дрон так плавно, коли знімальна група почала аплодувати.'::text),
(349296,38811,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, tú ... el dron con tanta suavidad cuando el equipo empezó a aplaudir.'::text,'pilotabas'::text,'pilotaste'::text,'has pilotado'::text,'La verdad, tú pilotabas el dron con tanta suavidad cuando el equipo empezó a aplaudir.'::text),
(349295,38811,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Honnêtement, tu ... le drone avec tellement de fluidité quand l''équipe a commencé à applaudir.'::text,'pilotais'::text,'as piloté'::text,'as piloté'::text,'Honnêtement, tu pilotais le drone avec tellement de fluidité quand l''équipe a commencé à applaudir.'::text),
(349298,38811,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, ekip alkışlamaya başladığında sen dronu öyle akıcı ...'::text,'uçuruyordun'::text,'uçurdun'::text,'uçurdun'::text,'Açıkçası, ekip alkışlamaya başladığında sen dronu öyle akıcı uçuruyordun.'::text),
(349299,38811,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te olyan simán ... a drónt, amikor a stáb tapsolni kezdett.'::text,'irányítottad'::text,'irányítottad'::text,'irányítottad'::text,'Őszintén, te olyan simán irányítottad a drónt, amikor a stáb tapsolni kezdett.'::text),
(349356,38818,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Drohne, ... Propeller das Gras plattdrücken, hebt über dem Feld ab.'::text,'deren'::text,'die'::text,'die'::text,'Die Drohne, deren Propeller das Gras plattdrücken, hebt über dem Feld ab.'::text),
(349360,38818,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дрон, ... пропелери притискають траву, злітає над полем.'::text,'чиї'::text,'який'::text,'що'::text,'Дрон, чиї пропелери притискають траву, злітає над полем.'::text),
(349359,38818,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El dron, ... hélices aplastan la hierba, despega sobre el campo.'::text,'cuyas'::text,'que'::text,'el cual'::text,'El dron, cuyas hélices aplastan la hierba, despega sobre el campo.'::text),
(349358,38818,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le drone, ... les hélices aplatissent l''herbe, décolle au-dessus du champ.'::text,'dont'::text,'qui'::text,'que'::text,'Le drone, dont les hélices aplatissent l''herbe, décolle au-dessus du champ.'::text),
(349361,38818,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pervaneleri ... çimi yere yatıran dron, tarlanın üzerinde havalanıyor.'::text,''::text,NULL::text,NULL::text,'Pervaneleri çimi yere yatıran dron, tarlanın üzerinde havalanıyor.'::text),
(349362,38818,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A drón, ... propellerei lelapítják a füvet, felemelkedik a mező fölé.'::text,'amelynek a'::text,'amely'::text,'amelyik'::text,'A drón, amelynek a propellerei lelapítják a füvet, felemelkedik a mező fölé.'::text),
(396561,44063,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat zwei Daumen, weil sie zwei Hände hat, und ...'::text,'der Sänger auch.'::text,'der Sänger auch.'::text,'der Sänger auch.'::text,'Sie hat zwei Daumen, weil sie zwei Hände hat, und der Sänger auch.'::text),
(396565,44063,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона має два великі пальці, бо має дві руки, і ...'::text,'співак теж.'::text,'співак теж.'::text,'співак теж.'::text,'Вона має два великі пальці, бо має дві руки, і співак теж.'::text),
(396564,44063,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella tiene dos pulgares porque tiene dos manos, y ...'::text,'el cantante también.'::text,'el cantante también.'::text,'el cantante también.'::text,'Ella tiene dos pulgares porque tiene dos manos, y el cantante también.'::text),
(396563,44063,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a deux pouces parce qu''elle a deux mains, et ...'::text,'le chanteur aussi.'::text,'le chanteur aussi.'::text,'le chanteur aussi.'::text,'Elle a deux pouces parce qu''elle a deux mains, et le chanteur aussi.'::text),
(396566,44063,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, iki eli olduğu için iki başparmağa sahip, ve ...'::text,'şarkıcı da öyle.'::text,'şarkıcı da öyle.'::text,'şarkıcı da öyle.'::text,'O, iki eli olduğu için iki başparmağa sahip, ve şarkıcı da öyle.'::text),
(396567,44063,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neki két hüvelykujja van, mert két keze van, és ...'::text,'az énekesnek is.'::text,'az énekesnek is.'::text,'az énekesnek is.'::text,'Neki két hüvelykujja van, mert két keze van, és az énekesnek is.'::text),
(396597,44067,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Daumen füllen das ganze Bild, also ... sie sehr nah an der Kamera gesessen haben.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Ihre Daumen füllen das ganze Bild, also muss sie sehr nah an der Kamera gesessen haben.'::text),
(396601,44067,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її пальці заповнюють увесь кадр, тож вона ... сидіти дуже близько до камери.'::text,'мусила'::text,'не могла'::text,'мала б'::text,'Її пальці заповнюють увесь кадр, тож вона мусила сидіти дуже близько до камери.'::text),
(396600,44067,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus pulgares llenan el encuadre, así que ella ... estado sentada muy cerca de la cámara.'::text,'debe de haber'::text,'no puede haber'::text,'debería haber'::text,'Sus pulgares llenan el encuadre, así que ella debe de haber estado sentada muy cerca de la cámara.'::text),
(396599,44067,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses pouces remplissent le cadre, donc elle ... être assise très près de la caméra.'::text,'a dû'::text,'n''a pas pu'::text,'aurait dû'::text,'Ses pouces remplissent le cadre, donc elle a dû être assise très près de la caméra.'::text),
(396602,44067,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başparmakları kadrajı dolduruyor, yani o kameraya çok yakın ...'::text,'oturuyor olmalı'::text,'oturuyor olamaz'::text,'oturmalıydı'::text,'Başparmakları kadrajı dolduruyor, yani o kameraya çok yakın oturuyor olmalı.'::text),
(396603,44067,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hüvelykujjai kitöltik a képet, szóval ő ... nagyon közel a kamerához.'::text,'biztosan ült'::text,'nem ülhetett'::text,'ülnie kellett volna'::text,'A hüvelykujjai kitöltik a képet, szóval ő biztosan ült nagyon közel a kamerához.'::text),
(377085,41899,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... spät in der Nacht, als er Student war.'::text,'programmierte oft'::text,'programmierte früher'::text,'war es gewohnt zu programmieren'::text,'Er programmierte oft spät in der Nacht, als er Student war.'::text),
(377089,41899,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... пізно вночі, коли був студентом.'::text,'програмував'::text,'програмував'::text,'звик програмувати'::text,'Він програмував пізно вночі, коли був студентом.'::text),
(377088,41899,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... hasta tarde por la noche cuando era estudiante.'::text,'programaba'::text,'solía programar'::text,'estaba acostumbrado a programar'::text,'Él programaba hasta tarde por la noche cuando era estudiante.'::text),
(377087,41899,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... tard le soir quand il était étudiant.'::text,'programmait'::text,'avait l''habitude de programmer'::text,'était habitué à programmer'::text,'Il programmait tard le soir quand il était étudiant.'::text),
(377090,41899,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O öğrenciyken gece geç saatlere kadar ...'::text,'program yazardı'::text,'program yazardı'::text,'program yazmaya alışkındı'::text,'O öğrenciyken gece geç saatlere kadar program yazardı.'::text),
(377091,41899,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... késő éjjel, amikor diák volt.'::text,'programozott'::text,'programozni szokott'::text,'hozzá volt szokva a programozáshoz'::text,'Ő programozott késő éjjel, amikor diák volt.'::text),
(377130,41904,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, die ... wochenlang an der App, bevor endlich der grüne Haken kam, echt jetzt.'::text,'programmierten'::text,'programmierten'::text,'haben programmiert'::text,'Bro, die programmierten wochenlang an der App, bevor endlich der grüne Haken kam, echt jetzt.'::text),
(377134,41904,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вони ... цей застосунок тижнями, поки нарешті не з''явилася зелена галочка, реально.'::text,'програмували'::text,'програмували'::text,'запрограмували'::text,'Бро, вони програмували цей застосунок тижнями, поки нарешті не з''явилася зелена галочка, реально.'::text),
(377133,41904,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ellos ... esa app durante semanas antes de que por fin saliera el check verde, en serio.'::text,'habían estado programando'::text,'estaban programando'::text,'han programado'::text,'Bro, ellos habían estado programando esa app durante semanas antes de que por fin saliera el check verde, en serio.'::text),
(377132,41904,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ils ... cette appli pendant des semaines avant que la coche verte apparaisse enfin, sérieux.'::text,'avaient programmé'::text,'programmaient'::text,'ont programmé'::text,'Frère, ils avaient programmé cette appli pendant des semaines avant que la coche verte apparaisse enfin, sérieux.'::text),
(377135,41904,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onlar yeşil tik sonunda çıkana kadar haftalarca o uygulamayı ..., cidden.'::text,'kodlamışlardı'::text,'kodluyorlardı'::text,'kodladılar'::text,'Kanka, onlar yeşil tik sonunda çıkana kadar haftalarca o uygulamayı kodlamışlardı, cidden.'::text),
(377136,41904,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ők hetekig ... azt az appot, mire végre megjelent a zöld pipa, komolyan.'::text,'programozták'::text,'programozták'::text,'leprogramozták'::text,'Tesó, ők hetekig programozták azt az appot, mire végre megjelent a zöld pipa, komolyan.'::text),
(355179,39465,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während er sich den Schaum von der Wange ..., schlug ihm das Herz bis zum Hals!'::text,'rasierte'::text,'rasierte'::text,'hat rasiert'::text,'Während er sich den Schaum von der Wange rasierte, schlug ihm das Herz bis zum Hals!'::text),
(355183,39465,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він ... піну зі щоки, серце в нього було просто в п''ятах!'::text,'збривав'::text,'збрив'::text,'збрив'::text,'Поки він збривав піну зі щоки, серце в нього було просто в п''ятах!'::text),
(355182,39465,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mientras él se ... la espuma de la mejilla, tenía el corazón en un puño!'::text,'afeitaba'::text,'afeitó'::text,'ha afeitado'::text,'¡Mientras él se afeitaba la espuma de la mejilla, tenía el corazón en un puño!'::text),
(355181,39465,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''il ... la mousse de sa joue, son cœur battait la chamade !'::text,'rasait'::text,'rasa'::text,'a rasé'::text,'Pendant qu''il rasait la mousse de sa joue, son cœur battait la chamade !'::text),
(355184,39465,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yanağındaki köpüğü ..., kalbi resmen ağzına gelmişti!'::text,'tıraş ederken'::text,'tıraş etti'::text,'tıraş etmiş'::text,'O yanağındaki köpüğü tıraş ederken, kalbi resmen ağzına gelmişti!'::text),
(355185,39465,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ő ... a habot az arcáról, a szíve a torkában dobogott!'::text,'borotválta'::text,'leborotválta'::text,'leborotválta'::text,'Miközben ő borotválta a habot az arcáról, a szíve a torkában dobogott!'::text),
(355260,39474,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... dem Schaum hinterließ das Rasiermesser einen sauberen Streifen auf seiner Wange.'::text,'Dank'::text,'Trotz'::text,'Im Fall von'::text,'Dank dem Schaum hinterließ das Rasiermesser einen sauberen Streifen auf seiner Wange.'::text),
(355264,39474,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... піні бритва залишила чисту смугу на його щоці.'::text,'Завдяки'::text,'Попри'::text,'У разі'::text,'Завдяки піні бритва залишила чисту смугу на його щоці.'::text),
(355263,39474,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la espuma, la navaja dejó una franja limpia en su mejilla.'::text,'Gracias a'::text,'A pesar de'::text,'En caso de'::text,'Gracias a la espuma, la navaja dejó una franja limpia en su mejilla.'::text),
(355262,39474,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la mousse, le rasoir a laissé une bande nette sur sa joue.'::text,'Grâce à'::text,'Malgré'::text,'En cas de'::text,'Grâce à la mousse, le rasoir a laissé une bande nette sur sa joue.'::text),
(355265,39474,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpük ..., ustura yanağında temiz bir şerit bıraktı.'::text,'sayesinde'::text,'rağmen'::text,'durumunda'::text,'Köpük sayesinde, ustura yanağında temiz bir şerit bıraktı.'::text),
(355266,39474,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hab ..., a borotva tiszta csíkot hagyott az arcán.'::text,'miatt'::text,'ellenére'::text,'esetén'::text,'A hab miatt, a borotva tiszta csíkot hagyott az arcán.'::text),
(379722,42192,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Team an der Anmeldung ... bisher über 500 Namensschilder gedruckt.'::text,'hat'::text,'hat'::text,'druckte'::text,'Das Team an der Anmeldung hat bisher über 500 Namensschilder gedruckt.'::text),
(379726,42192,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Персонал на реєстрації ... вже понад 500 бейджів.'::text,'надрукував'::text,'друкував'::text,'надрукував'::text,'Персонал на реєстрації надрукував вже понад 500 бейджів.'::text),
(379725,42192,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El personal ... más de 500 acreditaciones en el registro hasta ahora.'::text,'ha impreso'::text,'ha estado imprimiendo'::text,'imprimió'::text,'El personal ha impreso más de 500 acreditaciones en el registro hasta ahora.'::text),
(379724,42192,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le personnel ... plus de 500 badges à l''accueil jusqu''ici.'::text,'a imprimé'::text,'imprime'::text,'imprima'::text,'Le personnel a imprimé plus de 500 badges à l''accueil jusqu''ici.'::text),
(379727,42192,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Görevliler kayıt masasında şimdiye kadar 500''den fazla isim kartı ...'::text,'bastı'::text,'basıyor'::text,'bastı'::text,'Görevliler kayıt masasında şimdiye kadar 500''den fazla isim kartı bastı.'::text),
(379728,42192,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A személyzet eddig több mint 500 névkártyát ... a regisztrációnál.'::text,'nyomtatott ki'::text,'nyomtatott'::text,'nyomtatott ki'::text,'A személyzet eddig több mint 500 névkártyát nyomtatott ki a regisztrációnál.'::text),
(379776,42198,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Anmeldung war ... der endlosen Schlange in zehn Minuten vorbei! Absolut unglaublich!'::text,'trotz'::text,'wegen'::text,'obwohl'::text,'Die Anmeldung war trotz der endlosen Schlange in zehn Minuten vorbei! Absolut unglaublich!'::text),
(379780,42198,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Реєстрація закінчилася за десять хвилин ... нескінченну чергу! Просто неймовірно!'::text,'попри'::text,'через'::text,'хоча'::text,'Реєстрація закінчилася за десять хвилин попри нескінченну чергу! Просто неймовірно!'::text),
(379779,42198,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El registro terminó en diez minutos ... la cola interminable! ¡Absolutamente increíble!'::text,'a pesar de'::text,'por'::text,'aunque'::text,'¡El registro terminó en diez minutos a pesar de la cola interminable! ¡Absolutamente increíble!'::text),
(379778,42198,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''enregistrement s''est terminé en dix minutes ... la file interminable ! Absolument incroyable !'::text,'malgré'::text,'à cause de'::text,'bien que'::text,'L''enregistrement s''est terminé en dix minutes malgré la file interminable ! Absolument incroyable !'::text),
(379781,42198,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kayıt, uçsuz bucaksız kuyruğa ... on dakikada bitti! İnanılmaz!'::text,'rağmen'::text,'yüzünden'::text,'gerçi'::text,'Kayıt, uçsuz bucaksız kuyruğa rağmen on dakikada bitti! İnanılmaz!'::text),
(379782,42198,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A regisztráció a végtelen sor ... tíz perc alatt véget ért! Hihetetlen!'::text,'ellenére'::text,'miatt'::text,'bár'::text,'A regisztráció a végtelen sor ellenére tíz perc alatt véget ért! Hihetetlen!'::text),
(393609,43735,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie kann das ... weiterer Bücher für ihr Studium nicht lassen. Eine winzige Leseliste, ganz klar.'::text,'Hinzufügen'::text,'hinzuzufügen'::text,'hinzufügen'::text,'Sie kann das Hinzufügen weiterer Bücher für ihr Studium nicht lassen. Eine winzige Leseliste, ganz klar.'::text),
(393613,43735,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона не може уникнути ... нових книжок до свого навчання. Крихітний список літератури, звісно.'::text,'додавання'::text,'додати'::text,'додати'::text,'Вона не може уникнути додавання нових книжок до свого навчання. Крихітний список літератури, звісно.'::text),
(393612,43735,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella no puede evitar ... más libros a su estudio. Una lista de lectura diminuta, claro.'::text,'añadir'::text,'añadir'::text,'añadir'::text,'Ella no puede evitar añadir más libros a su estudio. Una lista de lectura diminuta, claro.'::text),
(393611,43735,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ne peut pas s''empêcher ... encore des livres à ses études. Une toute petite liste de lecture, clairement.'::text,'d''ajouter'::text,'d''ajouter'::text,'ajouter'::text,'Elle ne peut pas s''empêcher d''ajouter encore des livres à ses études. Une toute petite liste de lecture, clairement.'::text),
(393614,43735,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, çalışmalarına daha fazla kitap ... kendini alamıyor. Minicik bir okuma listesi, belli.'::text,'eklemekten'::text,'eklemek'::text,'ekle'::text,'O, çalışmalarına daha fazla kitap eklemekten kendini alamıyor. Minicik bir okuma listesi, belli.'::text),
(393615,43735,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő nem tudja elkerülni, hogy még több könyvet ... a tanulmányaihoz. Pici olvasmánylista, nyilván.'::text,'hozzáadjon'::text,'hozzáadjon'::text,'hozzáad'::text,'Ő nem tudja elkerülni, hogy még több könyvet hozzáadjon a tanulmányaihoz. Pici olvasmánylista, nyilván.'::text),
(393627,43737,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Studium ... nur ein paar Bücher gewesen, bevor die Stapel bis an die Decke reichten. Leicht ungeplant.'::text,'war'::text,'ist'::text,'wurde'::text,'Ihr Studium war nur ein paar Bücher gewesen, bevor die Stapel bis an die Decke reichten. Leicht ungeplant.'::text),
(393631,43737,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її навчання ... лише кількома книжками, поки стоси не дісталися стелі. Трохи незаплановано.'::text,'було'::text,'було'::text,'було'::text,'Її навчання було лише кількома книжками, поки стоси не дісталися стелі. Трохи незаплановано.'::text),
(393630,43737,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su estudio ... solo unos pocos libros antes de que las pilas llegaran al techo. Ligeramente imprevisto.'::text,'había sido'::text,'ha sido'::text,'estaba siendo'::text,'Su estudio había sido solo unos pocos libros antes de que las pilas llegaran al techo. Ligeramente imprevisto.'::text),
(393629,43737,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses études ... juste quelques livres avant que les piles atteignent le plafond. Légèrement imprévu.'::text,'avaient été'::text,'ont été'::text,'étaient'::text,'Ses études avaient été juste quelques livres avant que les piles atteignent le plafond. Légèrement imprévu.'::text),
(393632,43737,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yığınlar tavana dayanmadan önce çalışması sadece birkaç kitaptan ...; hafiften plansız.'::text,'ibaretti'::text,'ibaret oldu'::text,'ibaret oluyordu'::text,'Yığınlar tavana dayanmadan önce çalışması sadece birkaç kitaptan ibaretti; hafiften plansız.'::text),
(393633,43737,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tanulmánya csak pár könyvből ..., mielőtt a kupacok elérték a plafont. Kicsit nem volt betervezve.'::text,'állt'::text,'állt'::text,'állt'::text,'A tanulmánya csak pár könyvből állt, mielőtt a kupacok elérték a plafont. Kicsit nem volt betervezve.'::text),
(388641,43183,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Regen, aber jetzt lächelt sie unter dem Wartehäuschen.'::text,'hasste früher'::text,'hasste'::text,'war es gewohnt zu hassen'::text,'Sie hasste früher den Regen, aber jetzt lächelt sie unter dem Wartehäuschen.'::text),
(388645,43183,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... дощ, а тепер усміхається під навісом зупинки.'::text,'раніше ненавиділа'::text,'ненавиділа'::text,'звикла ненавидіти'::text,'Вона раніше ненавиділа дощ, а тепер усміхається під навісом зупинки.'::text),
(388644,43183,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... la lluvia, pero ahora sonríe bajo la marquesina del autobús.'::text,'solía odiar'::text,'odiaba'::text,'estaba acostumbrada a odiar'::text,'Ella solía odiar la lluvia, pero ahora sonríe bajo la marquesina del autobús.'::text),
(388643,43183,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la pluie, mais maintenant elle sourit sous l''abribus.'::text,'détestait'::text,'détestait'::text,'avait l''habitude de détester'::text,'Elle détestait la pluie, mais maintenant elle sourit sous l''abribus.'::text),
(388646,43183,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O eskiden yağmurdan ..., ama şimdi otobüs durağının altında gülümsüyor.'::text,'nefret ederdi'::text,'nefret ederdi'::text,'nefret etmeye alışkındı'::text,'O eskiden yağmurdan nefret ederdi, ama şimdi otobüs durağının altında gülümsüyor.'::text),
(388647,43183,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő régen ... az esőt, de most mosolyog a buszmegálló alatt.'::text,'utálta'::text,'utálta'::text,'hozzá volt szokva, hogy utálja'::text,'Ő régen utálta az esőt, de most mosolyog a buszmegálló alatt.'::text),
(373998,41556,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, als er auftauchte, ... seine Freunde auch schon vom Steg gesprungen, kein Witz.'::text,'waren'::text,'sind'::text,'springen'::text,'Bro, als er auftauchte, waren seine Freunde auch schon vom Steg gesprungen, kein Witz.'::text),
(374002,41556,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, поки він виринув, його друзі теж уже ... з пірсу, без брехні.'::text,'стрибнули'::text,'стрибнули'::text,'стрибають'::text,'Бро, поки він виринув, його друзі теж уже стрибнули з пірсу, без брехні.'::text),
(374001,41556,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, para cuando él salió a la superficie, sus amigos también ... del muelle, en serio.'::text,'habían saltado'::text,'han saltado'::text,'saltan'::text,'Bro, para cuando él salió a la superficie, sus amigos también habían saltado del muelle, en serio.'::text),
(374000,41556,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, quand il est remonté, ses potes ... aussi du ponton, sans mentir.'::text,'avaient sauté'::text,'ont sauté'::text,'sautent'::text,'Frérot, quand il est remonté, ses potes avaient sauté aussi du ponton, sans mentir.'::text),
(374003,41556,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o suyun yüzüne çıktığında arkadaşları da iskeleden ..., yemin ederim.'::text,'atlamıştı'::text,'atladı'::text,'atlıyor'::text,'Kanka, o suyun yüzüne çıktığında arkadaşları da iskeleden atlamıştı, yemin ederim.'::text),
(374004,41556,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, mire ő feljött, a haverjai is ... a mólóról, nem kamu.'::text,'leugrottak'::text,'leugrottak'::text,'ugranak'::text,'Tesó, mire ő feljött, a haverjai is leugrottak a mólóról, nem kamu.'::text),
(341589,37955,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Am Ende des Wettkampfs ... sie ein Auto über den Kopf gestemmt. Unglaublich!'::text,'hatte'::text,'hat'::text,'stemmt'::text,'Am Ende des Wettkampfs hatte sie ein Auto über den Kopf gestemmt. Unglaublich!'::text),
(341593,37955,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця змагань вона ... авто над головою. Неймовірно!'::text,'підняла'::text,'підняла'::text,'піднімає'::text,'До кінця змагань вона підняла авто над головою. Неймовірно!'::text),
(341592,37955,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al final de la competición, ella ... un coche por encima de la cabeza. ¡Increíble!'::text,'había levantado'::text,'ha levantado'::text,'levanta'::text,'Al final de la competición, ella había levantado un coche por encima de la cabeza. ¡Increíble!'::text),
(341591,37955,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À la fin de la compétition, elle ... une voiture au-dessus de sa tête. Incroyable !'::text,'avait soulevé'::text,'a soulevé'::text,'soulève'::text,'À la fin de la compétition, elle avait soulevé une voiture au-dessus de sa tête. Incroyable !'::text),
(341594,37955,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarışmanın sonunda o, bir arabayı başının üstüne ...! İnanılmaz!'::text,'kaldırmıştı'::text,'kaldırdı'::text,'kaldırıyor'::text,'Yarışmanın sonunda o, bir arabayı başının üstüne kaldırmıştı! İnanılmaz!'::text),
(341595,37955,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A verseny végére ő ... egy autót a feje fölé. Hihetetlen!'::text,'emelt'::text,'emelt'::text,'emel'::text,'A verseny végére ő emelt egy autót a feje fölé. Hihetetlen!'::text),
(341679,37965,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... in diesem Wettkampf seit dem Morgengrauen Gewichte, und das Auto ist der absolute Todesstoß!'::text,'stemmt'::text,'stemmt'::text,'stemmt'::text,'Sie stemmt in diesem Wettkampf seit dem Morgengrauen Gewichte, und das Auto ist der absolute Todesstoß!'::text),
(341683,37965,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... на цих змаганнях від світанку, і авто — це абсолютний фінальний удар!'::text,'піднімає ваги'::text,'піднімає ваги'::text,'піднімає ваги'::text,'Вона піднімає ваги на цих змаганнях від світанку, і авто — це абсолютний фінальний удар!'::text),
(341682,37965,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... en esta competición desde el amanecer, y el coche es sin duda el golpe final!'::text,'lleva levantando pesos'::text,'está levantando pesos'::text,'levanta pesos'::text,'¡Ella lleva levantando pesos en esta competición desde el amanecer, y el coche es sin duda el golpe final!'::text),
(341681,37965,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... dans cette compétition depuis l''aube, et la voiture, c''est carrément le coup de grâce !'::text,'soulève'::text,'est en train de soulever'::text,'soulève'::text,'Elle soulève dans cette compétition depuis l''aube, et la voiture, c''est carrément le coup de grâce !'::text),
(341684,37965,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bu yarışmada şafaktan beri ..., araba da resmen son darbe!'::text,'ağırlık kaldırıyor'::text,'ağırlık kaldırıyor'::text,'ağırlık kaldırır'::text,'O bu yarışmada şafaktan beri ağırlık kaldırıyor, araba da resmen son darbe!'::text),
(341685,37965,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő hajnal óta ... ezen a versenyen, és az autó a végső csapás!'::text,'emel'::text,'emel'::text,'emel'::text,'Ő hajnal óta emel ezen a versenyen, és az autó a végső csapás!'::text),
(329646,36628,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn Leute fest genug ..., bewegt sich sogar ein Flugzeug. Offensichtlich easy.'::text,'ziehen'::text,'zogen'::text,'werden ziehen'::text,'Wenn Leute fest genug ziehen, bewegt sich sogar ein Flugzeug. Offensichtlich easy.'::text),
(329650,36628,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо люди ... досить сильно, рухається навіть літак. Очевидно, легко.'::text,'тягнуть'::text,'тягнули'::text,'тягнутимуть'::text,'Якщо люди тягнуть досить сильно, рухається навіть літак. Очевидно, легко.'::text),
(329649,36628,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la gente ... con suficiente fuerza, hasta un avión se mueve. Facilísimo, obviamente.'::text,'tira'::text,'tiró'::text,'tirará'::text,'Si la gente tira con suficiente fuerza, hasta un avión se mueve. Facilísimo, obviamente.'::text),
(329648,36628,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les gens ... assez fort, même un avion bouge. Évidemment facile.'::text,'tirent'::text,'tiraient'::text,'tireront'::text,'Si les gens tirent assez fort, même un avion bouge. Évidemment facile.'::text),
(329651,36628,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnsanlar yeterince güçlü ..., bir uçak bile hareket eder. Belli ki çok kolay.'::text,'çekerse'::text,'çektiyse'::text,'çekecekse'::text,'İnsanlar yeterince güçlü çekerse, bir uçak bile hareket eder. Belli ki çok kolay.'::text),
(329652,36628,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az emberek elég erősen ..., még egy repülő is megmozdul. Nyilván könnyű.'::text,'húzzák'::text,'húzták'::text,'húzni fogják'::text,'Ha az emberek elég erősen húzzák, még egy repülő is megmozdul. Nyilván könnyű.'::text),
(329673,36631,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Laut Roadmap ... das Team 6 Monate lang trainiert, bevor sich das Flugzeug bewegte.'::text,'hatte'::text,'hat'::text,'war'::text,'Laut Roadmap hatte das Team 6 Monate lang trainiert, bevor sich das Flugzeug bewegte.'::text),
(329677,36631,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Згідно з роадмапом, команда ... 6 місяців, перш ніж літак зрушив.'::text,'тренувалася'::text,'тренується'::text,'тренувалася'::text,'Згідно з роадмапом, команда тренувалася 6 місяців, перш ніж літак зрушив.'::text),
(329676,36631,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según la hoja de ruta, el equipo ... durante 6 meses antes de que el avión se moviera.'::text,'había estado entrenando'::text,'ha estado entrenando'::text,'estaba entrenando'::text,'Según la hoja de ruta, el equipo había estado entrenando durante 6 meses antes de que el avión se moviera.'::text),
(329675,36631,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''après la roadmap, l''équipe ... pendant 6 mois avant que l''avion bouge.'::text,'s''était entraînée'::text,'s''est entraînée'::text,'s''entraînait'::text,'D''après la roadmap, l''équipe s''était entraînée pendant 6 mois avant que l''avion bouge.'::text),
(329678,36631,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yol haritasına göre ekip, uçak hareket etmeden önce 6 ay boyunca ...'::text,'antrenman yapmıştı'::text,'antrenman yapıyor'::text,'antrenman yapıyordu'::text,'Yol haritasına göre ekip, uçak hareket etmeden önce 6 ay boyunca antrenman yapmıştı.'::text),
(329679,36631,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A roadmap szerint a csapat 6 hónapig ..., mielőtt a repülő megmozdult.'::text,'edzett'::text,'edz'::text,'edzett'::text,'A roadmap szerint a csapat 6 hónapig edzett, mielőtt a repülő megmozdult.'::text),
(391818,43536,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er lehnt sich nach vorne, also ... der Weg sehr steil sein.'::text,'muss'::text,'kann nicht'::text,'sollte nicht'::text,'Er lehnt sich nach vorne, also muss der Weg sehr steil sein.'::text),
(391822,43536,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він нахиляється вперед, тож стежка ... бути дуже крутою.'::text,'має'::text,'не може'::text,'не повинна'::text,'Він нахиляється вперед, тож стежка має бути дуже крутою.'::text),
(391821,43536,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él se inclina hacia delante, así que el camino ... ser muy empinado.'::text,'debe de'::text,'no puede'::text,'no debería'::text,'Él se inclina hacia delante, así que el camino debe de ser muy empinado.'::text),
(391820,43536,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il se penche en avant, donc le sentier ... être très raide.'::text,'doit'::text,'ne peut pas'::text,'ne devrait pas'::text,'Il se penche en avant, donc le sentier doit être très raide.'::text),
(391823,43536,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O öne eğiliyor, yani patika çok dik ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'O öne eğiliyor, yani patika çok dik olmalı.'::text),
(391824,43536,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő előrehajol, szóval az ösvény ... nagyon meredek.'::text,'biztos'::text,'nem lehet'::text,'nem kéne, hogy'::text,'Ő előrehajol, szóval az ösvény biztos nagyon meredek.'::text),
(391890,43544,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag ... er den ganzen steilen Weg hinaufgestiegen sein. Ein gemütlicher Spaziergang, klar.'::text,'wird'::text,'wird'::text,'wird'::text,'Bis Mittag wird er den ganzen steilen Weg hinaufgestiegen sein. Ein gemütlicher Spaziergang, klar.'::text),
(391894,43544,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня він ... всю круту стежку. Легенька прогулянка, звісно.'::text,'здолає'::text,'здолає'::text,'долатиме'::text,'До полудня він здолає всю круту стежку. Легенька прогулянка, звісно.'::text),
(391893,43544,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía, él ... todo el camino empinado. Un paseíto tranquilo, obviamente.'::text,'habrá subido'::text,'subirá'::text,'estará subiendo'::text,'Para el mediodía, él habrá subido todo el camino empinado. Un paseíto tranquilo, obviamente.'::text),
(391892,43544,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, il ... tout le sentier raide. Une petite balade tranquille, évidemment.'::text,'aura grimpé'::text,'grimpera'::text,'sera en train de grimper'::text,'D''ici midi, il aura grimpé tout le sentier raide. Une petite balade tranquille, évidemment.'::text),
(391895,43544,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar o bütün dik patikayı ...; tabii ki hafif bir yürüyüş.'::text,'tırmanmış olacak'::text,'tırmanacak'::text,'tırmanıyor olacak'::text,'Öğlene kadar o bütün dik patikayı tırmanmış olacak; tabii ki hafif bir yürüyüş.'::text),
(391896,43544,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre ő ... az egész meredek ösvényt. Kellemes séta, nyilván.'::text,'megmássza'::text,'meg fogja mászni'::text,'mászni fogja'::text,'Délre ő megmássza az egész meredek ösvényt. Kellemes séta, nyilván.'::text),
(370524,41170,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er vermeidet es, auf dem schmalsten Stück des Weges ...'::text,'stehen zu bleiben'::text,'stehen zu bleiben'::text,'stehen bleiben'::text,'Er vermeidet es, auf dem schmalsten Stück des Weges stehen zu bleiben.'::text),
(370528,41170,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він уникає ... на найвужчій частині стежки.'::text,'зупинок'::text,'зупинятися'::text,'зупинятися'::text,'Він уникає зупинок на найвужчій частині стежки.'::text),
(370527,41170,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él evita ... en la parte más estrecha del camino.'::text,'pararse'::text,'pararse'::text,'pararse'::text,'Él evita pararse en la parte más estrecha del camino.'::text),
(370526,41170,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il évite ... sur la partie la plus étroite du sentier.'::text,'de s''arrêter'::text,'de s''arrêter'::text,'s''arrêter'::text,'Il évite de s''arrêter sur la partie la plus étroite du sentier.'::text),
(370529,41170,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, patikanın en dar kısmında ... kaçınıyor.'::text,'durmaktan'::text,'durmak'::text,'dur'::text,'O, patikanın en dar kısmında durmaktan kaçınıyor.'::text),
(370530,41170,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő kerüli, hogy ... az ösvény legkeskenyebb részén.'::text,'megálljon'::text,'megálljon'::text,'megáll'::text,'Ő kerüli, hogy megálljon az ösvény legkeskenyebb részén.'::text),
(370542,41172,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor er den schmalen Weg erreichte, ... er eine Stunde lang die Felsvorsprünge hinab.'::text,'kletterte'::text,'kletterte'::text,'kletterte'::text,'Bevor er den schmalen Weg erreichte, kletterte er eine Stunde lang die Felsvorsprünge hinab.'::text),
(370546,41172,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж дійти до вузької стежки, він ... годину вниз скельними виступами.'::text,'спускався'::text,'спустився'::text,'спускався'::text,'Перш ніж дійти до вузької стежки, він спускався годину вниз скельними виступами.'::text),
(370545,41172,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de llegar al camino estrecho, él ... durante una hora por las repisas de roca.'::text,'había estado bajando'::text,'bajó'::text,'estaba bajando'::text,'Antes de llegar al camino estrecho, él había estado bajando durante una hora por las repisas de roca.'::text),
(370544,41172,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant d''atteindre le sentier étroit, il ... pendant une heure le long des corniches rocheuses.'::text,'était descendu'::text,'descendit'::text,'descendait'::text,'Avant d''atteindre le sentier étroit, il était descendu pendant une heure le long des corniches rocheuses.'::text),
(370547,41172,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dar patikaya varmadan önce o bir saat boyunca kaya çıkıntılarından aşağı ...'::text,'inmişti'::text,'indi'::text,'iniyordu'::text,'Dar patikaya varmadan önce o bir saat boyunca kaya çıkıntılarından aşağı inmişti.'::text),
(370548,41172,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt elérte a keskeny ösvényt, ő egy órán át ... lefelé a sziklapárkányokon.'::text,'mászott'::text,'mászott'::text,'mászott'::text,'Mielőtt elérte a keskeny ösvényt, ő egy órán át mászott lefelé a sziklapárkányokon.'::text),
(333885,37099,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Wellen ... ihre barfüßigen Spuren komplett weg, für immer verschwunden!'::text,'spülen'::text,'werden gespült'::text,'spülend'::text,'Die Wellen spülen ihre barfüßigen Spuren komplett weg, für immer verschwunden!'::text),
(333889,37099,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хвилі ... її босі сліди повністю, назавжди!'::text,'змивають'::text,'змиваються'::text,'змиваючи'::text,'Хвилі змивають її босі сліди повністю, назавжди!'::text),
(333888,37099,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Las olas ... sus pasos descalzos por completo, desaparecidos para siempre!'::text,'borran'::text,'son borradas'::text,'borrando'::text,'¡Las olas borran sus pasos descalzos por completo, desaparecidos para siempre!'::text),
(333887,37099,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les vagues ... complètement ses pas nu-pieds, disparus à jamais !'::text,'effacent'::text,'sont effacées'::text,'effaçant'::text,'Les vagues effacent complètement ses pas nu-pieds, disparus à jamais !'::text),
(333890,37099,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dalgalar onun çıplak ayak izlerini tamamen ..., sonsuza dek yok oldu!'::text,'siliyor'::text,'siliniyor'::text,'silerek'::text,'Dalgalar onun çıplak ayak izlerini tamamen siliyor, sonsuza dek yok oldu!'::text),
(333891,37099,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hullámok teljesen ... a mezítlábas lépteit, örökre eltűntek!'::text,'elmossák'::text,'elmosódnak'::text,'elmosva'::text,'A hullámok teljesen elmossák a mezítlábas lépteit, örökre eltűntek!'::text),
(333966,37108,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Sonnenuntergang ... die Wellen all ihre barfüßigen Fußspuren weggespült haben.'::text,'werden'::text,'werden'::text,'werden'::text,'Bis zum Sonnenuntergang werden die Wellen all ihre barfüßigen Fußspuren weggespült haben.'::text),
(333970,37108,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця хвилі ... всі її босі сліди.'::text,'змиють'::text,'змиють'::text,'змиватимуть'::text,'До заходу сонця хвилі змиють всі її босі сліди.'::text),
(333969,37108,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la puesta de sol, las olas ... todas sus huellas descalzas.'::text,'habrán borrado'::text,'borrarán'::text,'estarán borrando'::text,'Para la puesta de sol, las olas habrán borrado todas sus huellas descalzas.'::text),
(333968,37108,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, les vagues ... toutes ses empreintes de pieds nus.'::text,'auront effacé'::text,'effaceront'::text,'seront en train d''effacer'::text,'D''ici le coucher du soleil, les vagues auront effacé toutes ses empreintes de pieds nus.'::text),
(333971,37108,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar dalgalar onun bütün çıplak ayak izlerini ...'::text,'silmiş olacak'::text,'silecek'::text,'siliyor olacak'::text,'Gün batımına kadar dalgalar onun bütün çıplak ayak izlerini silmiş olacak.'::text),
(333972,37108,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtára a hullámok ... az összes mezítlábas lábnyomát.'::text,'elmossák'::text,'el fogják mosni'::text,'mosni fogják'::text,'Napnyugtára a hullámok elmossák az összes mezítlábas lábnyomát.'::text),
(340365,37819,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Erst von oben ... die kreisrunde Form der Bühne.'::text,'zeigt die Kamera'::text,'die Kamera zeigt'::text,'zeigt die Kamera'::text,'Erst von oben zeigt die Kamera die kreisrunde Form der Bühne.'::text),
(340369,37819,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лише згори ... круглу форму сцени.'::text,'камера показує'::text,'камера показує'::text,'показує камера'::text,'Лише згори камера показує круглу форму сцени.'::text),
(340368,37819,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Solo desde arriba ... la forma circular del escenario.'::text,'muestra la cámara'::text,'la cámara muestra'::text,'muestra la cámara'::text,'Solo desde arriba muestra la cámara la forma circular del escenario.'::text),
(340367,37819,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce n''est que d''en haut que ... la forme circulaire de la scène.'::text,'la caméra montre'::text,'la caméra montre'::text,'montre la caméra'::text,'Ce n''est que d''en haut que la caméra montre la forme circulaire de la scène.'::text),
(340370,37819,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sahnenin yuvarlak şeklini kamera ancak yukarıdan ...'::text,'gösteriyor'::text,'gösteriyor'::text,'gösteriyor'::text,'Sahnenin yuvarlak şeklini kamera ancak yukarıdan gösteriyor.'::text),
(340371,37819,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csak felülről ... a színpad kör alakját.'::text,'mutatja meg a kamera'::text,'a kamera megmutatja'::text,'mutatja a kamera'::text,'Csak felülről mutatja meg a kamera a színpad kör alakját.'::text),
(340230,37804,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, als die Crowd auftauchte, ... der Junge den Kreisel schon allein umkreist, echt jetzt.'::text,'hatte'::text,'hat'::text,'umkreist'::text,'Yo, als die Crowd auftauchte, hatte der Junge den Kreisel schon allein umkreist, echt jetzt.'::text),
(340234,37804,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, поки з''явився натовп, хлопець уже сам ... дзиґу, реально.'::text,'оббіг'::text,'оббіг'::text,'оббігає'::text,'Йо, поки з''явився натовп, хлопець уже сам оббіг дзиґу, реально.'::text),
(340233,37804,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, para cuando llegó la gente, el chico ya ... la peonza solo, en serio.'::text,'había rodeado'::text,'ha rodeado'::text,'rodea'::text,'Oye, para cuando llegó la gente, el chico ya había rodeado la peonza solo, en serio.'::text),
(340232,37804,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, quand la foule est arrivée, le garçon ... déjà seul autour de la toupie, sérieux.'::text,'avait tourné'::text,'a tourné'::text,'tourne'::text,'Yo, quand la foule est arrivée, le garçon avait tourné déjà seul autour de la toupie, sérieux.'::text),
(340235,37804,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, kalabalık geldiğinde çocuk topacın etrafında tek başına ..., cidden.'::text,'dönmüştü'::text,'döndü'::text,'dönüyor'::text,'Yo, kalabalık geldiğinde çocuk topacın etrafında tek başına dönmüştü, cidden.'::text),
(340236,37804,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, mire megjött a tömeg, a srác már egyedül ... a pörgettyűt, komolyan.'::text,'körbefutotta'::text,'körbefutotta'::text,'körbefutja'::text,'Figyu, mire megjött a tömeg, a srác már egyedül körbefutotta a pörgettyűt, komolyan.'::text),
(340275,37809,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... sie eine Stunde lang um den Kreisel, bevor die Sonne unterging.'::text,'kreisten'::text,'kreisen'::text,'kreisen'::text,'Bestie, angeblich kreisten sie eine Stunde lang um den Kreisel, bevor die Sonne unterging.'::text),
(340279,37809,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вони ... навколо дзиґи годину, поки не сіло сонце.'::text,'кружляли'::text,'кружляють'::text,'кружляють'::text,'Подруго, кажуть, вони кружляли навколо дзиґи годину, поки не сіло сонце.'::text),
(340278,37809,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer ellos ... alrededor de la peonza durante una hora antes de que se pusiera el sol.'::text,'habían estado dando vueltas'::text,'han estado dando vueltas'::text,'dan vueltas'::text,'Amiga, al parecer ellos habían estado dando vueltas alrededor de la peonza durante una hora antes de que se pusiera el sol.'::text),
(340277,37809,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, apparemment ils ... autour de la toupie pendant une heure avant le coucher du soleil.'::text,'tournaient'::text,'tournent'::text,'tournent'::text,'Bestie, apparemment ils tournaient autour de la toupie pendant une heure avant le coucher du soleil.'::text),
(340280,37809,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, güya onlar güneş batmadan önce bir saat boyunca topacın etrafında ...'::text,'dönüp durmuşlar'::text,'dönüp duruyorlar'::text,'dönüyorlar'::text,'Kanka, güya onlar güneş batmadan önce bir saat boyunca topacın etrafında dönüp durmuşlar.'::text),
(340281,37809,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ők egy órán át ... a pörgettyű körül, mielőtt lement a nap.'::text,'köröztek'::text,'köröznek'::text,'köröznek'::text,'Csajszi, állítólag ők egy órán át köröztek a pörgettyű körül, mielőtt lement a nap.'::text),
(345036,38338,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, dir macht es nichts aus, in einem vollen Stadion zu ..., Respekt.'::text,'sitzen'::text,'sitzen'::text,'sitzen'::text,'Ehrlich, dir macht es nichts aus, in einem vollen Stadion zu sitzen, Respekt.'::text),
(345040,38338,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти не проти ... на переповненому стадіоні, респект.'::text,'сидіти'::text,'сидіти'::text,'сидіти'::text,'Чесно, ти не проти сидіти на переповненому стадіоні, респект.'::text),
(345039,38338,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, tú no tienes problema en ... en un estadio abarrotado, respeto.'::text,'sentarte'::text,'sentarte'::text,'sentarte'::text,'La verdad, tú no tienes problema en sentarte en un estadio abarrotado, respeto.'::text),
(345038,38338,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Honnêtement, ça ne te dérange pas ... dans un stade bondé, respect.'::text,'d''être assis'::text,'d''être assis'::text,'être assis'::text,'Honnêtement, ça ne te dérange pas d''être assis dans un stade bondé, respect.'::text),
(345041,38338,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen kalabalık bir stadyumda ... dert etmiyorsun, helal.'::text,'oturmayı'::text,'oturmayı'::text,'otur'::text,'Açıkçası sen kalabalık bir stadyumda oturmayı dert etmiyorsun, helal.'::text),
(345042,38338,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te nem bánod, hogy ... egy zsúfolt stadionban, respekt.'::text,'ülsz'::text,'ülsz'::text,'ülsz'::text,'Őszintén, te nem bánod, hogy ülsz egy zsúfolt stadionban, respekt.'::text),
(345054,38340,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als das Spiel anfing, ... das Stadion schon seit einer Stunde voll. Leicht beliebt.'::text,'war'::text,'ist'::text,'war'::text,'Als das Spiel anfing, war das Stadion schon seit einer Stunde voll. Leicht beliebt.'::text),
(345058,38340,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли гра почалася, стадіон ... переповнений уже годину. Трохи популярний.'::text,'був'::text,'є'::text,'був'::text,'Коли гра почалася, стадіон був переповнений уже годину. Трохи популярний.'::text),
(345057,38340,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando empezó el partido, el estadio ... lleno desde hacía una hora. Ligeramente popular.'::text,'había estado'::text,'ha estado'::text,'estaba'::text,'Cuando empezó el partido, el estadio había estado lleno desde hacía una hora. Ligeramente popular.'::text),
(345056,38340,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le match a commencé, le stade ... bondé depuis une heure. Légèrement populaire.'::text,'était'::text,'est'::text,'était'::text,'Quand le match a commencé, le stade était bondé depuis une heure. Légèrement populaire.'::text),
(345059,38340,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maç başladığında stadyum bir saattir tıklım tıklım ...; hafiften popüler.'::text,'doluydu'::text,'dolu'::text,'doluydu'::text,'Maç başladığında stadyum bir saattir tıklım tıklım doluydu; hafiften popüler.'::text),
(345060,38340,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A meccs kezdetére a stadion már egy órája ... zsúfolt. Kicsit népszerű.'::text,'volt'::text,'van'::text,'volt'::text,'A meccs kezdetére a stadion már egy órája volt zsúfolt. Kicsit népszerű.'::text),
(372486,41388,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jede Glasscheibe ... von zwei Gärtnern in den Metallrahmen gehoben.'::text,'wurde'::text,'hob'::text,'hebt'::text,'Jede Glasscheibe wurde von zwei Gärtnern in den Metallrahmen gehoben.'::text),
(372490,41388,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожна скляна панель ... в металеву раму двома садівниками.'::text,'була піднята'::text,'підняла'::text,'піднімає'::text,'Кожна скляна панель була піднята в металеву раму двома садівниками.'::text),
(372489,41388,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada panel de vidrio ... al marco metálico por dos jardineros.'::text,'fue levantado'::text,'levantó'::text,'está levantando'::text,'Cada panel de vidrio fue levantado al marco metálico por dos jardineros.'::text),
(372488,41388,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque panneau de verre ... dans le cadre métallique par deux jardiniers.'::text,'a été soulevé'::text,'a soulevé'::text,'soulève'::text,'Chaque panneau de verre a été soulevé dans le cadre métallique par deux jardiniers.'::text),
(372491,41388,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her cam panel iki bahçıvan tarafından metal çerçeveye ...'::text,'kaldırıldı'::text,'kaldırdı'::text,'kaldırıyor'::text,'Her cam panel iki bahçıvan tarafından metal çerçeveye kaldırıldı.'::text),
(372492,41388,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden üvegpanelt két kertész ... a fémkeretbe.'::text,'emelt be'::text,'emelte be'::text,'emeli be'::text,'Minden üvegpanelt két kertész emelt be a fémkeretbe.'::text),
(391179,43465,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Stapel, ... oberste Palette zuerst fiel, krachte auf den Rasen.'::text,'dessen'::text,'der'::text,'der'::text,'Der Stapel, dessen oberste Palette zuerst fiel, krachte auf den Rasen.'::text),
(391183,43465,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Штабель, ... верхній піддон упав першим, гепнувся на газон.'::text,'чий'::text,'який'::text,'що'::text,'Штабель, чий верхній піддон упав першим, гепнувся на газон.'::text),
(391182,43465,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pila, ... palé de arriba cayó primero, se estrelló contra el césped.'::text,'cuyo'::text,'que'::text,'la cual'::text,'La pila, cuyo palé de arriba cayó primero, se estrelló contra el césped.'::text),
(391181,43465,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pile, ... la palette du dessus est tombée en premier, s''est écrasée sur la pelouse.'::text,'dont'::text,'qui'::text,'que'::text,'La pile, dont la palette du dessus est tombée en premier, s''est écrasée sur la pelouse.'::text),
(391184,43465,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En üstteki paleti ... ilk düşen yığın, çimenlere çöktü.'::text,''::text,NULL::text,NULL::text,'En üstteki paleti ilk düşen yığın, çimenlere çöktü.'::text),
(391185,43465,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A halom, ... legfelső raklapja esett le először, rázuhant a gyepre.'::text,'amelynek a'::text,'amely'::text,'amelyik'::text,'A halom, amelynek a legfelső raklapja esett le először, rázuhant a gyepre.'::text),
(393807,43757,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieses U-Boot ... sich seit Jahren unter diesem See, und keiner wusste es! Horror!'::text,'versteckt'::text,'versteckt'::text,'versteckt'::text,'Dieses U-Boot versteckt sich seit Jahren unter diesem See, und keiner wusste es! Horror!'::text),
(393811,43757,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей підводний човен ... під цим озером роками, і ніхто не знав! Жах!'::text,'ховався'::text,'ховається'::text,'ховається'::text,'Цей підводний човен ховався під цим озером роками, і ніхто не знав! Жах!'::text),
(393810,43757,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ese submarino ... bajo este lago durante años y nadie lo sabía! ¡Qué miedo!'::text,'ha estado escondido'::text,'está escondido'::text,'se esconde'::text,'¡Ese submarino ha estado escondido bajo este lago durante años y nadie lo sabía! ¡Qué miedo!'::text),
(393809,43757,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce sous-marin ... sous ce lac depuis des années, et personne ne le savait ! Terrifiant !'::text,'se cache'::text,'est en train de se cacher'::text,'se cache'::text,'Ce sous-marin se cache sous ce lac depuis des années, et personne ne le savait ! Terrifiant !'::text),
(393812,43757,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O denizaltı yıllardır bu gölün altında ... ve kimse bilmiyordu! Korkunç!'::text,'saklanıyormuş'::text,'saklanıyor'::text,'saklanır'::text,'O denizaltı yıllardır bu gölün altında saklanıyormuş ve kimse bilmiyordu! Korkunç!'::text),
(393813,43757,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a tengeralattjáró évek óta ... ez alatt a tó alatt, és senki sem tudta! Ijesztő!'::text,'rejtőzik'::text,'rejtőzik'::text,'rejtőzik'::text,'Az a tengeralattjáró évek óta rejtőzik ez alatt a tó alatt, és senki sem tudta! Ijesztő!'::text),
(393879,43765,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das U-Boot ... sich bereits einige Zeit unter der Oberfläche, bevor die Schwimmer es bemerkten.'::text,'bewegte'::text,'bewegte'::text,'bewegt'::text,'Das U-Boot bewegte sich bereits einige Zeit unter der Oberfläche, bevor die Schwimmer es bemerkten.'::text),
(393883,43765,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Підводний човен ... під поверхнею певний час, перш ніж плавці його помітили.'::text,'рухався'::text,'рухався'::text,'рухається'::text,'Підводний човен рухався під поверхнею певний час, перш ніж плавці його помітили.'::text),
(393882,43765,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El submarino ... bajo la superficie durante un tiempo antes de que los nadadores lo observaran.'::text,'había estado navegando'::text,'estaba navegando'::text,'ha estado navegando'::text,'El submarino había estado navegando bajo la superficie durante un tiempo antes de que los nadadores lo observaran.'::text),
(393881,43765,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sous-marin ... sous la surface depuis un certain temps avant que les nageurs ne l''observent.'::text,'naviguait'::text,'naviguait'::text,'navigue'::text,'Le sous-marin naviguait sous la surface depuis un certain temps avant que les nageurs ne l''observent.'::text),
(393884,43765,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denizaltı, yüzücüler onu fark etmeden önce bir süredir yüzeyin altında ...'::text,'ilerliyordu'::text,'ilerliyordu'::text,'ilerliyor'::text,'Denizaltı, yüzücüler onu fark etmeden önce bir süredir yüzeyin altında ilerliyordu.'::text),
(393885,43765,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tengeralattjáró már egy ideje ... a felszín alatt, mielőtt az úszók észrevették.'::text,'haladt'::text,'haladt'::text,'halad'::text,'A tengeralattjáró már egy ideje haladt a felszín alatt, mielőtt az úszók észrevették.'::text),
(344856,38318,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, die Touristen haben sich auf den Platz gedrängt, und ... die Büroleute.'::text,'auch'::text,'auch'::text,'auch'::text,'Hör mal, ich hab gehört, die Touristen haben sich auf den Platz gedrängt, und auch die Büroleute.'::text),
(344860,38318,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що туристи натовпом ринули на площу, і ... офісні працівники.'::text,'теж'::text,'теж'::text,'теж'::text,'Слухай, я чула, що туристи натовпом ринули на площу, і теж офісні працівники.'::text),
(344859,38318,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, yo he oído que los turistas se apiñaron en la plaza, y los oficinistas ...'::text,'también'::text,'también'::text,'también'::text,'Oye, yo he oído que los turistas se apiñaron en la plaza, y los oficinistas también.'::text),
(344858,38318,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire que les touristes se sont entassés sur la place, et les employés de bureau ...'::text,'aussi'::text,'aussi'::text,'aussi'::text,'Écoute, j''ai entendu dire que les touristes se sont entassés sur la place, et les employés de bureau aussi.'::text),
(344861,38318,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, ben duydum ki turistler meydana doluşmuş, ofis çalışanları ...'::text,'da'::text,'da'::text,'da'::text,'Dinle, ben duydum ki turistler meydana doluşmuş, ofis çalışanları da.'::text),
(344862,38318,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, én úgy hallottam, a turisták beözönlöttek a térre, és az irodisták ...'::text,'is'::text,'is'::text,'is'::text,'Figyelj, én úgy hallottam, a turisták beözönlöttek a térre, és az irodisták is.'::text),
(344910,38324,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Individuen in der Mitte wünschen sich vermutlich, dass die anderen sich weniger eng ...'::text,'drängen würden'::text,'drängen'::text,'drängen werden'::text,'Die Individuen in der Mitte wünschen sich vermutlich, dass die anderen sich weniger eng drängen würden.'::text),
(344914,38324,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Особи в центрі, імовірно, бажають, щоб інші ... менш щільно.'::text,'скупчувалися'::text,'скупчуються'::text,'скупчуватимуться'::text,'Особи в центрі, імовірно, бажають, щоб інші скупчувалися менш щільно.'::text),
(344913,38324,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los individuos del centro presumiblemente desean que los demás se ... menos.'::text,'apiñaran'::text,'apiñan'::text,'apiñarán'::text,'Los individuos del centro presumiblemente desean que los demás se apiñaran menos.'::text),
(344912,38324,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les individus au centre souhaitent vraisemblablement que les autres se ... moins.'::text,'serrent'::text,'serrent'::text,'serreront'::text,'Les individus au centre souhaitent vraisemblablement que les autres se serrent moins.'::text),
(344915,38324,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Merkezdeki bireyler muhtemelen diğerlerinin daha az ... istiyor.'::text,'sıkışmasını'::text,'sıkışmasını'::text,'sıkışacağını'::text,'Merkezdeki bireyler muhtemelen diğerlerinin daha az sıkışmasını istiyor.'::text),
(344916,38324,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A középen lévő egyedek feltehetően azt szeretnék, ha a többiek kevésbé szorosan ...'::text,'tömörülnének'::text,'tömörülnek'::text,'tömörülni fognak'::text,'A középen lévő egyedek feltehetően azt szeretnék, ha a többiek kevésbé szorosan tömörülnének.'::text),
(381450,42384,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Stuhlturm wackelt, also ... es sehr riskant sein, hochzuklettern.'::text,'muss'::text,'kann nicht'::text,'sollte nicht'::text,'Der Stuhlturm wackelt, also muss es sehr riskant sein, hochzuklettern.'::text),
(381454,42384,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вежа зі стільців хитається, тож лізти на неї ... бути дуже ризиковано.'::text,'має'::text,'не може'::text,'не повинно'::text,'Вежа зі стільців хитається, тож лізти на неї має бути дуже ризиковано.'::text),
(381453,42384,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La torre de sillas se tambalea, así que escalarla ... ser muy arriesgado.'::text,'debe de'::text,'no puede'::text,'no debería'::text,'La torre de sillas se tambalea, así que escalarla debe de ser muy arriesgado.'::text),
(381452,42384,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tour de chaises oscille, donc l''escalader ... être très risqué.'::text,'doit'::text,'ne peut pas'::text,'ne devrait pas'::text,'La tour de chaises oscille, donc l''escalader doit être très risqué.'::text),
(381455,42384,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sandalye kulesi sallanıyor, yani ona tırmanmak çok riskli ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Sandalye kulesi sallanıyor, yani ona tırmanmak çok riskli olmalı.'::text),
(381456,42384,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A székekből álló torony inog, szóval felmászni rá ... nagyon kockázatos.'::text,'biztos'::text,'nem lehet'::text,'nem kéne, hogy'::text,'A székekből álló torony inog, szóval felmászni rá biztos nagyon kockázatos.'::text),
(381495,42389,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Stuhlturm ... gerade im Wind. Ein leicht riskanter Ort für ein Picknick.'::text,'schwankt'::text,'schwankt'::text,'hat geschwankt'::text,'Der Stuhlturm schwankt gerade im Wind. Ein leicht riskanter Ort für ein Picknick.'::text),
(381499,42389,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вежа зі стільців зараз ... на вітрі. Трохи ризиковане місце для пікніка.'::text,'хитається'::text,'хитається'::text,'хитнулася'::text,'Вежа зі стільців зараз хитається на вітрі. Трохи ризиковане місце для пікніка.'::text),
(381498,42389,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La torre de sillas ... con el viento ahora mismo. Un sitio ligeramente arriesgado para un pícnic.'::text,'se está balanceando'::text,'se balancea'::text,'se ha balanceado'::text,'La torre de sillas se está balanceando con el viento ahora mismo. Un sitio ligeramente arriesgado para un pícnic.'::text),
(381497,42389,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tour de chaises ... dans le vent en ce moment. Un endroit légèrement risqué pour un pique-nique.'::text,'oscille'::text,'oscille'::text,'a oscillé'::text,'La tour de chaises oscille dans le vent en ce moment. Un endroit légèrement risqué pour un pique-nique.'::text),
(381500,42389,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sandalye kulesi şu anda rüzgârda ...; piknik için hafif riskli bir yer.'::text,'sallanıyor'::text,'sallanır'::text,'sallandı'::text,'Sandalye kulesi şu anda rüzgârda sallanıyor; piknik için hafif riskli bir yer.'::text),
(381501,42389,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A székekből álló torony épp most ... a szélben. Kicsit kockázatos hely egy piknikhez.'::text,'inog'::text,'inog'::text,'megingott'::text,'A székekből álló torony épp most inog a szélben. Kicsit kockázatos hely egy piknikhez.'::text),
(389838,43316,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Brücke überspannt die ganze furchterregende Schlucht, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Diese Brücke überspannt die ganze furchterregende Schlucht, oder?'::text),
(389842,43316,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей міст перекриває весь моторошний каньйон, ...?'::text,'так?'::text,'так?'::text,'так?'::text,'Цей міст перекриває весь моторошний каньйон, так?'::text),
(389841,43316,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ese puente cruza todo el aterrador cañón, ¿...'::text,'verdad?'::text,'verdad?'::text,'verdad?'::text,'Ese puente cruza todo el aterrador cañón, ¿verdad?'::text),
(389840,43316,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce pont enjambe tout le canyon terrifiant, ...'::text,'non ?'::text,'non ?'::text,'non ?'::text,'Ce pont enjambe tout le canyon terrifiant, non ?'::text),
(389843,43316,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O köprü bütün korkunç kanyonu aşıyor, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'O köprü bütün korkunç kanyonu aşıyor, değil mi?'::text),
(389844,43316,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a híd átíveli az egész ijesztő kanyont, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Az a híd átíveli az egész ijesztő kanyont, ugye?'::text),
(389928,43326,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Sonnenuntergang ... der Kranausleger die ganze Baustelle überspannt haben und einen furchterregenden Schatten werfen!'::text,'wird'::text,'wird'::text,'überspannt'::text,'Bis zum Sonnenuntergang wird der Kranausleger die ganze Baustelle überspannt haben und einen furchterregenden Schatten werfen!'::text),
(389932,43326,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця стріла крана ... весь будмайданчик і кине моторошну тінь!'::text,'перекриє'::text,'перекриє'::text,'перекриває'::text,'До заходу сонця стріла крана перекриє весь будмайданчик і кине моторошну тінь!'::text),
(389931,43326,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para la puesta de sol, la pluma de la grúa ... toda la obra, proyectando una sombra aterradora!'::text,'habrá cubierto'::text,'cubrirá'::text,'cubre'::text,'¡Para la puesta de sol, la pluma de la grúa habrá cubierto toda la obra, proyectando una sombra aterradora!'::text),
(389930,43326,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, la flèche de la grue ... tout le chantier, projetant une ombre terrifiante !'::text,'aura surplombé'::text,'surplombera'::text,'surplombe'::text,'D''ici le coucher du soleil, la flèche de la grue aura surplombé tout le chantier, projetant une ombre terrifiante !'::text),
(389933,43326,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar vinç kolu bütün şantiyeyi ... ve korkunç bir gölge düşürecek!'::text,'kaplamış olacak'::text,'kaplayacak'::text,'kaplıyor'::text,'Gün batımına kadar vinç kolu bütün şantiyeyi kaplamış olacak ve korkunç bir gölge düşürecek!'::text),
(389934,43326,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtára a daru gémje ... az egész építkezést, és ijesztő árnyékot vet!'::text,'átíveli'::text,'át fogja ívelni'::text,'átíveli'::text,'Napnyugtára a daru gémje átíveli az egész építkezést, és ijesztő árnyékot vet!'::text),
(396066,44008,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Kamera beim Zelt ankam, ... der Bogen schon platt, weil er keine Luft hatte.'::text,'war'::text,'ist'::text,'wird'::text,'Als die Kamera beim Zelt ankam, war der Bogen schon platt, weil er keine Luft hatte.'::text),
(396070,44008,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки камера дісталася до намету, арка вже ..., бо в ній не було повітря.'::text,'здулася'::text,'здулася'::text,'здувається'::text,'Поки камера дісталася до намету, арка вже здулася, бо в ній не було повітря.'::text),
(396069,44008,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando la cámara llegó a la carpa, el arco ya se ..., porque no tenía aire.'::text,'había desinflado'::text,'ha desinflado'::text,'desinfla'::text,'Para cuando la cámara llegó a la carpa, el arco ya se había desinflado, porque no tenía aire.'::text),
(396068,44008,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand la caméra est arrivée à la tente, l''arche ... déjà à plat, parce qu''elle n''avait pas d''air.'::text,'était'::text,'est'::text,'devient'::text,'Quand la caméra est arrivée à la tente, l''arche était déjà à plat, parce qu''elle n''avait pas d''air.'::text),
(396071,44008,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamera çadıra vardığında kemer çoktan ..., çünkü havası yoktu.'::text,'sönmüştü'::text,'söndü'::text,'sönüyor'::text,'Kamera çadıra vardığında kemer çoktan sönmüştü, çünkü havası yoktu.'::text),
(396072,44008,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a kamera a sátorhoz ért, az ív már ..., mert nem volt benne levegő.'::text,'leeresztett'::text,'leeresztett'::text,'leereszt'::text,'Mire a kamera a sátorhoz ért, az ív már leeresztett, mert nem volt benne levegő.'::text),
(396120,44014,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Garten ist ... neben der Hüpfburg das Einzige, was noch steht.'::text,'das Zelt'::text,'ein Zelt'::text,'Zelt'::text,'Im Garten ist das Zelt neben der Hüpfburg das Einzige, was noch steht.'::text),
(396124,44014,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У саду ... біля надувного замку — єдине, що ще стоїть.'::text,'намет'::text,'намет'::text,'намет'::text,'У саду намет біля надувного замку — єдине, що ще стоїть.'::text),
(396123,44014,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En el jardín, ... junto al castillo hinchable es lo único que sigue en pie.'::text,'la carpa'::text,'una carpa'::text,'carpa'::text,'En el jardín, la carpa junto al castillo hinchable es lo único que sigue en pie.'::text),
(396122,44014,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans le jardin, ... à côté du château gonflable est la seule chose encore debout.'::text,'la tente'::text,'une tente'::text,'tente'::text,'Dans le jardin, la tente à côté du château gonflable est la seule chose encore debout.'::text),
(396125,44014,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bahçede şişme şatonun yanındaki ... hâlâ ayakta duran tek şey.'::text,'çadır'::text,'bir çadır'::text,'çadır'::text,'Bahçede şişme şatonun yanındaki çadır hâlâ ayakta duran tek şey.'::text),
(396126,44014,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kertben ... a légvár mellett az egyetlen, ami még áll.'::text,'a sátor'::text,'egy sátor'::text,'sátor'::text,'A kertben a sátor a légvár mellett az egyetlen, ami még áll.'::text),
(390135,43349,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... früher laute Boxen, und jetzt tanzt du direkt daneben? Ikonisch.'::text,'hasstest'::text,'hasstest'::text,'warst gewohnt zu hassen'::text,'Du hasstest früher laute Boxen, und jetzt tanzt du direkt daneben? Ikonisch.'::text),
(390139,43349,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... гучні колонки, а тепер танцюєш просто біля однієї? Легенда.'::text,'раніше ненавидів'::text,'ненавидів'::text,'звик ненавидіти'::text,'Ти раніше ненавидів гучні колонки, а тепер танцюєш просто біля однієї? Легенда.'::text),
(390138,43349,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... los altavoces fuertes, ¿y ahora bailas justo al lado de uno? Icónico.'::text,'solías odiar'::text,'odiabas'::text,'estabas acostumbrado a odiar'::text,'Tú solías odiar los altavoces fuertes, ¿y ahora bailas justo al lado de uno? Icónico.'::text),
(390137,43349,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... les enceintes bruyantes, et maintenant tu danses juste à côté d''une ? Iconique.'::text,'détestais'::text,'détestais'::text,'avais l''habitude de détester'::text,'Tu détestais les enceintes bruyantes, et maintenant tu danses juste à côté d''une ? Iconique.'::text),
(390140,43349,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen eskiden yüksek sesli hoparlörlerden ..., şimdi birinin dibinde mi dans ediyorsun? Efsane.'::text,'nefret ederdin'::text,'nefret ederdin'::text,'nefret etmeye alışkındın'::text,'Sen eskiden yüksek sesli hoparlörlerden nefret ederdin, şimdi birinin dibinde mi dans ediyorsun? Efsane.'::text),
(390141,43349,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te régen ... a hangos hangfalakat, most meg közvetlenül az egyik mellett táncolsz? Ikonikus.'::text,'utáltad'::text,'utáltad'::text,'hozzá voltál szokva, hogy utáld'::text,'Te régen utáltad a hangos hangfalakat, most meg közvetlenül az egyik mellett táncolsz? Ikonikus.'::text),
(390162,43352,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Handy ... auf der Holzterrasse, bevor das Video den Lautsprecher zeigte.'::text,'vibrierte'::text,'vibrierte'::text,'vibriert'::text,'Das Handy vibrierte auf der Holzterrasse, bevor das Video den Lautsprecher zeigte.'::text),
(390166,43352,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Телефон ... на дерев''яній терасі, перш ніж у відео показали колонку.'::text,'завібрував'::text,'завібрував'::text,'вібрує'::text,'Телефон завібрував на дерев''яній терасі, перш ніж у відео показали колонку.'::text),
(390165,43352,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El móvil ... en la terraza antes de que el vídeo mostrara el altavoz.'::text,'había vibrado'::text,'ha vibrado'::text,'vibra'::text,'El móvil había vibrado en la terraza antes de que el vídeo mostrara el altavoz.'::text),
(390164,43352,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le téléphone ... sur la terrasse avant que la vidéo montre l''enceinte.'::text,'avait vibré'::text,'a vibré'::text,'vibre'::text,'Le téléphone avait vibré sur la terrasse avant que la vidéo montre l''enceinte.'::text),
(390167,43352,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Video hoparlörü göstermeden önce telefon ahşap zeminde ...'::text,'titreşmişti'::text,'titreşti'::text,'titreşiyor'::text,'Video hoparlörü göstermeden önce telefon ahşap zeminde titreşmişti.'::text),
(390168,43352,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A telefon ... a fateraszon, mielőtt a videó megmutatta a hangszórót.'::text,'rezgett'::text,'rezgett'::text,'rezeg'::text,'A telefon rezgett a fateraszon, mielőtt a videó megmutatta a hangszórót.'::text),
(336225,37359,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Ast ... sanft im Wind, als zwei Hände ihn packten. Genau das, was er brauchte.'::text,'wiegte sich'::text,'wiegte sich'::text,'hat sich gewiegt'::text,'Der Ast wiegte sich sanft im Wind, als zwei Hände ihn packten. Genau das, was er brauchte.'::text),
(336229,37359,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гілка ... лагідно на вітерці, коли її схопили дві руки. Саме те, чого їй бракувало.'::text,'гойдалася'::text,'гойднулася'::text,'гойднулася'::text,'Гілка гойдалася лагідно на вітерці, коли її схопили дві руки. Саме те, чого їй бракувало.'::text),
(336228,37359,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La rama se ... suavemente con la brisa cuando dos manos la agarraron. Justo lo que necesitaba.'::text,'mecía'::text,'meció'::text,'ha mecido'::text,'La rama se mecía suavemente con la brisa cuando dos manos la agarraron. Justo lo que necesitaba.'::text),
(336227,37359,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La branche ... doucement dans la brise quand deux mains l''ont attrapée. Exactement ce qu''il lui fallait.'::text,'se balançait'::text,'se balança'::text,'s''est balancée'::text,'La branche se balançait doucement dans la brise quand deux mains l''ont attrapée. Exactement ce qu''il lui fallait.'::text),
(336230,37359,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki el onu yakaladığında dal esintide hafifçe ...; tam da ihtiyacı olan şey.'::text,'sallanıyordu'::text,'sallandı'::text,'sallanmış'::text,'İki el onu yakaladığında dal esintide hafifçe sallanıyordu; tam da ihtiyacı olan şey.'::text),
(336231,37359,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ág épp lágyan ... a szellőben, amikor két kéz megragadta. Pont erre volt szüksége.'::text,'ringatózott'::text,'meglendült'::text,'meglendült'::text,'Az ág épp lágyan ringatózott a szellőben, amikor két kéz megragadta. Pont erre volt szüksége.'::text),
(336297,37367,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Garten ist ..., den die Hände biegen, noch voller Blätter.'::text,'der Ast'::text,'ein Ast'::text,'Ast'::text,'Im Garten ist der Ast, den die Hände biegen, noch voller Blätter.'::text),
(336301,37367,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У саду ..., яку гнуть руки, досі вкрита листям.'::text,'гілка'::text,'гілка'::text,'гілка'::text,'У саду гілка, яку гнуть руки, досі вкрита листям.'::text),
(336300,37367,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En el jardín, ... que doblan las manos sigue cubierta de hojas.'::text,'la rama'::text,'una rama'::text,'rama'::text,'En el jardín, la rama que doblan las manos sigue cubierta de hojas.'::text),
(336299,37367,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans le jardin, ... que les mains plient est encore couverte de feuilles.'::text,'la branche'::text,'une branche'::text,'branche'::text,'Dans le jardin, la branche que les mains plient est encore couverte de feuilles.'::text),
(336302,37367,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bahçede, ellerin büktüğü ... hâlâ yapraklarla kaplı.'::text,'dal'::text,'bir dal'::text,'dal'::text,'Bahçede, ellerin büktüğü dal hâlâ yapraklarla kaplı.'::text),
(336303,37367,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kertben ..., amelyet a kezek hajlítanak, még mindig tele van levelekkel.'::text,'az ág'::text,'egy ág'::text,'ág'::text,'A kertben az ág, amelyet a kezek hajlítanak, még mindig tele van levelekkel.'::text),
(362505,40279,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Totales Chaos! Die Trainerin ruht sich nie aus, und ...'::text,'ihre Schüler auch nicht.'::text,'ihre Schüler auch nicht.'::text,'ihre Schüler auch.'::text,'Totales Chaos! Die Trainerin ruht sich nie aus, und ihre Schüler auch nicht.'::text),
(362509,40279,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Повний хаос! Інструкторка ніколи не відпочиває, і ...'::text,'її учні також ні.'::text,'її учні також ні.'::text,'її учні теж.'::text,'Повний хаос! Інструкторка ніколи не відпочиває, і її учні також ні.'::text),
(362508,40279,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Caos total! La instructora nunca descansa, y ...'::text,'sus alumnos tampoco.'::text,'sus alumnos tampoco.'::text,'sus alumnos también.'::text,'¡Caos total! La instructora nunca descansa, y sus alumnos tampoco.'::text),
(362507,40279,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaos total ! La prof ne se repose jamais, et ...'::text,'ses élèves non plus.'::text,'ses élèves non plus.'::text,'ses élèves aussi.'::text,'Chaos total ! La prof ne se repose jamais, et ses élèves non plus.'::text),
(362510,40279,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir kaos! Eğitmen hiç dinlenmiyor, ...'::text,'öğrencileri de öyle.'::text,'öğrencileri de öyle.'::text,'öğrencileri de öyle.'::text,'Tam bir kaos! Eğitmen hiç dinlenmiyor, öğrencileri de öyle.'::text),
(362511,40279,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teljes káosz! Az oktató sosem pihen, és ...'::text,'a tanítványai sem.'::text,'a tanítványai sem.'::text,'a tanítványai is.'::text,'Teljes káosz! Az oktató sosem pihen, és a tanítványai sem.'::text),
(362577,40287,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Schüler hat zu spät getreten; er ... die Trainerin genauer beobachten sollen.'::text,'hätte'::text,'muss'::text,'kann nicht'::text,'Ein Schüler hat zu spät getreten; er hätte die Trainerin genauer beobachten sollen.'::text),
(362581,40287,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Один учень ударив запізно; він ... уважніше стежити за інструкторкою.'::text,'мав'::text,'мусив'::text,'не міг'::text,'Один учень ударив запізно; він мав уважніше стежити за інструкторкою.'::text),
(362580,40287,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un alumno dio la patada demasiado tarde; él ... observado a la instructora con más atención.'::text,'debería haber'::text,'debe de haber'::text,'no puede haber'::text,'Un alumno dio la patada demasiado tarde; él debería haber observado a la instructora con más atención.'::text),
(362579,40287,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un élève a donné son coup trop tard ; il ... regarder la prof plus attentivement.'::text,'aurait dû'::text,'a dû'::text,'n''a pas pu'::text,'Un élève a donné son coup trop tard ; il aurait dû regarder la prof plus attentivement.'::text),
(362582,40287,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir öğrenci tekmeyi çok geç attı; o eğitmeni daha dikkatli ...'::text,'izlemeliydi'::text,'izlemiş olmalı'::text,'izlemiş olamaz'::text,'Bir öğrenci tekmeyi çok geç attı; o eğitmeni daha dikkatli izlemeliydi.'::text),
(362583,40287,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egyik tanítvány túl későn rúgott; neki ... az oktatót.'::text,'jobban kellett volna figyelnie'::text,'biztosan jobban figyelte'::text,'nem figyelhette jobban'::text,'Az egyik tanítvány túl későn rúgott; neki jobban kellett volna figyelnie az oktatót.'::text),
(336018,37336,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Freundin sagte, das Armband ... zu locker, also stellte sie es enger.'::text,'war'::text,'ist'::text,'wird'::text,'Ihre Freundin sagte, das Armband war zu locker, also stellte sie es enger.'::text),
(336022,37336,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її подруга сказала, що браслет ... занадто вільний, тож вона його поправила.'::text,'був'::text,'є'::text,'буде'::text,'Її подруга сказала, що браслет був занадто вільний, тож вона його поправила.'::text),
(336021,37336,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su amiga dijo que la pulsera ... demasiado floja, así que se la ajustó.'::text,'estaba'::text,'está'::text,'estará'::text,'Su amiga dijo que la pulsera estaba demasiado floja, así que se la ajustó.'::text),
(336020,37336,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son amie a dit que le bracelet ... trop lâche, alors elle l''a ajusté.'::text,'était'::text,'est'::text,'sera'::text,'Son amie a dit que le bracelet était trop lâche, alors elle l''a ajusté.'::text),
(336023,37336,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşı bileziğin çok bol ... söyledi, o da onu ayarladı.'::text,'olduğunu'::text,'olduğunu'::text,'olacağını'::text,'Arkadaşı bileziğin çok bol olduğunu söyledi, o da onu ayarladı.'::text),
(336024,37336,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátnője azt mondta, hogy a karkötő túl laza ..., ezért megigazította.'::text,'volt'::text,NULL::text,'lesz'::text,'A barátnője azt mondta, hogy a karkötő túl laza volt, ezért megigazította.'::text),
(336054,37340,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... gerade das Armband an das Handgelenk ihrer Bestie, kein Witz.'::text,'bindet'::text,'bindet'::text,'hat gebunden'::text,'Bro, sie bindet gerade das Armband an das Handgelenk ihrer Bestie, kein Witz.'::text),
(336058,37340,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона прямо зараз ... браслет на зап''ясті своєї найкращої подруги, без брехні.'::text,'застібає'::text,'застібає'::text,'застебнула'::text,'Бро, вона прямо зараз застібає браслет на зап''ясті своєї найкращої подруги, без брехні.'::text),
(336057,37340,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella ... la pulsera en la muñeca de su mejor amiga ahora mismo, en serio.'::text,'está abrochando'::text,'abrocha'::text,'ha abrochado'::text,'Bro, ella está abrochando la pulsera en la muñeca de su mejor amiga ahora mismo, en serio.'::text),
(336056,37340,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... le bracelet au poignet de sa meilleure pote en ce moment, sans mentir.'::text,'attache'::text,'attache'::text,'a attaché'::text,'Frérot, elle attache le bracelet au poignet de sa meilleure pote en ce moment, sans mentir.'::text),
(336059,37340,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o şu anda kankasının bileğine bilekliği ..., yemin ederim.'::text,'takıyor'::text,'takar'::text,'taktı'::text,'Kanka, o şu anda kankasının bileğine bilekliği takıyor, yemin ederim.'::text),
(336060,37340,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő épp most ... a karkötőt a legjobb barátnője csuklójára, nem kamu.'::text,'csatolja'::text,'csatolja'::text,'csatolta'::text,'Tesó, ő épp most csatolja a karkötőt a legjobb barátnője csuklójára, nem kamu.'::text),
(391539,43505,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, der Typ, ... ihre Taschen die Treppe hochgetragen hat, ist angeblich nur vorbeigejoggt.'::text,'der'::text,'das'::text,'dessen'::text,'Hör mal, der Typ, der ihre Taschen die Treppe hochgetragen hat, ist angeblich nur vorbeigejoggt.'::text),
(391543,43505,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, хлопець, ... заніс її сумки сходами, просто пробігав повз.'::text,'який'::text,'що'::text,'чий'::text,'Слухай, кажуть, хлопець, який заніс її сумки сходами, просто пробігав повз.'::text),
(391542,43505,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer el chico ... le subió las bolsas por las escaleras solo pasaba corriendo.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Oye, al parecer el chico que le subió las bolsas por las escaleras solo pasaba corriendo.'::text),
(391541,43505,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment le mec ... a monté ses sacs dans l''escalier passait juste en joggant.'::text,'qui'::text,'que'::text,'dont'::text,'Écoute, apparemment le mec qui a monté ses sacs dans l''escalier passait juste en joggant.'::text),
(391544,43505,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya çantalarını merdivenlerden ... çıkaran çocuk sadece koşarken oradan geçiyormuş.'::text,''::text,NULL::text,NULL::text,'Dinle, güya çantalarını merdivenlerden çıkaran çocuk sadece koşarken oradan geçiyormuş.'::text),
(391545,43505,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag a srác, ... felvitte a szatyrait a lépcsőn, csak arra kocogott.'::text,'aki'::text,'ami'::text,'akinek a'::text,'Figyelj, állítólag a srác, aki felvitte a szatyrait a lépcsőn, csak arra kocogott.'::text),
(368364,40930,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ungefähr vierzig Studierende ... seit Mittag auf der Clubmesse eine Mitgliedschaft.'::text,'beantragen'::text,'beantragen'::text,'beantragen'::text,'Ungefähr vierzig Studierende beantragen seit Mittag auf der Clubmesse eine Mitgliedschaft.'::text),
(368368,40930,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Приблизно сорок студентів ... на членство на клубному ярмарку від обіду.'::text,'подають заявки'::text,'подають заявки'::text,'подають заявки'::text,'Приблизно сорок студентів подають заявки на членство на клубному ярмарку від обіду.'::text),
(368367,40930,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aproximadamente cuarenta estudiantes ... la membresía en la feria de clubes desde mediodía.'::text,'han estado solicitando'::text,'están solicitando'::text,'solicitan'::text,'Aproximadamente cuarenta estudiantes han estado solicitando la membresía en la feria de clubes desde mediodía.'::text),
(368366,40930,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Environ quarante étudiants ... leur adhésion au salon des clubs depuis midi.'::text,'demandent'::text,'sont en train de demander'::text,'demandent'::text,'Environ quarante étudiants demandent leur adhésion au salon des clubs depuis midi.'::text),
(368369,40930,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaklaşık kırk öğrenci öğleden beri kulüp fuarında üyelik için ...'::text,'başvuruyor'::text,'başvuruyor'::text,'başvurur'::text,'Yaklaşık kırk öğrenci öğleden beri kulüp fuarında üyelik için başvuruyor.'::text),
(368370,40930,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Körülbelül negyven hallgató dél óta ... tagságért a klubvásáron.'::text,'jelentkezik'::text,'jelentkezik'::text,'jelentkezik'::text,'Körülbelül negyven hallgató dél óta jelentkezik tagságért a klubvásáron.'::text),
(368445,40939,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende der Messe ... der Club dreißig neue Mitgliedsanträge bekommen haben.'::text,'wird'::text,'wird'::text,'bekommt'::text,'Bis zum Ende der Messe wird der Club dreißig neue Mitgliedsanträge bekommen haben.'::text),
(368449,40939,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця ярмарку клуб ... тридцять нових заявок на членство.'::text,'отримає'::text,'отримає'::text,'отримує'::text,'До кінця ярмарку клуб отримає тридцять нових заявок на членство.'::text),
(368448,40939,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final de la feria, el club ... treinta nuevas solicitudes de membresía.'::text,'habrá recibido'::text,'recibirá'::text,'recibe'::text,'Para el final de la feria, el club habrá recibido treinta nuevas solicitudes de membresía.'::text),
(368447,40939,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin du salon, le club ... trente nouveaux formulaires d''adhésion.'::text,'aura reçu'::text,'recevra'::text,'reçoit'::text,'D''ici la fin du salon, le club aura reçu trente nouveaux formulaires d''adhésion.'::text),
(368450,40939,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fuarın sonuna kadar kulüp otuz yeni üyelik formu ...'::text,'almış olacak'::text,'alacak'::text,'alıyor'::text,'Fuarın sonuna kadar kulüp otuz yeni üyelik formu almış olacak.'::text),
(368451,40939,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vásár végére a klub ... harminc új tagsági űrlapot.'::text,'megkap'::text,'meg fog kapni'::text,'kap'::text,'A vásár végére a klub megkap harminc új tagsági űrlapot.'::text),
(341292,37922,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zunächst ... ein Setzling von drei Mitgliedern der Gemeinschaft in das Hochbeet gedrückt.'::text,'wurde'::text,'wird'::text,'drückte'::text,'Zunächst wurde ein Setzling von drei Mitgliedern der Gemeinschaft in das Hochbeet gedrückt.'::text),
(341296,37922,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спочатку розсаду ... в підняту грядку трьома членами громади.'::text,'було вдавлено'::text,'вдавлюють'::text,'вдавила'::text,'Спочатку розсаду було вдавлено в підняту грядку трьома членами громади.'::text),
(341295,37922,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Inicialmente, un plantón ... en el bancal elevado por tres miembros de la comunidad.'::text,'fue presionado'::text,'es presionado'::text,'presionó'::text,'Inicialmente, un plantón fue presionado en el bancal elevado por tres miembros de la comunidad.'::text),
(341294,37922,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au départ, un semis ... dans le bac surélevé par trois membres de la communauté.'::text,'a été enfoncé'::text,'est enfoncé'::text,'a enfoncé'::text,'Au départ, un semis a été enfoncé dans le bac surélevé par trois membres de la communauté.'::text),
(341297,37922,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başlangıçta bir fide topluluğun üç üyesi tarafından yükseltilmiş yatağa ...'::text,'bastırıldı'::text,'bastırılıyor'::text,'bastırdı'::text,'Başlangıçta bir fide topluluğun üç üyesi tarafından yükseltilmiş yatağa bastırıldı.'::text),
(341298,37922,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kezdetben egy palántát ... a magaságyásba a közösség három tagja.'::text,'nyomott bele'::text,'nyom bele'::text,'belenyomta'::text,'Kezdetben egy palántát nyomott bele a magaságyásba a közösség három tagja.'::text),
(397803,44201,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Trail ist ein Albtraum! Ich ... buchstäblich an jeder Wurzel ständig nach Luft!'::text,'schnappe'::text,'schnappe'::text,'schnappe'::text,'Dieser Trail ist ein Albtraum! Ich schnappe buchstäblich an jeder Wurzel ständig nach Luft!'::text),
(397807,44201,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця стежка — жах! Я буквально весь час ... повітря на кожному корені!'::text,'хапаю'::text,'хапаю'::text,'хапаю'::text,'Ця стежка — жах! Я буквально весь час хапаю повітря на кожному корені!'::text),
(397806,44201,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Este sendero es una pesadilla! ¡Yo literalmente sigo ... en cada raíz!'::text,'jadeando'::text,'jadear'::text,'jadear'::text,'¡Este sendero es una pesadilla! ¡Yo literalmente sigo jadeando en cada raíz!'::text),
(397805,44201,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce sentier est un cauchemar ! Je passe littéralement mon temps à ... mon souffle à chaque racine !'::text,'chercher'::text,'chercher'::text,'chercher'::text,'Ce sentier est un cauchemar ! Je passe littéralement mon temps à chercher mon souffle à chaque racine !'::text),
(397808,44201,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu patika tam bir kâbus! Ben resmen her kökte soluk soluğa ... devam ediyorum!'::text,'kalmaya'::text,'kalmak'::text,'kal'::text,'Bu patika tam bir kâbus! Ben resmen her kökte soluk soluğa kalmaya devam ediyorum!'::text),
