(338336,37593,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hemşire hastaya bakıyor, ...'::text,'meslektaşları da öyle.'::text,'meslektaşları da öyle.'::text,'meslektaşları da bakmıyor.'::text,'Hemşire hastaya bakıyor, meslektaşları da öyle.'::text),
