(391994,43555,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün taksi yoğun saatte tek elle ...; belli ki şehrin en güvenli yolculuğu.'::text,'sürüldü'::text,'sürülüyor'::text,'sürdü'::text,'Dün taksi yoğun saatte tek elle sürüldü; belli ki şehrin en güvenli yolculuğu.'::text),
(391995,43555,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap a taxit egy kézzel ... a csúcsforgalomban. Nyilván a város legbiztonságosabb fuvarja.'::text,'vezették'::text,'vezetik'::text,'vezette'::text,'Tegnap a taxit egy kézzel vezették a csúcsforgalomban. Nyilván a város legbiztonságosabb fuvarja.'::text),
(359661,39963,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du ... das Headset heute zehnmal auf- und abgesetzt, und es sieht immer noch ikonisch aus.'::text,'hast'::text,'hast'::text,'setzt'::text,'Ehrlich gesagt, du hast das Headset heute zehnmal auf- und abgesetzt, und es sieht immer noch ikonisch aus.'::text),
(359665,39963,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брешу, ти сьогодні десять разів ... цю гарнітуру, і вона все одно виглядає культово.'::text,'надягала й знімала'::text,'надягала й знімала'::text,'надягаєш і знімаєш'::text,'Не брешу, ти сьогодні десять разів надягала й знімала цю гарнітуру, і вона все одно виглядає культово.'::text),
(359664,39963,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, tú ... ese casco diez veces hoy, y sigue viéndose icónico.'::text,'te has puesto y quitado'::text,'te has estado poniendo y quitando'::text,'te estás poniendo y quitando'::text,'No te voy a mentir, tú te has puesto y quitado ese casco diez veces hoy, y sigue viéndose icónico.'::text),
(359663,39963,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... ce casque dix fois aujourd''hui, et il a toujours l''air iconique.'::text,'as mis et enlevé'::text,'as mis et enlevé'::text,'mets et enlèves'::text,'Je vais pas mentir, tu as mis et enlevé ce casque dix fois aujourd''hui, et il a toujours l''air iconique.'::text),
(359666,39963,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, sen bugün o başlığı on kez ... ve hâlâ efsane görünüyor.'::text,'takıp çıkardın'::text,'takıp çıkarıyordun'::text,'takıp çıkarıyorsun'::text,'Yalan yok, sen bugün o başlığı on kez takıp çıkardın ve hâlâ efsane görünüyor.'::text),
(359667,39963,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, te ma tízszer ... azt a headsetet, és még mindig ikonikusan néz ki.'::text,'vetted fel és le'::text,'vetted fel és le'::text,'veszed fel és le'::text,'Nem hazudok, te ma tízszer vetted fel és le azt a headsetet, és még mindig ikonikusan néz ki.'::text),
(341391,37933,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Kind ... sie einen Spielzeugkompass in ihrem Zimmer.'::text,'hatte'::text,'hatte'::text,'war gewohnt zu haben'::text,'Als Kind hatte sie einen Spielzeugkompass in ihrem Zimmer.'::text),
(341395,37933,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У дитинстві вона ... іграшковий компас у своїй спальні.'::text,'мала'::text,'мала'::text,'звикла мати'::text,'У дитинстві вона мала іграшковий компас у своїй спальні.'::text),
(341394,37933,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De niña, ella ... una brújula de juguete en su habitación.'::text,'solía tener'::text,'tenía'::text,'estaba acostumbrada a tener'::text,'De niña, ella solía tener una brújula de juguete en su habitación.'::text),
(341393,37933,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Enfant, elle ... une boussole jouet dans sa chambre.'::text,'avait'::text,'avait'::text,'avait l''habitude d''avoir'::text,'Enfant, elle avait une boussole jouet dans sa chambre.'::text),
(341396,37933,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocukken onun yatak odasında oyuncak bir pusulası ...'::text,'vardı'::text,'vardı'::text,'olmaya alışkındı'::text,'Çocukken onun yatak odasında oyuncak bir pusulası vardı.'::text),
(341397,37933,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gyerekkorában neki ... egy játékiránytűje a hálószobájában.'::text,'volt'::text,'volt'::text,'hozzá volt szokva, hogy legyen'::text,'Gyerekkorában neki volt egy játékiránytűje a hálószobájában.'::text),
(341445,37939,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Kompass nur einmal, bevor sie hinausfuhr. Makellose Planung.'::text,'prüfte'::text,'prüfte'::text,'prüfte'::text,'Sie prüfte den Kompass nur einmal, bevor sie hinausfuhr. Makellose Planung.'::text),
(341449,37939,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... компас лише раз, перш ніж вийти в море. Бездоганне планування.'::text,'перевірила'::text,'перевірила'::text,'перевіряла'::text,'Вона перевірила компас лише раз, перш ніж вийти в море. Бездоганне планування.'::text),
(341448,37939,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... la brújula solo una vez antes de zarpar. Planificación impecable.'::text,'había revisado'::text,'ha revisado'::text,'estaba revisando'::text,'Ella había revisado la brújula solo una vez antes de zarpar. Planificación impecable.'::text),
(341447,37939,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la boussole une seule fois avant de prendre la mer. Planification impeccable.'::text,'avait vérifié'::text,'a vérifié'::text,'vérifiait'::text,'Elle avait vérifié la boussole une seule fois avant de prendre la mer. Planification impeccable.'::text),
(341450,37939,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, denize açılmadan önce pusulayı yalnızca bir kez ...; kusursuz planlama.'::text,'kontrol etmişti'::text,'kontrol etti'::text,'kontrol ediyordu'::text,'O, denize açılmadan önce pusulayı yalnızca bir kez kontrol etmişti; kusursuz planlama.'::text),
(341451,37939,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő csak egyszer ... az iránytűt, mielőtt kihajózott. Hibátlan tervezés.'::text,'nézte meg'::text,'nézte meg'::text,'nézegette'::text,'Ő csak egyszer nézte meg az iránytűt, mielőtt kihajózott. Hibátlan tervezés.'::text),
(337053,37451,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während der Metzger das Steak ..., wartete der Kunde an der Theke.'::text,'wog'::text,'wog'::text,'hat gewogen'::text,'Während der Metzger das Steak wog, wartete der Kunde an der Theke.'::text),
(337057,37451,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки м''ясник ... стейк, покупець чекав біля прилавка.'::text,'зважував'::text,'зважив'::text,'зважив'::text,'Поки м''ясник зважував стейк, покупець чекав біля прилавка.'::text),
(337056,37451,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras el carnicero ... el filete, el cliente esperaba en el mostrador.'::text,'pesaba'::text,'pesó'::text,'ha pesado'::text,'Mientras el carnicero pesaba el filete, el cliente esperaba en el mostrador.'::text),
(337055,37451,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que le boucher ... le steak, le client attendait au comptoir.'::text,'pesait'::text,'pesa'::text,'a pesé'::text,'Pendant que le boucher pesait le steak, le client attendait au comptoir.'::text),
(337058,37451,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kasap bifteği ..., müşteri tezgâhta bekledi.'::text,'tartarken'::text,'tarttı'::text,'tartmış'::text,'Kasap bifteği tartarken, müşteri tezgâhta bekledi.'::text),
(337059,37451,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amíg a hentes ... a steaket, a vevő a pultnál várt.'::text,'mérte'::text,'lemérte'::text,'lemérte'::text,'Amíg a hentes mérte a steaket, a vevő a pultnál várt.'::text),
(337143,37461,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag ... der Metzger alle Steaks in der Glastheke verkauft haben.'::text,'wird'::text,'wird'::text,'verkauft'::text,'Bis Mittag wird der Metzger alle Steaks in der Glastheke verkauft haben.'::text),
(337147,37461,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня м''ясник ... всі стейки з вітрини.'::text,'продасть'::text,'продаватиме'::text,'продає'::text,'До полудня м''ясник продасть всі стейки з вітрини.'::text),
(337146,37461,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía, el carnicero ... todos los filetes del mostrador de cristal.'::text,'habrá vendido'::text,'venderá'::text,'vende'::text,'Para el mediodía, el carnicero habrá vendido todos los filetes del mostrador de cristal.'::text),
(337145,37461,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, le boucher ... tous les steaks de la vitrine.'::text,'aura vendu'::text,'vendra'::text,'vend'::text,'D''ici midi, le boucher aura vendu tous les steaks de la vitrine.'::text),
(337148,37461,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar kasap cam tezgâhtaki bütün biftekleri ...'::text,'satmış olacak'::text,'satacak'::text,'satıyor'::text,'Öğlene kadar kasap cam tezgâhtaki bütün biftekleri satmış olacak.'::text),
(337149,37461,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre a hentes ... az összes steaket az üvegpultból.'::text,'eladja'::text,'el fogja adni'::text,'árulja'::text,'Délre a hentes eladja az összes steaket az üvegpultból.'::text),
(366825,40759,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er verspricht: Nächstes Mal ... er weniger Gepäck ein. Klar, ein Mann mit sehr wenig Zeug.'::text,'packt'::text,'packt'::text,'packt'::text,'Er verspricht: Nächstes Mal packt er weniger Gepäck ein. Klar, ein Mann mit sehr wenig Zeug.'::text),
(366829,40759,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він обіцяє, що наступного разу ... менше багажу. Явно людина дуже небагатьох речей.'::text,'спакує'::text,'пакуватиме'::text,'пакує'::text,'Він обіцяє, що наступного разу спакує менше багажу. Явно людина дуже небагатьох речей.'::text),
(366828,40759,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él promete que la próxima vez ... menos equipaje. Claramente un hombre de muy pocas cosas.'::text,'llevará'::text,'estará llevando'::text,'lleva'::text,'Él promete que la próxima vez llevará menos equipaje. Claramente un hombre de muy pocas cosas.'::text),
(366827,40759,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il promet qu''il ... moins de bagages la prochaine fois. Clairement un homme de très peu de choses.'::text,'emportera'::text,'sera en train d''emporter'::text,'emporte'::text,'Il promet qu''il emportera moins de bagages la prochaine fois. Clairement un homme de très peu de choses.'::text),
(366830,40759,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, bir dahaki sefere daha az bagaj ... söz veriyor; belli ki çok az eşyası olan biri.'::text,'toplayacağına'::text,'topluyor olacağına'::text,'topladığına'::text,'O, bir dahaki sefere daha az bagaj toplayacağına söz veriyor; belli ki çok az eşyası olan biri.'::text),
(366831,40759,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő megígéri, hogy legközelebb ... kevesebb csomagot. Nyilván nagyon kevés cuccal utazó ember.'::text,'csomagol'::text,'csomagolni fog'::text,'csomagol'::text,'Ő megígéri, hogy legközelebb csomagol kevesebb csomagot. Nyilván nagyon kevés cuccal utazó ember.'::text),
(366870,40764,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte er mehr Gepäck eingepackt, ... er eine zweite Tasche gebraucht.'::text,'hätte'::text,'wird'::text,'brauchte'::text,'Hätte er mehr Gepäck eingepackt, hätte er eine zweite Tasche gebraucht.'::text),
(366874,40764,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він спакував більше багажу, йому ... друга сумка.'::text,'знадобилася б'::text,'знадобиться'::text,'знадобилася'::text,'Якби він спакував більше багажу, йому знадобилася б друга сумка.'::text),
(366873,40764,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si él hubiera metido más equipaje, ... una segunda bolsa.'::text,'habría necesitado'::text,'necesitará'::text,'necesitó'::text,'Si él hubiera metido más equipaje, habría necesitado una segunda bolsa.'::text),
(366872,40764,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait emporté plus de bagages, il ... d''un deuxième sac.'::text,'aurait eu besoin'::text,'aura besoin'::text,'a eu besoin'::text,'S''il avait emporté plus de bagages, il aurait eu besoin d''un deuxième sac.'::text),
(366875,40764,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O daha fazla bagaj toplasaydı, ikinci bir çantaya ...'::text,'ihtiyaç duyardı'::text,'ihtiyaç duyacak'::text,'ihtiyaç duydu'::text,'O daha fazla bagaj toplasaydı, ikinci bir çantaya ihtiyaç duyardı.'::text),
(366876,40764,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ő több csomagot pakolt volna, ... egy második táskára.'::text,'szüksége lett volna'::text,'szüksége lesz'::text,'szüksége volt'::text,'Ha ő több csomagot pakolt volna, szüksége lett volna egy második táskára.'::text),
(376113,41791,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, die Crew ... ihn seit so zehn Minuten mit Lob, er strahlt lowkey, echt jetzt.'::text,'überschüttet'::text,'überschüttet'::text,'überschüttet'::text,'Bro, die Crew überschüttet ihn seit so zehn Minuten mit Lob, er strahlt lowkey, echt jetzt.'::text),
(376117,41791,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, команда ... його похвалою вже хвилин десять, він аж світиться, реально.'::text,'засипає'::text,'засипає'::text,'засипає'::text,'Бро, команда засипає його похвалою вже хвилин десять, він аж світиться, реально.'::text),
(376116,41791,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el equipo lo ... de elogios desde hace como diez minutos, está brillando, en serio.'::text,'ha estado colmando'::text,'está colmando'::text,'colma'::text,'Bro, el equipo lo ha estado colmando de elogios desde hace como diez minutos, está brillando, en serio.'::text),
(376115,41791,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, l''équipe le ... de compliments depuis genre dix minutes, il rayonne grave, sérieux.'::text,'couvre'::text,'couvre'::text,'couvre'::text,'Frère, l''équipe le couvre de compliments depuis genre dix minutes, il rayonne grave, sérieux.'::text),
(376118,41791,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ekip onu on dakikadır övgüye ..., çocuk resmen parlıyor, cidden.'::text,'boğuyor'::text,'boğuyor'::text,'boğar'::text,'Kanka, ekip onu on dakikadır övgüye boğuyor, çocuk resmen parlıyor, cidden.'::text),
(376119,41791,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a stáb vagy tíz perce ... dicsérettel, lowkey ragyog, komolyan.'::text,'halmozza el'::text,'halmozza el'::text,'elhalmozza'::text,'Tesó, a stáb vagy tíz perce halmozza el dicsérettel, lowkey ragyog, komolyan.'::text),
(376158,41796,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich, dass die Crew für immer mit dem Lob ...! Nie wieder Stille!'::text,'weitermachen würde'::text,'weitermachen wird'::text,'weitermacht'::text,'Er wünscht sich, dass die Crew für immer mit dem Lob weitermachen würde! Nie wieder Stille!'::text),
(376162,41796,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хоче, щоб команда ... хвалити його вічно! Більше ніколи тиші!'::text,'продовжувала'::text,'продовжить'::text,'продовжує'::text,'Він хоче, щоб команда продовжувала хвалити його вічно! Більше ніколи тиші!'::text),
(376161,41796,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él desea que el equipo ... con sus elogios para siempre! ¡Nunca más silencio!'::text,'siguiera'::text,'seguirá'::text,'sigue'::text,'¡Él desea que el equipo siguiera con sus elogios para siempre! ¡Nunca más silencio!'::text),
(376160,41796,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il voudrait que l''équipe ... ses compliments pour toujours ! Plus jamais de silence !'::text,'continue'::text,'continuera'::text,'continue'::text,'Il voudrait que l''équipe continue ses compliments pour toujours ! Plus jamais de silence !'::text),
(376163,41796,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, ekibin övgülerine sonsuza dek ... istiyor! Bir daha asla sessizlik yok!'::text,'devam etmesini'::text,'devam edeceğini'::text,'devam ettiğini'::text,'O, ekibin övgülerine sonsuza dek devam etmesini istiyor! Bir daha asla sessizlik yok!'::text),
(376164,41796,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő azt szeretné, ha a stáb örökké ... a dicsérettel! Soha többé csend!'::text,'folytatná'::text,'folytatni fogja'::text,'folytatja'::text,'Ő azt szeretné, ha a stáb örökké folytatná a dicsérettel! Soha többé csend!'::text),
(358707,39857,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte, das Kleid ... zu lang für den schmalen Gang.'::text,'war'::text,'ist'::text,'ist gewesen'::text,'Sie sagte, das Kleid war zu lang für den schmalen Gang.'::text),
(358711,39857,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що сукня ... задовга для вузького коридору.'::text,'була'::text,'є'::text,'була'::text,'Вона сказала, що сукня була задовга для вузького коридору.'::text),
(358710,39857,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella dijo que el vestido ... demasiado largo para el pasillo estrecho.'::text,'era'::text,'está siendo'::text,'ha sido'::text,'Ella dijo que el vestido era demasiado largo para el pasillo estrecho.'::text),
(358709,39857,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit que la robe ... trop longue pour le couloir étroit.'::text,'était'::text,'est'::text,'a été'::text,'Elle a dit que la robe était trop longue pour le couloir étroit.'::text),
(358712,39857,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, gece elbisesinin dar koridor için fazla uzun ... söyledi.'::text,'olduğunu'::text,'olduğunu'::text,'olduğunu'::text,'O, gece elbisesinin dar koridor için fazla uzun olduğunu söyledi.'::text),
(358713,39857,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő azt mondta, hogy az estélyi ... túl hosszú a szűk folyosóhoz.'::text,'volt'::text,NULL::text,'volt'::text,'Ő azt mondta, hogy az estélyi volt túl hosszú a szűk folyosóhoz.'::text),
(358734,39860,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich ... sie gerade in dem goldenen Kleid auf der Bühne.'::text,'steht'::text,'steht'::text,'hat gestanden'::text,'Girl, angeblich steht sie gerade in dem goldenen Kleid auf der Bühne.'::text),
(358738,39860,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона прямо зараз ... у тій золотій сукні на сцені.'::text,'стоїть'::text,'стоїть'::text,'стояла'::text,'Подруго, кажуть, вона прямо зараз стоїть у тій золотій сукні на сцені.'::text),
(358737,39860,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ella ... con ese vestido dorado en el escenario ahora mismo.'::text,'está'::text,'está'::text,'ha estado'::text,'Tía, al parecer ella está con ese vestido dorado en el escenario ahora mismo.'::text),
(358736,39860,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle ... dans cette robe dorée sur scène en ce moment.'::text,'se tient'::text,'se tient'::text,'s''est tenue'::text,'Meuf, apparemment elle se tient dans cette robe dorée sur scène en ce moment.'::text),
(358739,39860,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya o şu anda o altın elbiseyle sahnede ...'::text,'duruyormuş'::text,'durur'::text,'durdu'::text,'Kızım, güya o şu anda o altın elbiseyle sahnede duruyormuş.'::text),
(358740,39860,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ő épp most ... abban az arany estélyiben a színpadon.'::text,'áll'::text,'áll'::text,'állt'::text,'Csajszi, állítólag ő épp most áll abban az arany estélyiben a színpadon.'::text),
(375303,41701,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, dein Pferdeschwanz ... wild hin und her, als du plötzlich stehen geblieben bist, ikonisch.'::text,'schwang'::text,'schwang'::text,'ist geschwungen'::text,'Ehrlich, dein Pferdeschwanz schwang wild hin und her, als du plötzlich stehen geblieben bist, ikonisch.'::text),
(375307,41701,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, твій хвіст дико ..., коли ти раптом зупинилася, культово.'::text,'гойдався'::text,'гойднувся'::text,'гойднувся'::text,'Чесно, твій хвіст дико гойдався, коли ти раптом зупинилася, культово.'::text),
(375306,41701,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, tu coleta ... como loca cuando de repente te paraste, icónico.'::text,'se balanceaba'::text,'se balanceó'::text,'se ha balanceado'::text,'La verdad, tu coleta se balanceaba como loca cuando de repente te paraste, icónico.'::text),
(375305,41701,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Honnêtement, ta queue-de-cheval ... dans tous les sens quand tu t''es arrêtée d''un coup, iconique.'::text,'se balançait'::text,'se balança'::text,'s''est balancée'::text,'Honnêtement, ta queue-de-cheval se balançait dans tous les sens quand tu t''es arrêtée d''un coup, iconique.'::text),
(375308,41701,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sen aniden durduğunda at kuyruğun deli gibi ..., efsane.'::text,'sallanıyordu'::text,'sallandı'::text,'sallanmış'::text,'Açıkçası, sen aniden durduğunda at kuyruğun deli gibi sallanıyordu, efsane.'::text),
(375309,41701,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, a lófarkad vadul ..., amikor hirtelen megálltál, ikonikus.'::text,'lengett'::text,'meglendült'::text,'meglendült'::text,'Őszintén, a lófarkad vadul lengett, amikor hirtelen megálltál, ikonikus.'::text),
(375798,41756,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie trat zurück, um das Porträt aus der Ferne ...'::text,'anzusehen'::text,'ansehen'::text,'sah an'::text,'Sie trat zurück, um das Porträt aus der Ferne anzusehen.'::text),
(375802,41756,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона відступила назад, ... портрет здалеку.'::text,'щоб подивитися на'::text,'подивитися на'::text,'подивилася на'::text,'Вона відступила назад, щоб подивитися на портрет здалеку.'::text),
(375801,41756,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella dio un paso atrás ... el retrato de lejos.'::text,'para mirar'::text,'mirar'::text,'miró'::text,'Ella dio un paso atrás para mirar el retrato de lejos.'::text),
(375800,41756,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a reculé ... le portrait de loin.'::text,'pour regarder'::text,'regarder'::text,'regarda'::text,'Elle a reculé pour regarder le portrait de loin.'::text),
(375803,41756,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, portreye uzaktan ... geri çekildi.'::text,'bakmak için'::text,'bakmak'::text,'baktı'::text,'O, portreye uzaktan bakmak için geri çekildi.'::text),
(375804,41756,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő hátrébb lépett, ... a portrét messziről.'::text,'hogy megnézze'::text,'megnézni'::text,'megnézte'::text,'Ő hátrébb lépett, hogy megnézze a portrét messziről.'::text),
(375825,41759,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Künstlerin ... etwa zwei Stunden lang Farbe auf, bevor das Porträt sichtbar wurde.'::text,'trug'::text,'trägt'::text,'trug'::text,'Die Künstlerin trug etwa zwei Stunden lang Farbe auf, bevor das Porträt sichtbar wurde.'::text),
(375829,41759,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Художниця ... фарбу приблизно дві години, перш ніж з''явився портрет.'::text,'наносила'::text,'наносить'::text,'наносила'::text,'Художниця наносила фарбу приблизно дві години, перш ніж з''явився портрет.'::text),
(375828,41759,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La artista ... pintura durante aproximadamente dos horas antes de que apareciera el retrato.'::text,'había estado aplicando'::text,'ha estado aplicando'::text,'estaba aplicando'::text,'La artista había estado aplicando pintura durante aproximadamente dos horas antes de que apareciera el retrato.'::text),
(375827,41759,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''artiste ... de la peinture pendant environ deux heures avant que le portrait apparaisse.'::text,'appliquait'::text,'applique'::text,'appliquait'::text,'L''artiste appliquait de la peinture pendant environ deux heures avant que le portrait apparaisse.'::text),
(375830,41759,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sanatçı, portre ortaya çıkmadan önce yaklaşık iki saat boyunca boya ...'::text,'sürüyordu'::text,'sürüyor'::text,'sürüyordu'::text,'Sanatçı, portre ortaya çıkmadan önce yaklaşık iki saat boyunca boya sürüyordu.'::text),
(375831,41759,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A művész körülbelül két órán át ... a festéket, mielőtt megjelent a portré.'::text,'hordta fel'::text,'hordja fel'::text,'hordta fel'::text,'A művész körülbelül két órán át hordta fel a festéket, mielőtt megjelent a portré.'::text),
(387597,43067,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie verspricht: Gleich nach dem Puder ... sie auf die Skyline. Natürlich.'::text,'schaut'::text,'wird schauen'::text,'schaut gerade'::text,'Sie verspricht: Gleich nach dem Puder schaut sie auf die Skyline. Natürlich.'::text),
(387601,43067,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона обіцяє, що ... на панораму міста одразу після пудри. Звісно.'::text,'подивиться'::text,'дивитиметься'::text,'дивиться'::text,'Вона обіцяє, що подивиться на панораму міста одразу після пудри. Звісно.'::text),
(387600,43067,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella promete que ... el horizonte de la ciudad justo después de los polvos. Obviamente.'::text,'mirará'::text,'estará mirando'::text,'está mirando'::text,'Ella promete que mirará el horizonte de la ciudad justo después de los polvos. Obviamente.'::text),
(387599,43067,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle promet qu''elle ... la skyline juste après la poudre. Évidemment.'::text,'regardera'::text,'sera en train de regarder'::text,'regarde'::text,'Elle promet qu''elle regardera la skyline juste après la poudre. Évidemment.'::text),
(387602,43067,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, pudradan hemen sonra şehir silüetine ... söz veriyor; tabii ki.'::text,'bakacağına'::text,'bakıyor olacağına'::text,'baktığına'::text,'O, pudradan hemen sonra şehir silüetine bakacağına söz veriyor; tabii ki.'::text),
(387603,43067,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő megígéri, hogy rögtön a púder után ... a városképre. Nyilván.'::text,'ránéz'::text,'nézni fog'::text,'néz'::text,'Ő megígéri, hogy rögtön a púder után ránéz a városképre. Nyilván.'::text),
(387669,43075,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... du dein Make-up mit der ganzen Skyline hinter dir. Ikonisch.'::text,'machst'::text,'machst'::text,'hast gemacht'::text,'Gerade machst du dein Make-up mit der ganzen Skyline hinter dir. Ikonisch.'::text),
(387673,43075,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто зараз ти ... макіяж, а за тобою вся панорама міста. Культово.'::text,'робиш'::text,'робиш'::text,'зробила'::text,'Просто зараз ти робиш макіяж, а за тобою вся панорама міста. Культово.'::text),
(387672,43075,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo tú te ... el maquillaje con todo el horizonte de la ciudad detrás. Icónico.'::text,'estás haciendo'::text,'haces'::text,'has hecho'::text,'Ahora mismo tú te estás haciendo el maquillaje con todo el horizonte de la ciudad detrás. Icónico.'::text),
(387671,43075,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, tu ... ton maquillage avec toute la skyline derrière toi. Iconique.'::text,'fais'::text,'fais'::text,'as fait'::text,'En ce moment, tu fais ton maquillage avec toute la skyline derrière toi. Iconique.'::text),
(387674,43075,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda sen arkanda bütün şehir silüetiyle makyajını ...; efsane.'::text,'yapıyorsun'::text,'yaparsın'::text,'yaptın'::text,'Şu anda sen arkanda bütün şehir silüetiyle makyajını yapıyorsun; efsane.'::text),
(387675,43075,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te épp most ... a sminkedet, mögötted az egész városképpel. Ikonikus.'::text,'csinálod'::text,'csinálod'::text,'megcsináltad'::text,'Te épp most csinálod a sminkedet, mögötted az egész városképpel. Ikonikus.'::text),
(383691,42633,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Wanderer ... seit dem frühen Morgen durch diese Berglandschaft.'::text,'laufen'::text,'laufen'::text,'laufen'::text,'Die Wanderer laufen seit dem frühen Morgen durch diese Berglandschaft.'::text),
(383695,42633,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Туристи ... цими гірськими краєвидами з самого ранку.'::text,'ідуть'::text,'ідуть'::text,'ходять'::text,'Туристи ідуть цими гірськими краєвидами з самого ранку.'::text),
(383694,42633,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los excursionistas ... por este paisaje de montaña desde primera hora de la mañana.'::text,'han estado caminando'::text,'están caminando'::text,'caminan'::text,'Los excursionistas han estado caminando por este paisaje de montaña desde primera hora de la mañana.'::text),
(383693,42633,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les randonneurs ... dans ce paysage de montagne depuis tôt ce matin.'::text,'marchent'::text,'sont en train de marcher'::text,'marchent'::text,'Les randonneurs marchent dans ce paysage de montagne depuis tôt ce matin.'::text),
(383696,42633,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yürüyüşçüler sabahın erken saatlerinden beri bu dağ manzarasında ...'::text,'yürüyor'::text,'yürüyor'::text,'yürür'::text,'Yürüyüşçüler sabahın erken saatlerinden beri bu dağ manzarasında yürüyor.'::text),
(383697,42633,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A túrázók kora reggel óta ... ebben a hegyvidéki tájban.'::text,'gyalogolnak'::text,'gyalogolnak'::text,'gyalogolnak'::text,'A túrázók kora reggel óta gyalogolnak ebben a hegyvidéki tájban.'::text),
(383736,42638,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich wünschte, ich ... meine Kamera mitgenommen! So eine Landschaft, für immer verloren!'::text,'hätte'::text,'habe'::text,'hatte'::text,'Ich wünschte, ich hätte meine Kamera mitgenommen! So eine Landschaft, für immer verloren!'::text),
(383740,42638,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ж я ... свій фотоапарат! Такі краєвиди — назавжди втрачені!'::text,'взяв'::text,'взяв'::text,'взяв'::text,'Якби ж я взяв свій фотоапарат! Такі краєвиди — назавжди втрачені!'::text),
(383739,42638,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ojalá yo ... mi cámara! ¡Un paisaje así, perdido para siempre!'::text,'hubiera traído'::text,'he traído'::text,'traje'::text,'¡Ojalá yo hubiera traído mi cámara! ¡Un paisaje así, perdido para siempre!'::text),
(383738,42638,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'J''aurais tellement voulu ... mon appareil photo ! Un paysage pareil, perdu à jamais !'::text,'avoir pris'::text,'avoir pris'::text,'prendre'::text,'J''aurais tellement voulu avoir pris mon appareil photo ! Un paysage pareil, perdu à jamais !'::text),
(383741,42638,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke ben fotoğraf makinemi ...! Böyle bir manzara, sonsuza dek kayıp!'::text,'getirseydim'::text,'getirdim'::text,'getirdim'::text,'Keşke ben fotoğraf makinemi getirseydim! Böyle bir manzara, sonsuza dek kayıp!'::text),
(383742,42638,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak én ... a fényképezőgépemet! Ilyen táj, örökre elveszett!'::text,'elhoztam volna'::text,'elhoztam'::text,'elhoztam'::text,'Bárcsak én elhoztam volna a fényképezőgépemet! Ilyen táj, örökre elveszett!'::text),
(360354,40040,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, sie hat mir erzählt, dass sie die Hüftpose jeden Abend vor ... übt.'::text,'dem Schlafengehen'::text,'dem Bett'::text,'einem Bett'::text,'Rate mal, sie hat mir erzählt, dass sie die Hüftpose jeden Abend vor dem Schlafengehen übt.'::text),
(360358,40040,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, вона сказала мені, що щовечора перед ... тренує позу з руками на стегнах.'::text,'сном'::text,'ліжком'::text,'ліжком'::text,'Уяви, вона сказала мені, що щовечора перед сном тренує позу з руками на стегнах.'::text),
(360357,40040,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, ella me dijo que practica la pose de cadera cada noche antes de ...'::text,'dormir'::text,'la cama'::text,'una cama'::text,'Adivina qué, ella me dijo que practica la pose de cadera cada noche antes de dormir.'::text),
(360356,40040,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, elle m''a dit qu''elle travaille la pose des hanches tous les soirs avant ...'::text,'d''aller au lit'::text,'le lit'::text,'un lit'::text,'Devine quoi, elle m''a dit qu''elle travaille la pose des hanches tous les soirs avant d''aller au lit.'::text),
(360359,40040,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, o bana her gece ... önce kalça pozunu çalıştığını söyledi.'::text,'yatmadan'::text,'yataktan'::text,'bir yataktan'::text,'Bil bakalım, o bana her gece yatmadan önce kalça pozunu çalıştığını söyledi.'::text),
(360360,40040,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, ő azt mondta nekem, hogy minden este ... előtt gyakorolja a csípőpózt.'::text,'lefekvés'::text,'az ágy'::text,'egy ágy'::text,'Képzeld, ő azt mondta nekem, hogy minden este lefekvés előtt gyakorolja a csípőpózt.'::text),
(360822,40092,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die ganze Woche auf einen Keimling, und immer noch nichts! Absoluter Albtraum!'::text,'hofft'::text,'hat gehofft'::text,'hofft'::text,'Sie hofft die ganze Woche auf einen Keimling, und immer noch nichts! Absoluter Albtraum!'::text),
(360826,40092,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... на паросток цілий тиждень, і досі нічого! Суцільний жах!'::text,'сподівається'::text,'сподівалася'::text,'сподівається'::text,'Вона сподівається на паросток цілий тиждень, і досі нічого! Суцільний жах!'::text),
(360825,40092,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... un brote toda la semana, y todavía nada! ¡Una pesadilla absoluta!'::text,'ha estado esperando'::text,'ha esperado'::text,'está esperando'::text,'¡Ella ha estado esperando un brote toda la semana, y todavía nada! ¡Una pesadilla absoluta!'::text),
(360824,40092,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... un germe depuis toute la semaine, et toujours rien ! Cauchemar absolu !'::text,'espère'::text,'a espéré'::text,'espère'::text,'Elle espère un germe depuis toute la semaine, et toujours rien ! Cauchemar absolu !'::text),
(360827,40092,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bütün haftadır bir filiz çıkmasını ..., hâlâ hiçbir şey yok! Tam bir kâbus!'::text,'umuyor'::text,'umdu'::text,'umuyor'::text,'O bütün haftadır bir filiz çıkmasını umuyor, hâlâ hiçbir şey yok! Tam bir kâbus!'::text),
(360828,40092,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő egész héten ... egy csírában, és még mindig semmi! Teljes rémálom!'::text,'reménykedik'::text,'reménykedett'::text,'reménykedik'::text,'Ő egész héten reménykedik egy csírában, és még mindig semmi! Teljes rémálom!'::text),
(360885,40099,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis nächste Woche ... der Keimling, auf den sie gehofft hat, zu einer kleinen Pflanze herangewachsen sein.'::text,'wird'::text,'wird'::text,'wächst'::text,'Bis nächste Woche wird der Keimling, auf den sie gehofft hat, zu einer kleinen Pflanze herangewachsen sein.'::text),
(360889,40099,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До наступного тижня паросток, на який вона сподівалася, ... в маленьку рослинку.'::text,'виросте'::text,'виросте'::text,'росте'::text,'До наступного тижня паросток, на який вона сподівалася, виросте в маленьку рослинку.'::text),
(360888,40099,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la semana que viene, el brote que ella esperaba ... hasta ser una plantita.'::text,'habrá crecido'::text,'crecerá'::text,'crece'::text,'Para la semana que viene, el brote que ella esperaba habrá crecido hasta ser una plantita.'::text),
(360887,40099,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la semaine prochaine, le germe qu''elle espérait ... en une petite plante.'::text,'aura poussé'::text,'poussera'::text,'pousse'::text,'D''ici la semaine prochaine, le germe qu''elle espérait aura poussé en une petite plante.'::text),
(360890,40099,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelecek haftaya kadar umduğu filiz küçük bir bitkiye ...'::text,'dönüşmüş olacak'::text,'dönüşecek'::text,'dönüşüyor'::text,'Gelecek haftaya kadar umduğu filiz küçük bir bitkiye dönüşmüş olacak.'::text),
(360891,40099,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő hétre a csíra, amiben reménykedett, ... egy kis növénnyé.'::text,'megnő'::text,'meg fog nőni'::text,'nő'::text,'Jövő hétre a csíra, amiben reménykedett, megnő egy kis növénnyé.'::text),
(366150,40684,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die hohen grauen Spinde sollen vor vielen Jahren vom Hostel ...'::text,'gekauft worden sein'::text,'kaufen'::text,'kaufend'::text,'Die hohen grauen Spinde sollen vor vielen Jahren vom Hostel gekauft worden sein.'::text),
(366154,40684,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що високі сірі шафки ... хостелом багато років тому.'::text,'були куплені'::text,'купити'::text,'купуючи'::text,'Кажуть, що високі сірі шафки були куплені хостелом багато років тому.'::text),
(366153,40684,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que las altas taquillas grises ... por el albergue hace muchos años.'::text,'fueron compradas'::text,'comprar'::text,'comprando'::text,'Se dice que las altas taquillas grises fueron compradas por el albergue hace muchos años.'::text),
(366152,40684,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que les grands casiers gris ... par l''auberge de jeunesse il y a de nombreuses années.'::text,'ont été achetés'::text,'acheter'::text,'achetant'::text,'On dit que les grands casiers gris ont été achetés par l''auberge de jeunesse il y a de nombreuses années.'::text),
(366155,40684,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uzun gri dolapların yıllar önce hostel tarafından ... söyleniyor.'::text,'satın alındığı'::text,'satın almak'::text,'satın alarak'::text,'Uzun gri dolapların yıllar önce hostel tarafından satın alındığı söyleniyor.'::text),
(366156,40684,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állítólag a magas szürke szekrényeket a hosztel ... sok évvel ezelőtt.'::text,'vásárolta'::text,'vásárolni'::text,'vásárolva'::text,'Állítólag a magas szürke szekrényeket a hosztel vásárolta sok évvel ezelőtt.'::text),
(400890,44544,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar ein super Deal: Eine Villa mit eigenem Brunnen ... billig sein.'::text,'kann nicht'::text,'muss'::text,'sollte'::text,'Klar ein super Deal: Eine Villa mit eigenem Brunnen kann nicht billig sein.'::text),
(400894,44544,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно чудова угода: вілла з власним фонтаном ... бути дешевою.'::text,'не може'::text,'мусить'::text,'повинна'::text,'Явно чудова угода: вілла з власним фонтаном не може бути дешевою.'::text),
(400893,44544,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un chollo, claramente: una villa con fuente propia ... ser barata.'::text,'no puede'::text,'debe de'::text,'debería'::text,'Un chollo, claramente: una villa con fuente propia no puede ser barata.'::text),
(400892,44544,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super affaire, clairement : une villa avec sa propre fontaine ... être bon marché.'::text,'ne peut pas'::text,'doit'::text,'devrait'::text,'Super affaire, clairement : une villa avec sa propre fontaine ne peut pas être bon marché.'::text),
(400895,44544,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki harika bir fırsat: kendi çeşmesi olan bir villa ucuz ...'::text,'olamaz'::text,'olmalı'::text,'olması gerekir'::text,'Belli ki harika bir fırsat: kendi çeşmesi olan bir villa ucuz olamaz.'::text),
(400896,44544,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván szuper üzlet: egy saját szökőkutas villa ... olcsó.'::text,'nem lehet'::text,'biztos'::text,'kéne, hogy legyen'::text,'Nyilván szuper üzlet: egy saját szökőkutas villa nem lehet olcsó.'::text),
(343335,38149,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn dem Paar das weiße Häuschen gefällt, ... sie es diese Woche.'::text,'kaufen'::text,'würden kaufen'::text,'kauften'::text,'Wenn dem Paar das weiße Häuschen gefällt, kaufen sie es diese Woche.'::text),
(343339,38149,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо парі сподобається білий будиночок, вони ... його цього тижня.'::text,'куплять'::text,'купили б'::text,'купили'::text,'Якщо парі сподобається білий будиночок, вони куплять його цього тижня.'::text),
(343338,38149,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si a la pareja le gusta la casita blanca, ellos la ... esta semana.'::text,'comprarán'::text,'comprarían'::text,'compraron'::text,'Si a la pareja le gusta la casita blanca, ellos la comprarán esta semana.'::text),
(343337,38149,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le couple aime la petite maison blanche, ils ... cette semaine.'::text,'l''achèteront'::text,'l''achèteraient'::text,'l''achetèrent'::text,'Si le couple aime la petite maison blanche, ils l''achèteront cette semaine.'::text),
(343340,38149,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çift beyaz kulübeyi beğenirse, onlar bu hafta onu ...'::text,'satın alacaklar'::text,'satın alırlardı'::text,'satın aldılar'::text,'Çift beyaz kulübeyi beğenirse, onlar bu hafta onu satın alacaklar.'::text),
(343341,38149,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a párnak tetszik a fehér házikó, ők ezen a héten ...'::text,'megveszik'::text,'megvennék'::text,'megvették'::text,'Ha a párnak tetszik a fehér házikó, ők ezen a héten megveszik.'::text),
(345207,38357,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die zwei Frauen ... sich schon seit fünf Minuten in den Armen, und keine will loslassen.'::text,'liegen'::text,'liegen'::text,'liegen'::text,'Die zwei Frauen liegen sich schon seit fünf Minuten in den Armen, und keine will loslassen.'::text),
(345211,38357,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дві жінки ... вже п''ять хвилин, і ніхто не хоче відпускати.'::text,'обіймаються'::text,'обіймаються'::text,'обіймаються'::text,'Дві жінки обіймаються вже п''ять хвилин, і ніхто не хоче відпускати.'::text),
(345210,38357,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las dos mujeres ... desde hace cinco minutos y nadie quiere soltarse.'::text,'han estado abrazándose'::text,'se están abrazando'::text,'se abrazan'::text,'Las dos mujeres han estado abrazándose desde hace cinco minutos y nadie quiere soltarse.'::text),
(345209,38357,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux femmes ... depuis cinq minutes, et personne ne veut lâcher.'::text,'se câlinent'::text,'sont en train de se câliner'::text,'se câlinent'::text,'Les deux femmes se câlinent depuis cinq minutes, et personne ne veut lâcher.'::text),
(345212,38357,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki kadın beş dakikadır ... ve kimse bırakmak istemiyor.'::text,'sarılıyor'::text,'sarılıyor'::text,'sarılır'::text,'İki kadın beş dakikadır sarılıyor ve kimse bırakmak istemiyor.'::text),
(345213,38357,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A két nő már öt perce ..., és senki sem akarja elengedni a másikat.'::text,'ölelkezik'::text,'ölelkezik'::text,'ölelkezik'::text,'A két nő már öt perce ölelkezik, és senki sem akarja elengedni a másikat.'::text),
(345279,38365,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sich schon seit zehn Minuten in den Armen, und ich kann buchstäblich nicht atmen!'::text,'liegen'::text,'liegen'::text,'liegen'::text,'Sie liegen sich schon seit zehn Minuten in den Armen, und ich kann buchstäblich nicht atmen!'::text),
(345283,38365,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... вже десять хвилин, а я буквально не можу дихати!'::text,'обіймаються'::text,'обіймаються'::text,'обіймаються'::text,'Вони обіймаються вже десять хвилин, а я буквально не можу дихати!'::text),
(345282,38365,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ellas ... desde hace diez minutos y literalmente no puedo respirar!'::text,'han estado abrazándose'::text,'se están abrazando'::text,'se abrazan'::text,'¡Ellas han estado abrazándose desde hace diez minutos y literalmente no puedo respirar!'::text),
(345281,38365,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elles ... depuis dix minutes et je n''arrive littéralement plus à respirer !'::text,'se câlinent'::text,'sont en train de se câliner'::text,'se câlinent'::text,'Elles se câlinent depuis dix minutes et je n''arrive littéralement plus à respirer !'::text),
(345284,38365,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar on dakikadır ... ve ben resmen nefes alamıyorum!'::text,'sarılıyorlar'::text,'sarılıyorlar'::text,'sarılırlar'::text,'Onlar on dakikadır sarılıyorlar ve ben resmen nefes alamıyorum!'::text),
(345285,38365,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők már tíz perce ..., és én szó szerint nem kapok levegőt!'::text,'ölelkeznek'::text,'ölelkeznek'::text,'ölelkeznek'::text,'Ők már tíz perce ölelkeznek, és én szó szerint nem kapok levegőt!'::text),
(334776,37198,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... das Fernglas an die Augen, weil ein Fernglas für die Augen ist.'::text,'hebt'::text,'wird gehoben'::text,'hebend'::text,'Er hebt das Fernglas an die Augen, weil ein Fernglas für die Augen ist.'::text),
(334780,37198,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... бінокль до очей, бо бінокль — для очей.'::text,'підносить'::text,'піднесений'::text,'підносячи'::text,'Він підносить бінокль до очей, бо бінокль — для очей.'::text),
(334779,37198,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él se ... los prismáticos a los ojos porque los prismáticos son para los ojos.'::text,'lleva'::text,'es llevado'::text,'llevando'::text,'Él se lleva los prismáticos a los ojos porque los prismáticos son para los ojos.'::text),
(334778,37198,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... les jumelles à ses yeux parce que les jumelles, c''est pour les yeux.'::text,'porte'::text,'est porté'::text,'portant'::text,'Il porte les jumelles à ses yeux parce que les jumelles, c''est pour les yeux.'::text),
(334781,37198,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O dürbünü gözlerine ..., çünkü dürbün gözler içindir.'::text,'kaldırıyor'::text,'kaldırılıyor'::text,'kaldırarak'::text,'O dürbünü gözlerine kaldırıyor, çünkü dürbün gözler içindir.'::text),
(334782,37198,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a szeméhez ... a távcsövet, mert a távcső a szemnek való.'::text,'emeli'::text,'emeltetik'::text,'emelve'::text,'Ő a szeméhez emeli a távcsövet, mert a távcső a szemnek való.'::text),
(353325,39259,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr armer Finger soll im Möbelbausatz-Tisch ... sein! Das absolut Schlimmste!'::text,'eingeklemmt worden'::text,'einklemmen'::text,'einklemmend'::text,'Ihr armer Finger soll im Möbelbausatz-Tisch eingeklemmt worden sein! Das absolut Schlimmste!'::text),
(353329,39259,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, її бідний палець ... в столі з коробки! Найгірше, що може бути!'::text,'затиснуло'::text,'затиснути'::text,'затискаючи'::text,'Кажуть, її бідний палець затиснуло в столі з коробки! Найгірше, що може бути!'::text),
(353328,39259,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Dicen que su pobre dedo ... en la mesa de montar! ¡Lo peor de lo peor!'::text,'se quedó atrapado'::text,'atrapar'::text,'atrapando'::text,'¡Dicen que su pobre dedo se quedó atrapado en la mesa de montar! ¡Lo peor de lo peor!'::text),
(353327,39259,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son pauvre doigt se serait ... dans la table en kit ! Le pire du pire !'::text,'coincé'::text,'coincer'::text,'coinçant'::text,'Son pauvre doigt se serait coincé dans la table en kit ! Le pire du pire !'::text),
(353330,39259,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zavallı parmağının kutudan çıkan masaya ... söyleniyor! Olabilecek en kötü şey!'::text,'sıkıştığı'::text,'sıkıştırmak'::text,'sıkıştırarak'::text,'Zavallı parmağının kutudan çıkan masaya sıkıştığı söyleniyor! Olabilecek en kötü şey!'::text),
(353331,39259,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szegény ujja állítólag ... a lapraszerelt asztalba! A lehető legrosszabb!'::text,'beszorult'::text,'beszorítani'::text,'beszorítva'::text,'Szegény ujja állítólag beszorult a lapraszerelt asztalba! A lehető legrosszabb!'::text),
(395544,43950,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unter uns, angeblich ... er die Suppe zweimal probiert, bevor er sie kosten ließ.'::text,'hatte'::text,'hat'::text,'probiert'::text,'Unter uns, angeblich hatte er die Suppe zweimal probiert, bevor er sie kosten ließ.'::text),
(395548,43950,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Між нами, кажуть, він ... суп двічі, перш ніж дав їй спробувати.'::text,'скуштував'::text,'скуштував'::text,'куштує'::text,'Між нами, кажуть, він скуштував суп двічі, перш ніж дав їй спробувати.'::text),
(395547,43950,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entre nosotros, dicen que él ... la sopa dos veces antes de dejarla probarla.'::text,'había probado'::text,'ha probado'::text,'prueba'::text,'Entre nosotros, dicen que él había probado la sopa dos veces antes de dejarla probarla.'::text),
(395546,43950,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entre nous, il paraît qu''il ... la soupe deux fois avant de la lui faire goûter.'::text,'avait goûté'::text,'a goûté'::text,'goûte'::text,'Entre nous, il paraît qu''il avait goûté la soupe deux fois avant de la lui faire goûter.'::text),
(395549,43950,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aramızda kalsın, güya o ona tattırmadan önce çorbayı iki kez ...'::text,'tatmıştı'::text,'tattı'::text,'tadıyor'::text,'Aramızda kalsın, güya o ona tattırmadan önce çorbayı iki kez tatmıştı.'::text),
(395550,43950,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köztünk szólva, állítólag ő kétszer ... a levest, mielőtt hagyta, hogy a lány is megkóstolja.'::text,'megkóstolta'::text,'megkóstolta'::text,'kóstolja'::text,'Köztünk szólva, állítólag ő kétszer megkóstolta a levest, mielőtt hagyta, hogy a lány is megkóstolja.'::text),
(395598,43956,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie die Suppe probierte, ... er die Blumen schon hinter seinem Rücken versteckt.'::text,'hatte'::text,'versteckte'::text,'hat'::text,'Als sie die Suppe probierte, hatte er die Blumen schon hinter seinem Rücken versteckt.'::text),
(395602,43956,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вона скуштувала суп, він уже ... квіти за спиною.'::text,'сховав'::text,'сховав'::text,'сховав'::text,'Коли вона скуштувала суп, він уже сховав квіти за спиною.'::text),
(395601,43956,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando probó la sopa, él ya ... las flores detrás de la espalda.'::text,'había escondido'::text,'escondió'::text,'ha escondido'::text,'Para cuando probó la sopa, él ya había escondido las flores detrás de la espalda.'::text),
(395600,43956,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand elle a goûté la soupe, il ... déjà les fleurs derrière son dos.'::text,'avait caché'::text,'cacha'::text,'a caché'::text,'Quand elle a goûté la soupe, il avait caché déjà les fleurs derrière son dos.'::text),
(395603,43956,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O çorbayı tattığında, adam çiçekleri çoktan arkasına ...'::text,'saklamıştı'::text,'sakladı'::text,'sakladı'::text,'O çorbayı tattığında, adam çiçekleri çoktan arkasına saklamıştı.'::text),
(395604,43956,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a lány megkóstolta a levest, ő már ... a virágokat a háta mögé.'::text,'elrejtette'::text,'elrejtette'::text,'elrejtette'::text,'Mire a lány megkóstolta a levest, ő már elrejtette a virágokat a háta mögé.'::text),
(361785,40199,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Beamte fragte sie, ob sie ihren Personalausweis dabei ...'::text,'hatte'::text,'hat'::text,'hätte'::text,'Der Beamte fragte sie, ob sie ihren Personalausweis dabei hatte.'::text),
(361789,40199,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Офіцер запитав її, чи ... вона при собі посвідчення особи.'::text,'має'::text,'має'::text,'мала'::text,'Офіцер запитав її, чи має вона при собі посвідчення особи.'::text),
(361788,40199,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El agente le preguntó si ella ... su documento de identidad encima.'::text,'tenía'::text,'tiene'::text,'tuvo'::text,'El agente le preguntó si ella tenía su documento de identidad encima.'::text),
(361787,40199,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''agent lui a demandé si elle ... sa carte d''identité sur elle.'::text,'avait'::text,'a'::text,'a eu'::text,'L''agent lui a demandé si elle avait sa carte d''identité sur elle.'::text),
(361790,40199,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Memur ona kimlik kartının yanında ... sordu.'::text,'olup olmadığını'::text,'olup olmadığını'::text,'olup olmadığını'::text,'Memur ona kimlik kartının yanında olup olmadığını sordu.'::text),
(361791,40199,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tisztviselő megkérdezte tőle, hogy nála ... a személyi igazolványa.'::text,'van-e'::text,'van-e'::text,'volt-e'::text,'A tisztviselő megkérdezte tőle, hogy nála van-e a személyi igazolványa.'::text),
(353397,39267,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während das Feuerwerk über der Kuppel ..., war der Himmel hell wegen des Feuerwerks.'::text,'explodierte'::text,'explodierte'::text,'ist explodiert'::text,'Während das Feuerwerk über der Kuppel explodierte, war der Himmel hell wegen des Feuerwerks.'::text),
(353401,39267,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки феєрверк ... над куполом, небо було яскравим через феєрверк.'::text,'вибухав'::text,'вибухнув'::text,'вибухнув'::text,'Поки феєрверк вибухав над куполом, небо було яскравим через феєрверк.'::text),
(353400,39267,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras los fuegos artificiales ... sobre la cúpula, el cielo estaba brillante por los fuegos artificiales.'::text,'estallaban'::text,'estallaron'::text,'han estallado'::text,'Mientras los fuegos artificiales estallaban sobre la cúpula, el cielo estaba brillante por los fuegos artificiales.'::text),
(353399,39267,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que le feu d''artifice ... au-dessus du dôme, le ciel était lumineux à cause du feu d''artifice.'::text,'éclatait'::text,'éclata'::text,'a éclaté'::text,'Pendant que le feu d''artifice éclatait au-dessus du dôme, le ciel était lumineux à cause du feu d''artifice.'::text),
(353402,39267,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Havai fişekler kubbenin üzerinde ..., gökyüzü havai fişekler yüzünden aydınlıktı.'::text,'patlarken'::text,'patladı'::text,'patlamış'::text,'Havai fişekler kubbenin üzerinde patlarken, gökyüzü havai fişekler yüzünden aydınlıktı.'::text),
(353403,39267,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amíg a tűzijáték ... a kupola fölött, az ég világos volt a tűzijáték miatt.'::text,'robbant'::text,'felrobbant'::text,'felrobbant'::text,'Amíg a tűzijáték robbant a kupola fölött, az ég világos volt a tűzijáték miatt.'::text),
(353451,39273,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des ganzen Rauchs war das Feuerwerk klar zu sehen. Keine Anmerkungen.'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz des ganzen Rauchs war das Feuerwerk klar zu sehen. Keine Anmerkungen.'::text),
(353455,39273,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... весь дим, феєрверк було чудово видно. Без зауважень.'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри весь дим, феєрверк було чудово видно. Без зауважень.'::text),
(353454,39273,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... todo el humo, los fuegos artificiales se veían claramente. Sin comentarios.'::text,'A pesar de'::text,'Aunque'::text,'Debido a'::text,'A pesar de todo el humo, los fuegos artificiales se veían claramente. Sin comentarios.'::text),
(353453,39273,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... toute la fumée, le feu d''artifice était bien visible. Rien à redire.'::text,'Malgré'::text,'Bien que'::text,'À cause de'::text,'Malgré toute la fumée, le feu d''artifice était bien visible. Rien à redire.'::text),
(353456,39273,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün dumana ..., havai fişekler açıkça görünüyordu. Diyecek yok.'::text,'rağmen'::text,'gerçi'::text,'yüzünden'::text,'Bütün dumana rağmen, havai fişekler açıkça görünüyordu. Diyecek yok.'::text),
(353457,39273,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egész füst ... a tűzijáték tisztán látszott. Nincs mit hozzátenni.'::text,'ellenére'::text,'bár'::text,'miatt'::text,'Az egész füst ellenére a tűzijáték tisztán látszott. Nincs mit hozzátenni.'::text),
(373296,41478,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie meinte, sie ... sich nächstes Jahr wieder die Wangen bemalen, weil sie so patriotisch ist.'::text,'würde'::text,'wird'::text,'bemalt'::text,'Bro, sie meinte, sie würde sich nächstes Jahr wieder die Wangen bemalen, weil sie so patriotisch ist.'::text),
(373300,41478,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона сказала, що наступного року знову ... щоки, бо вона така патріотична.'::text,'розмалює'::text,'розмалює'::text,'малює'::text,'Бро, вона сказала, що наступного року знову розмалює щоки, бо вона така патріотична.'::text),
(373299,41478,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella dijo que se ... las mejillas otra vez el año que viene, porque es superpatriota.'::text,'pintaría'::text,'pintará'::text,'pinta'::text,'Bro, ella dijo que se pintaría las mejillas otra vez el año que viene, porque es superpatriota.'::text),
(373298,41478,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle a dit qu''elle se ... encore les joues l''année prochaine, parce qu''elle est trop patriote.'::text,'peindrait'::text,'peindra'::text,'peint'::text,'Frère, elle a dit qu''elle se peindrait encore les joues l''année prochaine, parce qu''elle est trop patriote.'::text),
(373301,41478,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o seneye yine yanaklarını ... söyledi, çünkü çok vatansever.'::text,'boyayacağını'::text,'boyayacağını'::text,'boyadığını'::text,'Kanka, o seneye yine yanaklarını boyayacağını söyledi, çünkü çok vatansever.'::text),
(373302,41478,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő azt mondta, jövőre megint ... az arcát, mert annyira hazafias.'::text,'kifesti'::text,'ki fogja festeni'::text,'festi'::text,'Tesó, ő azt mondta, jövőre megint kifesti az arcát, mert annyira hazafias.'::text),
(373332,41482,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor das Feuerwerk begann, ... die Menge etwa eine Stunde lang patriotische Fahnen.'::text,'schwenkte'::text,'schwenkte'::text,'schwenkte'::text,'Bevor das Feuerwerk begann, schwenkte die Menge etwa eine Stunde lang patriotische Fahnen.'::text),
(373336,41482,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж почався феєрверк, натовп ... патріотичними прапорами приблизно годину.'::text,'махав'::text,'махав'::text,'махав'::text,'Перш ніж почався феєрверк, натовп махав патріотичними прапорами приблизно годину.'::text),
(373335,41482,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de que empezaran los fuegos artificiales, la multitud ... banderas patrióticas durante aproximadamente una hora.'::text,'había estado ondeando'::text,'ondeó'::text,'estaba ondeando'::text,'Antes de que empezaran los fuegos artificiales, la multitud había estado ondeando banderas patrióticas durante aproximadamente una hora.'::text),
(373334,41482,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant le début du feu d''artifice, la foule ... des drapeaux patriotiques pendant environ une heure.'::text,'agitait'::text,'agita'::text,'agitait'::text,'Avant le début du feu d''artifice, la foule agitait des drapeaux patriotiques pendant environ une heure.'::text),
(373337,41482,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Havai fişekler başlamadan önce kalabalık yaklaşık bir saat boyunca vatansever bayraklar ...'::text,'sallıyordu'::text,'salladı'::text,'sallıyordu'::text,'Havai fişekler başlamadan önce kalabalık yaklaşık bir saat boyunca vatansever bayraklar sallıyordu.'::text),
(373338,41482,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt a tűzijáték elkezdődött, a tömeg körülbelül egy órán át ... a hazafias zászlókat.'::text,'lengette'::text,'lengette'::text,'lengette'::text,'Mielőtt a tűzijáték elkezdődött, a tömeg körülbelül egy órán át lengette a hazafias zászlókat.'::text),
(369741,41083,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er liebte das Denkmal, und natürlich ...'::text,'seine Kamera auch.'::text,'seine Kamera auch.'::text,'seine Kamera auch.'::text,'Er liebte das Denkmal, und natürlich seine Kamera auch.'::text),
(369745,41083,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він обожнював пам''ятник, і, звісно, ...'::text,'його камера теж.'::text,'його камера теж.'::text,'його камера теж.'::text,'Він обожнював пам''ятник, і, звісно, його камера теж.'::text),
(369744,41083,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él adoraba el monumento y, obviamente, ...'::text,'su cámara también.'::text,'su cámara también.'::text,'su cámara también.'::text,'Él adoraba el monumento y, obviamente, su cámara también.'::text),
(369743,41083,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a adoré le monument, et évidemment ...'::text,'son appareil photo aussi.'::text,'son appareil photo aussi.'::text,'son appareil photo aussi.'::text,'Il a adoré le monument, et évidemment son appareil photo aussi.'::text),
(369746,41083,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O anıta bayıldı, tabii ki ...'::text,'kamerası da öyle.'::text,'kamerası da öyle.'::text,'kamerası da öyle.'::text,'O anıta bayıldı, tabii ki kamerası da öyle.'::text),
(369747,41083,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő imádta az emlékművet, és persze ...'::text,'a fényképezőgépe is.'::text,'a fényképezőgépe is.'::text,'a fényképezőgépe is.'::text,'Ő imádta az emlékművet, és persze a fényképezőgépe is.'::text),
(369804,41090,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... vor ihm war absolut das Schönste überhaupt!'::text,'Das Denkmal'::text,'Ein Denkmal'::text,'Denkmal'::text,'Das Denkmal vor ihm war absolut das Schönste überhaupt!'::text),
(369808,41090,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... перед ним був абсолютно найкрасивішим у світі!'::text,'Пам''ятник'::text,'Пам''ятник'::text,'Пам''ятник'::text,'Пам''ятник перед ним був абсолютно найкрасивішим у світі!'::text),
(369807,41090,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... frente a él era absolutamente lo más bonito del mundo!'::text,'El monumento'::text,'Un monumento'::text,'Monumento'::text,'¡El monumento frente a él era absolutamente lo más bonito del mundo!'::text),
(369806,41090,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... devant lui était absolument la plus belle chose au monde !'::text,'Le monument'::text,'Un monument'::text,'Monument'::text,'Le monument devant lui était absolument la plus belle chose au monde !'::text),
(369809,41090,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Önündeki ... kesinlikle gelmiş geçmiş en güzel şeydi!'::text,'anıt'::text,'bir anıt'::text,'anıt'::text,'Önündeki anıt kesinlikle gelmiş geçmiş en güzel şeydi!'::text),
(369810,41090,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... előtte egyszerűen a világ legszebb dolga volt!'::text,'Az emlékmű'::text,'Egy emlékmű'::text,'Emlékmű'::text,'Az emlékmű előtte egyszerűen a világ legszebb dolga volt!'::text),
(384735,42749,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Verkäufer, ... aus 1 Meter Höhe einschenkt, erreicht sein Tagesziel.'::text,'der'::text,'das'::text,'dessen'::text,'Der Verkäufer, der aus 1 Meter Höhe einschenkt, erreicht sein Tagesziel.'::text),
(384739,42749,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Продавець, ... наливає з висоти 1 метра, виконує свій денний план.'::text,'який'::text,'що'::text,'чий'::text,'Продавець, який наливає з висоти 1 метра, виконує свій денний план.'::text),
(384738,42749,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vendedor ... sirve desde 1 metro de altura cumple su objetivo diario.'::text,'que'::text,'el cual'::text,'cuyo'::text,'El vendedor que sirve desde 1 metro de altura cumple su objetivo diario.'::text),
(384737,42749,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vendeur ... verse de 1 mètre de haut atteint son objectif quotidien.'::text,'qui'::text,'que'::text,'dont'::text,'Le vendeur qui verse de 1 mètre de haut atteint son objectif quotidien.'::text),
(384740,42749,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'1 metre yükseklikten ... döken satıcı günlük hedefini tutturuyor.'::text,''::text,NULL::text,NULL::text,'1 metre yükseklikten döken satıcı günlük hedefini tutturuyor.'::text),
(384741,42749,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az az eladó, ... 1 méter magasról tölt, teljesíti a napi célját.'::text,'aki'::text,'ami'::text,'akinek a'::text,'Az az eladó, aki 1 méter magasról tölt, teljesíti a napi célját.'::text),
(384789,42755,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Verkäufer ... schon eine Stunde lang Tee ein, bevor die jungen Männer ihn filmten.'::text,'schenkte'::text,'schenkt'::text,'schenkte'::text,'Der Verkäufer schenkte schon eine Stunde lang Tee ein, bevor die jungen Männer ihn filmten.'::text),
(384793,42755,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Продавець ... чай уже годину, коли молоді хлопці почали його знімати.'::text,'наливав'::text,'наливає'::text,'наливав'::text,'Продавець наливав чай уже годину, коли молоді хлопці почали його знімати.'::text),
(384792,42755,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vendedor ... té durante una hora antes de que los chicos empezaran a grabarlo.'::text,'había estado sirviendo'::text,'ha estado sirviendo'::text,'estaba sirviendo'::text,'El vendedor había estado sirviendo té durante una hora antes de que los chicos empezaran a grabarlo.'::text),
(384791,42755,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vendeur ... du thé depuis une heure quand les jeunes ont commencé à le filmer.'::text,'versait'::text,'verse'::text,'versait'::text,'Le vendeur versait du thé depuis une heure quand les jeunes ont commencé à le filmer.'::text),
(384794,42755,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gençler onu çekmeye başlamadan önce satıcı bir saattir çay ...'::text,'dolduruyordu'::text,'dolduruyor'::text,'dolduruyordu'::text,'Gençler onu çekmeye başlamadan önce satıcı bir saattir çay dolduruyordu.'::text),
(384795,42755,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az eladó már egy órája ... a teát, mire a fiatalok elkezdték filmezni.'::text,'töltötte'::text,'tölti'::text,'töltötte'::text,'Az eladó már egy órája töltötte a teát, mire a fiatalok elkezdték filmezni.'::text),
(401187,44577,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bauer watet ... des aufsteigenden Rauchs aus dem Vulkan weiter durchs Wasser.'::text,'trotz'::text,'obwohl'::text,'wegen'::text,'Der Bauer watet trotz des aufsteigenden Rauchs aus dem Vulkan weiter durchs Wasser.'::text),
(401191,44577,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фермер і далі бреде водою ... дим, що здіймається з вулкана.'::text,'попри'::text,'хоча'::text,'через'::text,'Фермер і далі бреде водою попри дим, що здіймається з вулкана.'::text),
(401190,44577,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El campesino sigue vadeando el agua ... el humo que sale del volcán.'::text,'a pesar de'::text,'aunque'::text,'por'::text,'El campesino sigue vadeando el agua a pesar de el humo que sale del volcán.'::text),
(401189,44577,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le paysan continue de patauger dans l''eau ... la fumée qui s''élève du volcan.'::text,'malgré'::text,'bien que'::text,'à cause de'::text,'Le paysan continue de patauger dans l''eau malgré la fumée qui s''élève du volcan.'::text),
(401192,44577,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çiftçi volkandan yükselen dumana ... sudan geçmeye devam ediyor.'::text,'rağmen'::text,'gerçi'::text,'yüzünden'::text,'Çiftçi volkandan yükselen dumana rağmen sudan geçmeye devam ediyor.'::text),
(401193,44577,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A földműves a vulkánból felszálló füst ... tovább gázol a vízben.'::text,'ellenére'::text,'bár'::text,'miatt'::text,'A földműves a vulkánból felszálló füst ellenére tovább gázol a vízben.'::text),
(400143,44461,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Impfstoff soll letztes Jahr an Tausenden Freiwilligen getestet worden ...'::text,'sein'::text,'werden'::text,'seiend'::text,'Der Impfstoff soll letztes Jahr an Tausenden Freiwilligen getestet worden sein.'::text),
(400147,44461,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, вакцину ... на тисячах добровольців торік.'::text,'було протестовано'::text,'тестують'::text,'тестуючи'::text,'Кажуть, вакцину було протестовано на тисячах добровольців торік.'::text),
(400146,44461,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que la vacuna ... probada en miles de voluntarios el año pasado.'::text,'fue'::text,'es'::text,'siendo'::text,'Se dice que la vacuna fue probada en miles de voluntarios el año pasado.'::text),
(400145,44461,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vaccin aurait ... testé sur des milliers de volontaires l''an dernier.'::text,'été'::text,'être'::text,'étant'::text,'Le vaccin aurait été testé sur des milliers de volontaires l''an dernier.'::text),
(400148,44461,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aşının geçen yıl binlerce gönüllü üzerinde test ... söyleniyor.'::text,'edildiği'::text,'edilmek'::text,'edilerek'::text,'Aşının geçen yıl binlerce gönüllü üzerinde test edildiği söyleniyor.'::text),
(400149,44461,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állítólag a vakcinát tavaly több ezer önkéntesen ...'::text,'tesztelték'::text,'tesztelni'::text,'tesztelve'::text,'Állítólag a vakcinát tavaly több ezer önkéntesen tesztelték.'::text),
(336450,37384,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er seine Aktentasche fallen lässt, ... seine Papiere über die ganze Promenade.'::text,'fliegen'::text,'würden fliegen'::text,'flogen'::text,'Wenn er seine Aktentasche fallen lässt, fliegen seine Papiere über die ganze Promenade.'::text),
(336454,37384,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він упустить портфель, його папери ... по всій набережній.'::text,'розлетяться'::text,'розлетілися б'::text,'розлетілися'::text,'Якщо він упустить портфель, його папери розлетяться по всій набережній.'::text),
(336453,37384,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si él deja caer el maletín, sus papeles ... por todo el paseo.'::text,'volarán'::text,'volarían'::text,'volaron'::text,'Si él deja caer el maletín, sus papeles volarán por todo el paseo.'::text),
(336452,37384,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il fait tomber sa mallette, ses papiers ... sur toute la promenade.'::text,'s''envoleront'::text,'s''envoleraient'::text,'s''envolèrent'::text,'S''il fait tomber sa mallette, ses papiers s''envoleront sur toute la promenade.'::text),
(336455,37384,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O çantasını düşürürse, kâğıtları bütün sahil yoluna ...'::text,'saçılacak'::text,'saçılırdı'::text,'saçıldı'::text,'O çantasını düşürürse, kâğıtları bütün sahil yoluna saçılacak.'::text),
(336456,37384,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ő elejti az aktatáskáját, a papírjai ... az egész sétányon.'::text,'szétrepülnek'::text,'szétrepülnének'::text,'szétrepültek'::text,'Ha ő elejti az aktatáskáját, a papírjai szétrepülnek az egész sétányon.'::text),
(336531,37393,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ... gerade mit seiner Aktentasche Skateboard.'::text,'fährt'::text,'fährt'::text,'ist gefahren'::text,'Der Mann fährt gerade mit seiner Aktentasche Skateboard.'::text),
(336535,37393,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік зараз ... на скейтборді з портфелем.'::text,'їде'::text,'їздить'::text,'проїхав'::text,'Чоловік зараз їде на скейтборді з портфелем.'::text),
(336534,37393,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... en monopatín con su maletín en este momento.'::text,'está yendo'::text,'va'::text,'ha ido'::text,'El hombre está yendo en monopatín con su maletín en este momento.'::text),
(336533,37393,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... du skateboard avec sa mallette en ce moment.'::text,'fait'::text,'fait'::text,'a fait'::text,'L''homme fait du skateboard avec sa mallette en ce moment.'::text),
(336536,37393,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam şu anda çantasıyla kaykay ...'::text,'sürüyor'::text,'sürer'::text,'sürdü'::text,'Adam şu anda çantasıyla kaykay sürüyor.'::text),
(336537,37393,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi épp most ... gördeszkán az aktatáskájával.'::text,'gurul'::text,'gurul'::text,'gurult'::text,'A férfi épp most gurul gördeszkán az aktatáskájával.'::text),
(353748,39306,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um zehn ... sie weitere Bildschirme an der Bürowand.'::text,'montieren'::text,'montieren'::text,'montieren'::text,'Morgen um zehn montieren sie weitere Bildschirme an der Bürowand.'::text),
(353752,39306,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра о десятій ранку вони ... нові екрани на стіну офісу.'::text,'кріпитимуть'::text,'закріплять'::text,'кріплять'::text,'Завтра о десятій ранку вони кріпитимуть нові екрани на стіну офісу.'::text),
(353751,39306,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a las diez, ellos ... más pantallas en la pared de la oficina.'::text,'estarán fijando'::text,'fijarán'::text,'fijan'::text,'Mañana a las diez, ellos estarán fijando más pantallas en la pared de la oficina.'::text),
(353750,39306,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à dix heures, ils ... d''autres écrans au mur du bureau.'::text,'seront en train de fixer'::text,'fixeront'::text,'fixent'::text,'Demain à dix heures, ils seront en train de fixer d''autres écrans au mur du bureau.'::text),
(353753,39306,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın sabah onda onlar ofis duvarına daha fazla ekran ...'::text,'takıyor olacaklar'::text,'takacaklar'::text,'takıyorlar'::text,'Yarın sabah onda onlar ofis duvarına daha fazla ekran takıyor olacaklar.'::text),
(353754,39306,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap reggel tízkor ők ... további képernyőket az iroda falára.'::text,'szerelnek fel'::text,'fel fognak szerelni'::text,'szerelnek fel'::text,'Holnap reggel tízkor ők szerelnek fel további képernyőket az iroda falára.'::text),
(353829,39315,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Büroleiterin ließ die Arbeiter die Bildschirme an der Wand ...'::text,'befestigen'::text,'befestigen'::text,'befestigen'::text,'Die Büroleiterin ließ die Arbeiter die Bildschirme an der Wand befestigen.'::text),
(353833,39315,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Офіс-менеджерка доручила працівникам ... екрани на стіну.'::text,'закріпити'::text,'закріпити'::text,'закріплення'::text,'Офіс-менеджерка доручила працівникам закріпити екрани на стіну.'::text),
(353832,39315,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La jefa de oficina hizo que los trabajadores ... las pantallas a la pared.'::text,'fijaran'::text,'fijaran'::text,'fijando'::text,'La jefa de oficina hizo que los trabajadores fijaran las pantallas a la pared.'::text),
(353831,39315,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La responsable du bureau a demandé aux ouvriers de ... les écrans au mur.'::text,'fixer'::text,'fixer'::text,'fixer'::text,'La responsable du bureau a demandé aux ouvriers de fixer les écrans au mur.'::text),
(353834,39315,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ofis müdürü ekranları duvara işçilere ...'::text,'taktırdı'::text,'taktırdı'::text,'taktırdı'::text,'Ofis müdürü ekranları duvara işçilere taktırdı.'::text),
(353835,39315,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az irodavezető ... a munkásokkal a képernyőket a falra.'::text,'felszereltette'::text,'felszereltette'::text,'felszereltette'::text,'Az irodavezető felszereltette a munkásokkal a képernyőket a falra.'::text),
(376482,41832,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... heute drei ganze Projekte präsentiert und keiner hört zu, echt jetzt.'::text,'hat'::text,'hat'::text,'präsentiert'::text,'Bro, sie hat heute drei ganze Projekte präsentiert und keiner hört zu, echt jetzt.'::text),
(376486,41832,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона сьогодні ... три цілі проєкти, а ніхто не слухає, реально.'::text,'презентувала'::text,'презентувала'::text,'презентує'::text,'Бро, вона сьогодні презентувала три цілі проєкти, а ніхто не слухає, реально.'::text),
(376485,41832,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella ... tres proyectos enteros hoy y nadie escucha, en serio.'::text,'ha presentado'::text,'ha estado presentando'::text,'está presentando'::text,'Bro, ella ha presentado tres proyectos enteros hoy y nadie escucha, en serio.'::text),
(376484,41832,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle ... trois projets entiers aujourd''hui et personne n''écoute, sérieux.'::text,'a présenté'::text,'a présenté'::text,'présente'::text,'Frère, elle a présenté trois projets entiers aujourd''hui et personne n''écoute, sérieux.'::text),
(376487,41832,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o bugün koca üç proje ... ve kimse dinlemiyor, cidden.'::text,'sundu'::text,'sunuyordu'::text,'sunuyor'::text,'Kanka, o bugün koca üç proje sundu ve kimse dinlemiyor, cidden.'::text),
(376488,41832,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő ma ... három teljes projektet, és senki sem figyel, komolyan.'::text,'bemutatott'::text,'mutatott be'::text,'mutat be'::text,'Tesó, ő ma bemutatott három teljes projektet, és senki sem figyel, komolyan.'::text),
(376545,41839,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Freitag ... du dieses Projekt jedem Team präsentiert haben, und ehrlich, Respekt.'::text,'wirst'::text,'wirst'::text,'präsentierst'::text,'Bis Freitag wirst du dieses Projekt jedem Team präsentiert haben, und ehrlich, Respekt.'::text),
(376549,41839,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До п''ятниці ти ... цей проєкт кожній команді, і чесно, респект.'::text,'презентуєш'::text,'презентуєш'::text,'презентуєш'::text,'До п''ятниці ти презентуєш цей проєкт кожній команді, і чесно, респект.'::text),
(376548,41839,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el viernes, tú ... este proyecto a todos los equipos y, sinceramente, respeto.'::text,'habrás presentado'::text,'presentarás'::text,'presentas'::text,'Para el viernes, tú habrás presentado este proyecto a todos los equipos y, sinceramente, respeto.'::text),
(376547,41839,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici vendredi, tu ... ce projet à chaque équipe, et franchement, respect.'::text,'auras présenté'::text,'présenteras'::text,'présentes'::text,'D''ici vendredi, tu auras présenté ce projet à chaque équipe, et franchement, respect.'::text),
(376550,41839,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cumaya kadar sen bu projeyi her ekibe ... ve açıkçası, helal.'::text,'sunmuş olacaksın'::text,'sunacaksın'::text,'sunuyorsun'::text,'Cumaya kadar sen bu projeyi her ekibe sunmuş olacaksın ve açıkçası, helal.'::text),
(376551,41839,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Péntekre te ... ezt a projektet minden csapatnak, és őszintén, respekt.'::text,'bemutatod'::text,'be fogod mutatni'::text,'bemutatod'::text,'Péntekre te bemutatod ezt a projektet minden csapatnak, és őszintén, respekt.'::text),
(368634,40960,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Haufen, ... auf dem Bett liegt, sieht sehr unordentlich aus.'::text,'der'::text,'wer'::text,'was'::text,'Der Haufen, der auf dem Bett liegt, sieht sehr unordentlich aus.'::text),
(368638,40960,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Купа, ... лежить на ліжку, виглядає дуже неохайно.'::text,'яка'::text,'хто'::text,'що'::text,'Купа, яка лежить на ліжку, виглядає дуже неохайно.'::text),
(368637,40960,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El montón ... está en la cama se ve muy desordenado.'::text,'que'::text,'quien'::text,'lo que'::text,'El montón que está en la cama se ve muy desordenado.'::text),
(368636,40960,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pile ... est sur le lit a l''air très en désordre.'::text,'qui'::text,'qui'::text,'ce qui'::text,'La pile qui est sur le lit a l''air très en désordre.'::text),
(368639,40960,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yatakta ... duran yığın çok dağınık görünüyor.'::text,''::text,NULL::text,NULL::text,'Yatakta duran yığın çok dağınık görünüyor.'::text),
(368640,40960,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a kupac, ... az ágyon van, nagyon rendetlennek tűnik.'::text,'amely'::text,'aki'::text,'ami'::text,'Az a kupac, amely az ágyon van, nagyon rendetlennek tűnik.'::text),
(368679,40965,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor du es gebügelt hast, ... das Hemd tagelang im chaotischen Haufen; ehrlich, starke Rettung.'::text,'lag'::text,'lag'::text,'hat gelegen'::text,'Bevor du es gebügelt hast, lag das Hemd tagelang im chaotischen Haufen; ehrlich, starke Rettung.'::text),
(368683,40965,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки ти її не випрасував, та сорочка ... в безладній купі кілька днів; чесно, класний порятунок.'::text,'лежала'::text,'лежала'::text,'лежала'::text,'Поки ти її не випрасував, та сорочка лежала в безладній купі кілька днів; чесно, класний порятунок.'::text),
(368682,40965,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de que tú la plancharas, esa camisa ... días en el montón desordenado; sinceramente, gran rescate.'::text,'había estado'::text,'estaba'::text,'ha estado'::text,'Antes de que tú la plancharas, esa camisa había estado días en el montón desordenado; sinceramente, gran rescate.'::text),
(368681,40965,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant que tu la repasses, cette chemise ... depuis des jours dans le tas en bazar ; franchement, beau sauvetage.'::text,'traînait'::text,'traînait'::text,'a traîné'::text,'Avant que tu la repasses, cette chemise traînait depuis des jours dans le tas en bazar ; franchement, beau sauvetage.'::text),
(368684,40965,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen onu ütülemeden önce o gömlek günlerce dağınık yığında ...; açıkçası, harika kurtarış.'::text,'duruyordu'::text,'duruyordu'::text,'durdu'::text,'Sen onu ütülemeden önce o gömlek günlerce dağınık yığında duruyordu; açıkçası, harika kurtarış.'::text),
(368685,40965,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt te kivasaltad, az az ing napokig ... a rendetlen kupacban; őszintén, szép mentés.'::text,'hevert'::text,'hevert'::text,'hevert'::text,'Mielőtt te kivasaltad, az az ing napokig hevert a rendetlen kupacban; őszintén, szép mentés.'::text),
(384384,42710,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann fährt am Brunnen vorbei, ... anzuhalten und sich die Skulptur anzusehen.'::text,'statt'::text,'trotz'::text,'sowie'::text,'Der Mann fährt am Brunnen vorbei, statt anzuhalten und sich die Skulptur anzusehen.'::text),
(384388,42710,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік проїжджає повз фонтан, ... зупинитися й подивитися на його скульптуру.'::text,'замість того щоб'::text,'попри те що'::text,'а також'::text,'Чоловік проїжджає повз фонтан, замість того щоб зупинитися й подивитися на його скульптуру.'::text),
(384387,42710,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre pasa junto a la fuente ... pararse a mirar su escultura.'::text,'en vez de'::text,'a pesar de'::text,'además de'::text,'El hombre pasa junto a la fuente en vez de pararse a mirar su escultura.'::text),
(384386,42710,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme passe devant la fontaine ... s''arrêter pour regarder sa sculpture.'::text,'au lieu de'::text,'malgré'::text,'en plus de'::text,'L''homme passe devant la fontaine au lieu de s''arrêter pour regarder sa sculpture.'::text),
(384389,42710,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam heykele bakmak için ... fıskiyenin yanından geçip gidiyor.'::text,'durmak yerine'::text,'durmasına rağmen'::text,'durmanın yanı sıra'::text,'Adam heykele bakmak için durmak yerine fıskiyenin yanından geçip gidiyor.'::text),
(384390,42710,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi elhajt a szökőkút mellett, ... megállna megnézni a szobrát.'::text,'ahelyett, hogy'::text,'annak ellenére, hogy'::text,'valamint'::text,'A férfi elhajt a szökőkút mellett, ahelyett, hogy megállna megnézni a szobrát.'::text),
(341940,37994,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Eiswaffel schon eine Minute in der Hand, als die Tauben aufflogen.'::text,'hielt'::text,'hält'::text,'hält'::text,'Sie hielt die Eiswaffel schon eine Minute in der Hand, als die Tauben aufflogen.'::text),
(341944,37994,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... ріжок із морозивом уже хвилину, коли голуби злетіли.'::text,'тримала'::text,'тримає'::text,'тримає'::text,'Вона тримала ріжок із морозивом уже хвилину, коли голуби злетіли.'::text),
(341943,37994,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... el cucurucho de helado durante un minuto cuando las palomas echaron a volar.'::text,'llevaba sosteniendo'::text,'ha estado sosteniendo'::text,'sostiene'::text,'Ella llevaba sosteniendo el cucurucho de helado durante un minuto cuando las palomas echaron a volar.'::text),
(341942,37994,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... le cornet de glace depuis une minute quand les pigeons se sont envolés.'::text,'tenait'::text,'tient'::text,'tient'::text,'Elle tenait le cornet de glace depuis une minute quand les pigeons se sont envolés.'::text),
(341945,37994,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güvercinler havalandığında o bir dakikadır dondurma külahını ...'::text,'tutuyordu'::text,'tutuyor'::text,'tutar'::text,'Güvercinler havalandığında o bir dakikadır dondurma külahını tutuyordu.'::text),
(341946,37994,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő már egy perce ... a fagyitölcsért, amikor a galambok felröppentek.'::text,'tartotta'::text,'tartja'::text,'tartja'::text,'Ő már egy perce tartotta a fagyitölcsért, amikor a galambok felröppentek.'::text),
(364260,40474,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... ein leises Lachen, bevor er anfing zu reisen.'::text,'hatte früher'::text,'hatte'::text,'war gewohnt, zu haben'::text,'Er hatte früher ein leises Lachen, bevor er anfing zu reisen.'::text),
(364264,40474,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... тихий сміх, перш ніж почав подорожувати.'::text,'раніше мав'::text,'мав'::text,'звик мати'::text,'Він раніше мав тихий сміх, перш ніж почав подорожувати.'::text),
(364263,40474,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... una risa tranquila antes de empezar a viajar.'::text,'solía tener'::text,'tenía'::text,'estaba acostumbrado a tener'::text,'Él solía tener una risa tranquila antes de empezar a viajar.'::text),
(364262,40474,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... un rire discret avant de commencer à voyager.'::text,'avait'::text,'avait'::text,'avait l''habitude d''avoir'::text,'Il avait un rire discret avant de commencer à voyager.'::text),
(364265,40474,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O seyahat etmeye başlamadan önce sessiz bir gülüşü ...'::text,'vardı'::text,'vardı'::text,'olmaya alışkındı'::text,'O seyahat etmeye başlamadan önce sessiz bir gülüşü vardı.'::text),
(364266,40474,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neki ... egy halk nevetése, mielőtt elkezdett utazni.'::text,'régen volt'::text,'volt'::text,'hozzá volt szokva, hogy legyen'::text,'Neki régen volt egy halk nevetése, mielőtt elkezdett utazni.'::text),
(399036,44338,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit zehn Minuten durch diesen Tunnel aus Gates. Klar, ein kurzer kleiner Spaziergang.'::text,'läuft'::text,'läuft'::text,'läuft'::text,'Er läuft seit zehn Minuten durch diesen Tunnel aus Gates. Klar, ein kurzer kleiner Spaziergang.'::text),
(399040,44338,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... цим тунелем із гейтів уже десять хвилин. Явно коротенька прогулянка.'::text,'іде'::text,'іде'::text,'ходить'::text,'Він іде цим тунелем із гейтів уже десять хвилин. Явно коротенька прогулянка.'::text),
(399039,44338,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... por este túnel de puertas desde hace diez minutos. Claramente un paseíto corto.'::text,'ha estado caminando'::text,'está caminando'::text,'camina'::text,'Él ha estado caminando por este túnel de puertas desde hace diez minutos. Claramente un paseíto corto.'::text),
(399038,44338,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... dans ce tunnel de portes depuis dix minutes. Clairement une toute petite balade.'::text,'marche'::text,'est en train de marcher'::text,'marche'::text,'Il marche dans ce tunnel de portes depuis dix minutes. Clairement une toute petite balade.'::text),
(399041,44338,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O on dakikadır bu kapı tünelinde ...; belli ki kısacık bir yürüyüş.'::text,'yürüyor'::text,'yürüyor'::text,'yürür'::text,'O on dakikadır bu kapı tünelinde yürüyor; belli ki kısacık bir yürüyüş.'::text),
(399042,44338,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő tíz perce ... ebben a kapukból álló alagútban. Nyilván rövidke séta.'::text,'sétál'::text,'sétál'::text,'sétál'::text,'Ő tíz perce sétál ebben a kapukból álló alagútban. Nyilván rövidke séta.'::text),
(399090,44344,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wusste, dass der Tunnel aus Gates an einer hellen Öffnung ...'::text,'enden würde'::text,'enden wird'::text,'endet'::text,'Er wusste, dass der Tunnel aus Gates an einer hellen Öffnung enden würde.'::text),
(399094,44344,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він знав, що тунель із гейтів ... світлим виходом.'::text,'закінчиться'::text,'закінчиться'::text,'закінчується'::text,'Він знав, що тунель із гейтів закінчиться світлим виходом.'::text),
(399093,44344,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él sabía que el túnel de puertas ... en una abertura luminosa.'::text,'terminaría'::text,'terminará'::text,'está terminando'::text,'Él sabía que el túnel de puertas terminaría en una abertura luminosa.'::text),
(399092,44344,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il savait que le tunnel de portes ... sur une ouverture lumineuse.'::text,'déboucherait'::text,'débouchera'::text,'débouche'::text,'Il savait que le tunnel de portes déboucherait sur une ouverture lumineuse.'::text),
(399095,44344,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, kapı tünelinin aydınlık bir açıklıkta ... biliyordu.'::text,'biteceğini'::text,'biteceğini'::text,'bittiğini'::text,'O, kapı tünelinin aydınlık bir açıklıkta biteceğini biliyordu.'::text),
(399096,44344,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő tudta, hogy a kapukból álló alagút egy világos nyílásnál ...'::text,'fog véget érni'::text,'fog véget érni'::text,'ér véget'::text,'Ő tudta, hogy a kapukból álló alagút egy világos nyílásnál fog véget érni.'::text),
(349590,38844,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der letzte Mann sprang, ... die Dämmerung schon in die Nacht übergegangen.'::text,'war'::text,'ist'::text,'geht'::text,'Als der letzte Mann sprang, war die Dämmerung schon in die Nacht übergegangen.'::text),
(349594,38844,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки стрибнув останній чоловік, сутінки вже ... ніччю.'::text,'змінилися'::text,'змінилися'::text,'змінюються'::text,'Поки стрибнув останній чоловік, сутінки вже змінилися ніччю.'::text),
(349593,38844,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando saltó el último hombre, el anochecer ya se ... en noche.'::text,'había convertido'::text,'ha convertido'::text,'convierte'::text,'Para cuando saltó el último hombre, el anochecer ya se había convertido en noche.'::text),
(349592,38844,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le dernier homme a sauté, le crépuscule ... en nuit.'::text,'s''était changé'::text,'s''est changé'::text,'se change'::text,'Quand le dernier homme a sauté, le crépuscule s''était changé en nuit.'::text),
(349595,38844,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son adam atladığında alacakaranlık geceye ...'::text,'dönmüştü'::text,'döndü'::text,'dönüyor'::text,'Son adam atladığında alacakaranlık geceye dönmüştü.'::text),
(349596,38844,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire az utolsó férfi beugrott, a szürkület ... éjszakába.'::text,'átfordult'::text,'átfordult'::text,'átfordul'::text,'Mire az utolsó férfi beugrott, a szürkület átfordult éjszakába.'::text),
(349626,38848,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Dämmerung, ... Licht schnell schwindet, ist klar die ideale Zeit, um in einen dunklen See zu springen.'::text,'deren'::text,'die'::text,'wenn'::text,'Die Dämmerung, deren Licht schnell schwindet, ist klar die ideale Zeit, um in einen dunklen See zu springen.'::text),
(349630,38848,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сутінки, ... світло швидко згасає, — очевидно, ідеальний час, щоб стрибнути в темне озеро.'::text,'чиє'::text,'які'::text,'коли'::text,'Сутінки, чиє світло швидко згасає, — очевидно, ідеальний час, щоб стрибнути в темне озеро.'::text),
(349629,38848,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El anochecer, ... luz se apaga rápido, es claramente el momento ideal para saltar a un lago oscuro.'::text,'cuya'::text,'que'::text,'cuando'::text,'El anochecer, cuya luz se apaga rápido, es claramente el momento ideal para saltar a un lago oscuro.'::text),
(349628,38848,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le crépuscule, ... la lumière baisse vite, est clairement le moment idéal pour sauter dans un lac sombre.'::text,'dont'::text,'qui'::text,'quand'::text,'Le crépuscule, dont la lumière baisse vite, est clairement le moment idéal pour sauter dans un lac sombre.'::text),
(349631,38848,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Işığı ... hızla sönen alacakaranlık, belli ki karanlık bir göle atlamak için ideal zaman.'::text,''::text,NULL::text,NULL::text,'Işığı hızla sönen alacakaranlık, belli ki karanlık bir göle atlamak için ideal zaman.'::text),
(349632,38848,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szürkület, ... fénye gyorsan halványul, nyilván az ideális időpont, hogy beugorjunk egy sötét tóba.'::text,'amelynek a'::text,'amely'::text,'amikor'::text,'A szürkület, amelynek a fénye gyorsan halványul, nyilván az ideális időpont, hogy beugorjunk egy sötét tóba.'::text),
(351624,39070,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Entdecker ... sich gerade durch die Lianen, als ein Ara über seinen Kopf flog.'::text,'schlug'::text,'schlug'::text,'hat geschlagen'::text,'Der Entdecker schlug sich gerade durch die Lianen, als ein Ara über seinen Kopf flog.'::text),
(351628,39070,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дослідник ... крізь ліани, коли над його головою пролетів ара.'::text,'прорубувався'::text,'прорубався'::text,'прорубався'::text,'Дослідник прорубувався крізь ліани, коли над його головою пролетів ара.'::text),
(351627,39070,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El explorador se ... paso entre las lianas cuando un guacamayo pasó volando sobre su cabeza.'::text,'abría'::text,'abrió'::text,'ha abierto'::text,'El explorador se abría paso entre las lianas cuando un guacamayo pasó volando sobre su cabeza.'::text),
(351626,39070,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''explorateur se ... un chemin à travers les lianes quand un ara est passé au-dessus de sa tête.'::text,'taillait'::text,'tailla'::text,'est taillé'::text,'L''explorateur se taillait un chemin à travers les lianes quand un ara est passé au-dessus de sa tête.'::text),
(351629,39070,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başının üstünden bir ara papağanı uçtuğunda kâşif lianları ...'::text,'kesiyordu'::text,'kesti'::text,'kesmiş'::text,'Başının üstünden bir ara papağanı uçtuğunda kâşif lianları kesiyordu.'::text),
(351630,39070,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A felfedező épp ... magát a liánokon át, amikor egy ara repült el a feje fölött.'::text,'vágta'::text,'átvágta'::text,'átvágta'::text,'A felfedező épp vágta magát a liánokon át, amikor egy ara repült el a feje fölött.'::text),
(399738,44416,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... die Person dieselbe Holztür auf, wie sie es typischerweise tut.'::text,'schließt'::text,'schließt'::text,'schließt'::text,'Morgen um diese Zeit schließt die Person dieselbe Holztür auf, wie sie es typischerweise tut.'::text),
(399742,44416,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра о цій порі суб''єкт ... ті самі дерев''яні двері, як вона зазвичай робить.'::text,'відмикатиме'::text,'відімкне'::text,'відмикає'::text,'Завтра о цій порі суб''єкт відмикатиме ті самі дерев''яні двері, як вона зазвичай робить.'::text),
(399741,44416,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, el sujeto ... la misma puerta de madera, como hace habitualmente.'::text,'estará abriendo'::text,'abrirá'::text,'está abriendo'::text,'Mañana a esta hora, el sujeto estará abriendo la misma puerta de madera, como hace habitualmente.'::text),
(399740,44416,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à cette heure-ci, le sujet ... la même porte en bois, comme elle le fait habituellement.'::text,'sera en train de déverrouiller'::text,'déverrouillera'::text,'déverrouille'::text,'Demain à cette heure-ci, le sujet sera en train de déverrouiller la même porte en bois, comme elle le fait habituellement.'::text),
(399743,44416,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte denek, genellikle yaptığı gibi aynı ahşap kapının kilidini ...'::text,'açıyor olacak'::text,'açacak'::text,'açıyor'::text,'Yarın bu saatte denek, genellikle yaptığı gibi aynı ahşap kapının kilidini açıyor olacak.'::text),
(399744,44416,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor az alany ... ugyanazt a faajtót, ahogy általában szokta.'::text,'nyitja ki'::text,'ki fogja nyitni'::text,'nyitja ki'::text,'Holnap ilyenkor az alany nyitja ki ugyanazt a faajtót, ahogy általában szokta.'::text),
(399819,44425,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die schwarze Tür auf und kramte dann im Schlüsselbund.'::text,'schloss'::text,'schloss'::text,'schloss'::text,'Sie schloss die schwarze Tür auf und kramte dann im Schlüsselbund.'::text),
(399823,44425,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... чорні двері, а потім перебирала в''язку ключів.'::text,'відімкнула'::text,'відмикала'::text,'відмикала'::text,'Вона відімкнула чорні двері, а потім перебирала в''язку ключів.'::text),
(399822,44425,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... la puerta negra y luego rebuscó en el llavero.'::text,'abrió'::text,'había estado abriendo'::text,'estaba abriendo'::text,'Ella abrió la puerta negra y luego rebuscó en el llavero.'::text),
(399821,44425,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la porte noire, puis elle a fouillé dans le trousseau de clés.'::text,'a déverrouillé'::text,'avait déverrouillé'::text,'déverrouillait'::text,'Elle a déverrouillé la porte noire, puis elle a fouillé dans le trousseau de clés.'::text),
(399824,44425,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O siyah kapının kilidini ... ve sonra anahtar destesini karıştırdı.'::text,'açtı'::text,'açıyordu'::text,'açıyordu'::text,'O siyah kapının kilidini açtı ve sonra anahtar destesini karıştırdı.'::text),
(399825,44425,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a fekete ajtót, aztán a kulcscsomóban kotorászott.'::text,'kinyitotta'::text,'nyitogatta'::text,'nyitotta'::text,'Ő kinyitotta a fekete ajtót, aztán a kulcscsomóban kotorászott.'::text),
(360660,40074,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selbstgebackenes Brot schmeckt besser, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Selbstgebackenes Brot schmeckt besser, oder?'::text),
(360664,40074,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Домашній хліб смачніший, ...?'::text,'так?'::text,'так?'::text,'так?'::text,'Домашній хліб смачніший, так?'::text),
(360663,40074,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pan casero sabe mejor, ¿...'::text,'verdad?'::text,'verdad?'::text,'verdad?'::text,'El pan casero sabe mejor, ¿verdad?'::text),
(360662,40074,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pain maison a meilleur goût, ...'::text,'non ?'::text,'non ?'::text,'non ?'::text,'Le pain maison a meilleur goût, non ?'::text),
(360665,40074,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev yapımı ekmeğin tadı daha güzel, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Ev yapımı ekmeğin tadı daha güzel, değil mi?'::text),
(360666,40074,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A házi kenyér finomabb, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'A házi kenyér finomabb, ugye?'::text),
(360714,40080,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätten sie sich nicht für selbstgebackenes Brot entschieden, ... sie jetzt nicht voller Mehl. Klar tragisch.'::text,'wären'::text,'wären gewesen'::text,'werden'::text,'Hätten sie sich nicht für selbstgebackenes Brot entschieden, wären sie jetzt nicht voller Mehl. Klar tragisch.'::text),
(360718,40080,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вони не обрали домашній хліб, зараз ... в борошні. Явно трагедія.'::text,'не були б'::text,'не були б'::text,'не будуть'::text,'Якби вони не обрали домашній хліб, зараз не були б в борошні. Явно трагедія.'::text),
(360717,40080,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ellos no hubieran elegido pan casero, ahora ... cubiertos de harina. Claramente trágico.'::text,'no estarían'::text,'no habrían estado'::text,'no estarán'::text,'Si ellos no hubieran elegido pan casero, ahora no estarían cubiertos de harina. Claramente trágico.'::text),
(360716,40080,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils n''avaient pas choisi le pain maison, ils ... couverts de farine maintenant. Clairement tragique.'::text,'ne seraient pas'::text,'n''auraient pas été'::text,'ne seront pas'::text,'S''ils n''avaient pas choisi le pain maison, ils ne seraient pas couverts de farine maintenant. Clairement tragique.'::text),
(360719,40080,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar ev yapımı ekmeği seçmeseydi, şimdi una bulanmış ...; belli ki çok trajik.'::text,'olmazlardı'::text,'olmamış olurlardı'::text,'olmayacaklar'::text,'Onlar ev yapımı ekmeği seçmeseydi, şimdi una bulanmış olmazlardı; belli ki çok trajik.'::text),
(360720,40080,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ők nem a házi kenyeret választották volna, most nem ... csupa liszt. Nyilván tragikus.'::text,'lennének'::text,'lettek volna'::text,'lesznek'::text,'Ha ők nem a házi kenyeret választották volna, most nem lennének csupa liszt. Nyilván tragikus.'::text),
(360165,40019,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit zehn Minuten über dasselbe urkomische Video.'::text,'lacht'::text,'lacht'::text,'lacht'::text,'Er lacht seit zehn Minuten über dasselbe urkomische Video.'::text),
(360169,40019,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... з того самого кумедного відео вже десять хвилин.'::text,'сміється'::text,'сміється'::text,'сміється'::text,'Він сміється з того самого кумедного відео вже десять хвилин.'::text),
(360168,40019,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... con el mismo vídeo divertidísimo desde hace diez minutos.'::text,'ha estado riéndose'::text,'se está riendo'::text,'se ríe'::text,'Él ha estado riéndose con el mismo vídeo divertidísimo desde hace diez minutos.'::text),
(360167,40019,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... de la même vidéo hilarante depuis dix minutes.'::text,'rit'::text,'est en train de rire'::text,'rit'::text,'Il rit de la même vidéo hilarante depuis dix minutes.'::text),
(360170,40019,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O on dakikadır aynı komik videoya ...'::text,'gülüyor'::text,'gülüyor'::text,'güler'::text,'O on dakikadır aynı komik videoya gülüyor.'::text),
(360171,40019,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő tíz perce ... ugyanazon a vicces videón.'::text,'nevet'::text,'nevet'::text,'nevet'::text,'Ő tíz perce nevet ugyanazon a vicces videón.'::text),
(360192,40022,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich wünschte, dieses urkomische Video ... nie in der Vorlesung aufgetaucht! Totales Chaos!'::text,'wäre'::text,'ist'::text,'würde'::text,'Ich wünschte, dieses urkomische Video wäre nie in der Vorlesung aufgetaucht! Totales Chaos!'::text),
(360196,40022,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ж те кумедне відео ... ніколи не з''явилося на лекції! Повний хаос!'::text,''::text,NULL::text,NULL::text,'Якби ж те кумедне відео ніколи не з''явилося на лекції! Повний хаос!'::text),
(360195,40022,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ojalá ese vídeo tan gracioso no ... aparecido nunca en la clase! ¡Caos total!'::text,'hubiera'::text,'ha'::text,'habría'::text,'¡Ojalá ese vídeo tan gracioso no hubiera aparecido nunca en la clase! ¡Caos total!'::text),
(360194,40022,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si seulement cette vidéo hilarante ... jamais apparue en cours ! Chaos total !'::text,'n''était'::text,'n''est'::text,'ne serait'::text,'Si seulement cette vidéo hilarante n''était jamais apparue en cours ! Chaos total !'::text),
(360197,40022,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke o komik video derste hiç ...! Tam bir kaos!'::text,'görünmeseydi'::text,'görünmedi'::text,'görünmezdi'::text,'Keşke o komik video derste hiç görünmeseydi! Tam bir kaos!'::text),
(360198,40022,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak az a vicces videó soha ... meg az előadáson! Teljes káosz!'::text,'nem jelent volna'::text,'nem jelent'::text,'nem jelenne'::text,'Bárcsak az a vicces videó soha nem jelent volna meg az előadáson! Teljes káosz!'::text),
(363090,40344,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hammer ist gefallen, also ... die Richterin ihre Entscheidung getroffen haben.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Der Hammer ist gefallen, also muss die Richterin ihre Entscheidung getroffen haben.'::text),
(363094,40344,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Молоток опустився, тож суддя ... ухвалити своє рішення.'::text,'мусила'::text,'мала'::text,'не могла'::text,'Молоток опустився, тож суддя мусила ухвалити своє рішення.'::text),
(363093,40344,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El mazo ha caído, así que la jueza ... tomado su decisión.'::text,'debe de haber'::text,'debería haber'::text,'no puede haber'::text,'El mazo ha caído, así que la jueza debe de haber tomado su decisión.'::text),
(363092,40344,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le marteau est tombé, donc la juge ... prendre sa décision.'::text,'a dû'::text,'aurait dû'::text,'n''a pas pu'::text,'Le marteau est tombé, donc la juge a dû prendre sa décision.'::text),
(363095,40344,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tokmak indi, yani hâkim kararını ...'::text,'vermiş olmalı'::text,'vermeliydi'::text,'vermiş olamaz'::text,'Tokmak indi, yani hâkim kararını vermiş olmalı.'::text),
(363096,40344,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kalapács lecsapott, szóval a bíró ... a döntését.'::text,'biztosan meghozta'::text,'meg kellett volna hoznia'::text,'nem hozhatta meg'::text,'A kalapács lecsapott, szóval a bíró biztosan meghozta a döntését.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
commit;
